import{a as e}from"./jsx-runtime-Bzw2jH9X.js";var t=e({default:()=>n}),n=JSON.parse(`[{"id":"qx-a1-001","clusterId":"A","werkstueckRef":"A.1.1","stufe":1,"question":"Bei einem Streit um die Ursache eines Phänomens sagt jemand: „Nach Ockhams Rasiermesser ist die einfachste Erklärung die wahre, also ist jede Erklärung mit mehr Annahmen damit widerlegt.“ Was ist an dieser Schlussfolgerung falsch?","options":["Das Sparsamkeitsprinzip gilt als Priorisierungswerkzeug und legt nur fest, welche Erklärung man zuerst prüft, ohne deren Wahrheit zu beweisen.","Das Sparsamkeitsprinzip gilt als Naturgesetz und bestätigt deshalb stets die Erklärung mit den wenigsten Annahmen als die tatsächlich zutreffende.","Das Sparsamkeitsprinzip gilt als Beweisverfahren und widerlegt deshalb jede Erklärung, die mehr Annahmen benötigt als eine konkurrierende.","Das Sparsamkeitsprinzip gilt als Verständlichkeitstest und verwirft deshalb jede Erklärung, die ein Laie nicht auf Anhieb nachvollziehen kann."],"correctIndex":0,"explanation":"Die Schlussfolgerung verwechselt ein Priorisierungswerkzeug mit einem Beweis. Das Sparsamkeitsprinzip sagt nur, welche Erklärung man zuerst prüfen sollte: die mit den wenigsten unbewiesenen Annahmen. Dass sie zutrifft, folgt daraus nicht. Eine Erklärung mit mehr Annahmen ist damit nicht widerlegt, sondern nur die schlechtere Ausgangsbasis.","coreRule":"⚡ Sparsamkeit sortiert Hypothesen nach ihren unbewiesenen Annahmen: Sie ist ein Priorisierungswerkzeug, kein Wahrheitsbeweis.","quote":"Man sollte nicht mehr Ursachen zur Erklärung heranziehen, als unbedingt notwendig sind.","quoteLabel":"Merksatz:","beleg":"Werkstück A.1.1 (Kontext & Tiefe; Der Kipppunkt)","status":"entwurf","scenario":"","kurz":"Das Sparsamkeitsprinzip sagt nur, welche Erklärung man zuerst prüfen sollte, nämlich die mit den wenigsten unbewiesenen Annahmen. Der Fehler liegt darin, aus „zuerst prüfen“ ein „wahr“ zu machen: Eine Erklärung mit mehr Annahmen ist so nicht widerlegt.","prueffrage":"Was müsste man beobachten, um eine Erklärung wirklich zu widerlegen, und kommt so etwas in dem Satz überhaupt vor?","rueckmeldung":[{"option":1,"text":"Dass sparsame Erklärungen oft ein guter Anfang sind, macht das Prinzip noch nicht zum Naturgesetz. Es ist eine methodische Faustregel, und dass die Erklärung mit den wenigsten Annahmen tatsächlich zutrifft, folgt daraus keineswegs."},{"option":2,"text":"Wer das Prinzip für ein Beweisverfahren hält, wiederholt den Fehler des Satzes, statt ihn zu finden. Es ordnet Erklärungen nur: Wer mehr Annahmen braucht, startet schlechter, ist deshalb aber nicht widerlegt."},{"option":3,"text":"Beim Sparsamkeitsprinzip zählen unbewiesene Annahmen, nicht die Verständlichkeit für Laien. Eine einfache Erklärung muss nicht leicht zu verstehen sein, und verworfen wird durch das Prinzip ohnehin nichts: Es legt nur die Prüfreihenfolge nahe."}],"familie":"sparsamste-erklaerung","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"Baker, A.: Simplicity. Stanford Encyclopedia of Philosophy (überarb. 16.05.2022), Abschn. 1–2","oeffentlich":true,"url":"https://plato.stanford.edu/entries/simplicity/","abruf":"2026-10-12"},{"typ":"doi","kurz":"Thorburn, W. M. (1918): The Myth of Occam's Razor. Mind 27(3), 345–353","oeffentlich":false,"doi":"10.1093/mind/XXVII.3.345"}],"thema":"Geschichte und Wissenschaft"},{"id":"qx-a1-002","clusterId":"A","werkstueckRef":"A.1.1","stufe":2,"question":"Welche Ursache solltest du zuerst prüfen, und warum?","scenario":"Abends fällt dein WLAN aus, alle Geräte sind betroffen. Gestern lief noch alles. Du willst nicht wahllos suchen.","options":["Einen gezielten Angriff auf dein Heimnetz, weil diese Erklärung auch spätere Ausfälle mit abdecken würde.","Einen gezielten Angriff auf dein Heimnetz, weil erst sein Ausschluss die Suche nach harmloseren Gründen lohnt.","Einen hängenden Router oder eine Störung beim Anbieter, weil dafür keine neuen Annahmen nötig sind.","Einen gleichzeitigen Defekt aller Endgeräte, weil der Ausfall wirklich jedes Gerät im Haushalt betrifft."],"correctIndex":2,"explanation":"Ein hängender Router oder eine Anbieterstörung braucht nichts Neues: Geräte fallen aus, das weiß jeder. Ein Cyberangriff dagegen setzt einen Angreifer, ein Motiv und eine Möglichkeit voraus, die du erst belegen müsstest, und ein gleichzeitiger Defekt aller Geräte verlangt viele voneinander unabhängige Zufälle. Dass eine Erklärung mehr abdecken oder schwerer wiegen würde, macht sie nicht sparsamer: Sparsam heißt, mit den wenigsten unbewiesenen Annahmen auszukommen. Das ist eine Reihenfolge der Prüfung, kein Beweis: Hilft ein Neustart des Routers nicht und meldet der Anbieter keine Störung, rücken die nächstsparsamen Erklärungen nach, die exotischen erst am Ende.","coreRule":"⚡ Starte bei der Ursache, die nur Bekanntes voraussetzt, und erst danach bei den exotischen.","beleg":"Werkstück A.1.1 (Anwendung & Relevanz: Im Alltag, Fehlerdiagnose)","status":"entwurf","kurz":"Zuerst prüfst du, was keine neuen Annahmen braucht: Dass ein Router hängt oder der Anbieter eine Störung hat, kennt jeder. Ein Angriff wäre erst zu belegen und rückt ans Ende. Das ist eine Reihenfolge der Prüfung, kein Beweis.","prueffrage":"Was weißt du sicher über den Ausfall: Welche Geräte sind betroffen, und was hat sich seit gestern geändert?","rueckmeldung":[{"option":0,"text":"Dass eine Erklärung auch spätere Ausfälle abdecken würde, macht sie nicht sparsamer. Sparsam ist die Erklärung mit den wenigsten unbewiesenen Annahmen, und ein Angriff verlangt Angreifer, Motiv und Möglichkeit, die erst zu belegen wären."},{"option":1,"text":"Das Schlimmste zuerst auszuschließen wirkt vorsichtig. Doch ein Angriff braucht viele unbelegte Annahmen, und wie schwer eine Ursache wöge, sagt nichts darüber, wie wahrscheinlich sie ist; harmlose Gründe lohnen die Suche sofort."},{"option":3,"text":"Dass alle Geräte betroffen sind, ist ein wichtiger Hinweis, spricht aber gegen viele Einzeldefekte: Sie müssten unabhängig voneinander zur selben Zeit auftreten. Ein hängender Router erklärt dasselbe mit einer einzigen Annahme."}],"familie":"sparsamste-erklaerung","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"Baker, A.: Simplicity. Stanford Encyclopedia of Philosophy (überarb. 16.05.2022), Abschn. 2","oeffentlich":true,"url":"https://plato.stanford.edu/entries/simplicity/","abruf":"2026-10-12"}],"thema":"Technik und KI"},{"id":"qx-a1-003","clusterId":"A","werkstueckRef":"A.1.1","stufe":3,"question":"Was ist an dieser Berufung auf das Prinzip der Sparsamkeit falsch?","scenario":"In einer Diskussion sagt jemand: „Nach dem Prinzip der Sparsamkeit ist die einfachere Erklärung besser. Newtons Physik versteht jeder, die Relativitätstheorie fast niemand – also gilt Newton.“","options":["Das Prinzip betrifft nur Alltagsfragen, nicht physikalische Theorien mit Messdaten, daher ist der Vergleich der beiden Theorien unzulässig.","Das Prinzip bemisst Sparsamkeit an der Zahl der Annahmen, nicht an der Verständlichkeit, und Newton erklärt manche Messungen nur mit Zusatzannahmen.","Das Prinzip verlangt immer die kompliziertere Theorie, weil sie mehr Daten abdeckt und jede zusätzliche Regel einen weiteren Datenpunkt erklärt.","Das Prinzip greift erst, wenn eine der beiden Theorien durch Experimente widerlegt ist, weil es vorher keinen Maßstab für den Vergleich gibt."],"correctIndex":1,"explanation":"„Einfach“ bedeutet beim Prinzip der Sparsamkeit „wenige Annahmen“, nicht „leicht zu verstehen“. Die Relativitätstheorie ist konzeptionell anspruchsvoll, doch Newtons Physik erklärt manche Messungen nur mit eigens angefügten Zusatzannahmen oder gar nicht genau, etwa die Periheldrehung des Merkur. Wer „einfach“ mit „leicht verständlich“ verwechselt, wählt am Ende die Erklärung, die wichtige Daten ignoriert, und macht aus dem Werkzeug zur Priorisierung von Hypothesen ein Scheinargument.","coreRule":"⚡ Eine einfache Erklärung, die der Hälfte der Beweise widerspricht, ist nicht besser als eine komplexere Erklärung, die alle Beweise integriert.","quote":"„Einfach“ bedeutet „wenige Annahmen“, nicht „leicht zu verstehen“.","quoteLabel":"Typische Aussage:","beleg":"Werkstück A.1.1 (Der Kipppunkt)","status":"entwurf","kurz":"„Einfach“ heißt beim Prinzip der Sparsamkeit „wenige Annahmen“, nicht „leicht zu verstehen“. Die Relativitätstheorie ist schwer zu begreifen, doch Newtons Physik erklärt manche Messungen, etwa am Merkur, nur mit eigens angefügten Zusatzannahmen oder gar nicht genau.","prueffrage":"Gibt es Messungen, bei denen Newtons Physik und die Relativitätstheorie Verschiedenes vorhersagen, und welche liegt dort richtig?","rueckmeldung":[{"option":0,"text":"Messdaten spielen bei physikalischen Theorien eine große Rolle, doch das Prinzip lässt sich auch hier anwenden und auf beide Theorien beziehen. Der Fehler liegt im Verständnis von „einfach“, nicht im Anwendungsbereich."},{"option":2,"text":"Mehr abgedeckte Daten zählen tatsächlich für eine Theorie. Das Prinzip bevorzugt aber die mit weniger Annahmen, und eine Sonderregel, die eigens für einen Datenpunkt eingeführt wird, flickt nur eine Lücke, statt etwas vorherzusagen."},{"option":3,"text":"Dass Experimente am Ende entscheiden, stimmt. Ist eine Theorie aber widerlegt, braucht es kein Sparsamkeitsprinzip mehr; es hilft gerade vorher, Hypothesen zu ordnen. Der Fehler liegt darin, was hier als „einfach“ gilt."}],"familie":"sparsamste-erklaerung","fertigkeit":"F4","quellen":[{"typ":"doi","kurz":"Will, C. M. (2014): The Confrontation between General Relativity and Experiment. Living Reviews in Relativity 17, 4 (Abschn. „The perihelion shift of Mercury“)","oeffentlich":true,"doi":"10.12942/lrr-2014-4","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC5255900/","abruf":"2026-10-12"},{"typ":"url","kurz":"Baker, A.: Simplicity. Stanford Encyclopedia of Philosophy (überarb. 16.05.2022)","oeffentlich":true,"url":"https://plato.stanford.edu/entries/simplicity/","abruf":"2026-10-12"}],"thema":"Geschichte und Wissenschaft"},{"id":"qx-a1-004","clusterId":"A","werkstueckRef":"A.1.1","stufe":4,"question":"Was ist an diesem Argument der Ärztin fehlerhaft?","scenario":"Zwei Patienten kommen mit Fieber und Husten. Patientin 1 war seit Monaten nicht verreist. Patient 2 kam, wie belegt ist, vor zwei Wochen aus den Tropen zurück. Eine Ärztin sagt: „Erkältung ist bei beiden die sparsamste Erklärung, denn sie ist die häufigste.“","options":["Sie setzt „sparsam“ mit „häufig“ gleich, obwohl sich die Sparsamkeit nach den unbelegten Annahmen im Einzelfall richtet.","Sie vergisst, dass eine belegte Reise die Tropenkrankheit zur sicheren Diagnose macht und die Erkältung ausschließt.","Sie übersieht, dass das Sparsamkeitsprinzip nur in der Naturwissenschaft gilt und auf Diagnosen nicht übertragbar ist.","Sie wählt für beide Fälle dieselbe Erklärung, obwohl nach dem Sparsamkeitsprinzip eine Erklärung immer die andere ausschließt."],"correctIndex":0,"explanation":"Sparsam heißt „wenige neue, unbelegte Annahmen“. Bei Patientin 1 braucht eine Tropenkrankheit eine zusätzliche, unbelegte Annahme (eine unbemerkte Reise), deshalb liegt die Erkältung vorn. Bei Patient 2 ist die Reise belegt, diese Annahme entfällt, und die Tropenkrankheit rückt in die engere Wahl. Die Ärztin beachtet das nicht und wendet für beide dieselbe Erklärung an. Das Sparsamkeitsprinzip ist ein Werkzeug zur Priorisierung, kein Beweis: Die Tropenkrankheit gilt damit nicht als bewiesen, die Erkältung nicht als ausgeschlossen.","coreRule":"⚡ Sparsam heißt „wenige unbelegte Annahmen“, nicht „häufig“: Wird eine Zusatzannahme belegt, verschiebt sich die Rangfolge.","beleg":"Werkstück A.1.1 (Anwendung & Relevanz: In der Medizin; Der Kipppunkt)","status":"entwurf","kurz":"Sparsam heißt „wenige unbelegte Annahmen“, nicht „häufig“. Bei Patient 2 ist die Reise belegt, diese Annahme entfällt, und eine Tropenkrankheit rückt in die engere Wahl, ohne damit schon bewiesen zu sein.","prueffrage":"Worin unterscheiden sich die Vorgeschichten der beiden, und welcher Unterschied ist belegt?","rueckmeldung":[{"option":1,"text":"Die belegte Reise stärkt den Verdacht auf eine Tropenkrankheit tatsächlich. Sie macht ihn aber nicht zur sicheren Diagnose: Das Prinzip ordnet nur die Reihenfolge der Verdachtsdiagnosen, und eine Erkältung bleibt weiterhin möglich."},{"option":2,"text":"Eine klare Grenze zwischen Naturwissenschaft und Medizin wirkt ordentlich, trägt hier aber nicht: Auch in der Medizin dient Sparsamkeit als Faustregel, um Verdachtsdiagnosen zu ordnen. Der Fehler liegt in der Anwendung, nicht im Gebiet."},{"option":3,"text":"Dieselbe Erklärung für zwei Fälle zu wählen ist an sich nicht verboten, und Sparsamkeit schließt auch keine andere Erklärung aus. Entscheidend ist, dass sich die Annahmenlage der beiden Fälle unterscheidet und die Ärztin das nicht berücksichtigt."}],"familie":"sparsamste-erklaerung","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"Baker, A.: Simplicity. Stanford Encyclopedia of Philosophy (überarb. 16.05.2022), Abschn. 4 (Sober)","oeffentlich":true,"url":"https://plato.stanford.edu/entries/simplicity/","abruf":"2026-10-12"}],"thema":"Gesundheit"},{"id":"qx-a1-005","clusterId":"A","werkstueckRef":"A.1.2","stufe":1,"question":"Du schreibst einer Kollegin eine dringende Nachricht. Sie antwortet den ganzen Tag nicht. Eine andere Kollegin sagt: „Die ignoriert dich absichtlich, die kann dich eben nicht leiden.“ Du weißt: Die Kollegin war schon immer freundlich zu dir, und heute sind im Haus mehrere Systeme ausgefallen. Welche Reaktion ist am vernünftigsten?","options":["Die ausbleibende Antwort als Hinweis auf eine schlechte Beziehung werten und ab sofort nur noch das Nötigste mit ihr besprechen.","Die Erklärung der anderen Kollegin zunächst ernst nehmen, weil sie die Schweigende vielleicht besser kennt als du.","Freundlich nachfragen, ob die Nachricht angekommen ist, bevor du ihr eine Absicht unterstellst.","Warten, bis die Kollegin sich von selbst meldet, und ihr Schweigen bis dahin als Beleg gegen sie sammeln."],"correctIndex":2,"explanation":"Ein einzelnes Schweigen sagt wenig über die Absicht dahinter. Eine böse Absicht erfordert mehrere Annahmen (etwa: Die Kollegin ist böswillig, verstellt sich und plant aktiv gegen dich). Gegen eine solche Absicht spricht ihr bisheriges Verhalten. Für Panne, Überlastung oder Zufall genügt eine einzige Annahme: Technische Systeme fallen aus. Die Systemausfälle im Haus machen diese Erklärung sogar wahrscheinlich. Wer Charakter und Motive unterstellt, übersieht leicht die Umstände, die er bei sich selbst sofort anführen würde. Die sparsamste Erklärung zuerst zu prüfen heißt nicht, Absicht für unmöglich zu halten. Wiederholt sich das Muster, ändert sich die Lage. Hier ist die Nachfrage der erste Schritt.","coreRule":"⚡ Bevor du eine Absicht unterstellst, frag nach den Umständen – so wie du es bei dir selbst tust.","beleg":"Werkstück A.1.2 (Kontext & Tiefe; Verbindungen: Verwandter Bug)","status":"entwurf","scenario":"","kurz":"Ein einzelnes Schweigen sagt wenig über die Absicht dahinter. Für Pech oder Überlastung genügt eine Annahme, für Böswilligkeit braucht es mehrere, und ihr bisheriges Verhalten spricht dagegen. Also zuerst die einfache Erklärung prüfen: nachfragen.","prueffrage":"Worauf stützt die andere Kollegin ihr Urteil, und was weißt du selbst über das bisherige Verhalten der Kollegin?","rueckmeldung":[{"option":0,"text":"Ein einzelner Tag ohne Antwort ist ein dünner Anlass für eine dauerhafte Distanz. Dagegen sprechen ihr bisher freundliches Verhalten und die Ausfälle im Haus. Anders sähe es aus, wenn sich das Schweigen wiederholte."},{"option":1,"text":"Vielleicht kennt sie die Kollegin tatsächlich besser, doch sie nennt nur eine Absicht, ohne etwas dafür anzuführen. Was du selbst weißt, spricht dagegen: ihre Freundlichkeit bisher und der Ausfall der Systeme."},{"option":3,"text":"Abwarten wirkt fair, doch wer ihr Schweigen als Beleg sammelt, sucht schon nach Bestätigung für die Unterstellung. Ein Einzelfall wird nicht zum Muster, nur weil man ihn aufhebt; eine kurze Nachfrage klärt mehr."}],"familie":"umstaende-vor-absicht","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Gilbert, D. T.; Malone, P. S. (1995): The Correspondence Bias. Psychological Bulletin 117(1), 21–38 (Autorenkopie, Harvard)","oeffentlich":true,"url":"https://dtg.sites.fas.harvard.edu/Gilbert%20%26%20Malone%20%28CORRESPONDENCE%20BIAS%29.pdf","seite":"21","abruf":"2026-10-12"},{"typ":"url","kurz":"Quote Investigator: Never Attribute to Malice That Which Is Adequately Explained by Stupidity (30.12.2016, aktual. 18.04.2025)","oeffentlich":true,"url":"https://quoteinvestigator.com/2016/12/30/not-malice/","abruf":"2026-10-12"},{"typ":"doi","kurz":"Malle, B. F. (2006): The Actor–Observer Asymmetry in Attribution: A (Surprising) Meta-Analysis. Psychological Bulletin 132(6), 895–919","oeffentlich":false,"doi":"10.1037/0033-2909.132.6.895"}],"thema":"Zusammenleben"},{"id":"qx-a1-006","clusterId":"A","werkstueckRef":"A.1.2","stufe":2,"question":"Welcher nächste Schritt ist hier am vernünftigsten?","scenario":"Dein Partner hat vergessen, die Milch mitzubringen. Dein erster Gedanke: „Meine Bedürfnisse sind ihm egal.“ Es ist das erste Mal, dass so etwas passiert, und er kam heute spät und erschöpft von der Arbeit.","options":["Zuerst harmlose Erklärungen durchgehen – müde, abgelenkt, den Einkauf vergessen –, bevor du aus einem einzelnen Vorfall auf Gleichgültigkeit schließt.","Deinem ersten Gefühl vertrauen, denn wenn sich etwas nach Gleichgültigkeit anfühlt, ist es das meistens auch, und entsprechend reagieren.","Den Vorfall als Absicht deuten und beim nächsten Mal Gleiches mit Gleichem vergelten, damit die Botschaft auch ankommt.","Gar nichts schlussfolgern und den Vorfall aus jeder Bewertung streichen, solange sich seine Ursache nicht lückenlos beweisen lässt."],"correctIndex":0,"explanation":"Ein einzelnes vergessenes Mitbringsel lässt viele Ursachen zu: Müdigkeit, Ablenkung, Stress, ein übersehener Zettel. Dass ihm deine Bedürfnisse egal sind, wäre dagegen eine Annahme über Absicht und Charakter, für die ein einziger Vorfall kaum etwas belegt. Wer daraus sofort auf Gleichgültigkeit schließt, überschätzt leicht den Charakter und unterschätzt die Umstände, zumal nach einem erschöpfenden Arbeitstag. Das ist keine Naivität: Häufen sich solche „Fehler“ und treffen immer nur dich, wird Absicht plausibler. Einen lückenlosen Beweis braucht es dafür nicht, den gibt es im Alltag fast nie; Gefühl und Vergeltung dagegen ersetzen die Prüfung durch Stimmung und eine unbelegte Annahme.","coreRule":"⚡ Aus einem einzelnen Ereignis folgt keine Absicht – prüfe zuerst die harmlose Erklärung.","beleg":"Werkstück A.1.2 (Anwendung & Relevanz: In persönlichen Beziehungen)","status":"entwurf","kurz":"Ein einzelnes Vergessen lässt viele Ursachen zu, besonders nach einem erschöpfenden Tag. Wer sofort auf Gleichgültigkeit schließt, überschätzt leicht den Charakter und unterschätzt die Umstände; erst die harmlosen Erklärungen zu prüfen ist vernünftiger.","prueffrage":"Was müsste über längere Zeit geschehen, damit „Meine Bedürfnisse sind ihm egal“ eine gut gestützte Deutung wäre?","rueckmeldung":[{"option":1,"text":"Das Gefühl zeigt, dass dich etwas getroffen hat, und das darf man ernst nehmen. Als Beleg für Gleichgültigkeit reicht es aber nicht: Es ersetzt die Prüfung durch Stimmung und sagt nichts darüber, was bei ihm tatsächlich los war."},{"option":2,"text":"Vergeltung wirkt wie eine klare Grenze, baut aber auf einer unbelegten Annahme über seine Absicht auf. Beim ersten Vorfall nach einem erschöpfenden Tag würde sie einen Streit auslösen, für den es noch keinen Grund gibt."},{"option":3,"text":"Mit dem Urteil zurückhaltend zu sein, ist richtig. Einen lückenlosen Beweis zu verlangen, geht aber zu weit, denn den gibt es im Alltag fast nie. Besser: die harmloseste Erklärung zuerst prüfen und auf eine Häufung achten."}],"familie":"umstaende-vor-absicht","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Gilbert, D. T.; Malone, P. S. (1995): The Correspondence Bias. Psychological Bulletin 117(1), 21–38 (Autorenkopie, Harvard)","oeffentlich":true,"url":"https://dtg.sites.fas.harvard.edu/Gilbert%20%26%20Malone%20%28CORRESPONDENCE%20BIAS%29.pdf","seite":"21","abruf":"2026-10-12"}],"thema":"Zusammenleben"},{"id":"qx-a1-007","clusterId":"A","werkstueckRef":"A.1.2","stufe":3,"question":"Wie solltest du das Muster einschätzen und was ist deine beste nächste Reaktion?","scenario":"Ein Kollege vergisst zum dritten Mal, dir einen Termin weiterzuleiten. Jedes Mal geht die Panne zu deinem Nachteil und zu seinem Vorteil aus.","options":["Du bleibst bei der Zufallserklärung, denn solange niemand zugibt, dass er es mit Absicht tut, darfst du nie etwas anderes unterstellen.","Du nimmst den Verdacht auf Absicht ernst und prüfst ihn, denn ein Muster zugunsten nur einer Seite ist mit Zufall kaum erklärbar.","Du nimmst ab dem zweiten Vorfall als bewiesen an, dass er böse Absicht hat, denn Zufall kann sich nie wiederholen.","Du unterstellst Absicht nur bei Fremden, denn bei Kollegen im selben Büro gelten für die Einschätzung andere Regeln."],"correctIndex":1,"explanation":"Die Faustregel, Böswilligkeit nicht zu unterstellen, wo Dummheit oder Zufall genügen, ist ein sinnvoller Startpunkt, aber keine Denkverbotszone. Der Kipppunkt ist erreicht, wenn ein wiederholtes Muster von „Fehlern“ immer nur einer Partei zugutekommt und der anderen schadet: Einmal ist ein Fehler, zweimal ein Zufall, dreimal feindliche Handlung (oder zumindest grobe Fahrlässigkeit, die an Vorsatz grenzt). Genau das trifft hier zu, denn die Panne geht jedes Mal zu deinem Nachteil und zu seinem Vorteil aus. Das beweist noch keine Absicht, macht sie aber zu einer ernsthaften Möglichkeit, die du nicht einfach als Zufall abtun solltest. Sinnvoll wäre es zum Beispiel, das Muster genauer zu prüfen, etwa durch Nachfragen oder schriftliche Bestätigungen. Hanlons Rasiermesser ist ein Werkzeug für die erste Analyse, nicht für die abschließende Beurteilung. Überzogen wäre es, schon beim zweiten Vorfall Absicht für bewiesen zu halten, und naiv, trotz des Musters stur beim Zufall zu bleiben. Wer ein Muster ignoriert, nur weil kein Geständnis vorliegt, schützt im Zweifel genau jene, die systematisch profitieren.","coreRule":"⚡ Die Faustregel „Zufall vor Absicht“ ist ein Startpunkt, kein Schutzschild: Ein Muster, das stets derselben Seite nützt, verdient eine ernste Prüfung auf Absicht.","quote":"","quoteLabel":"","beleg":"Werkstück A.1.2 (Der Kipppunkt)","status":"entwurf","kurz":"Ein Muster, das immer nur dir schadet und ihm nützt, ist mit Zufall schlecht erklärbar. Es beweist noch keine Absicht, macht sie aber zu einer ernsten Möglichkeit, die du prüfen solltest, statt sie vorschnell abzutun.","prueffrage":"Wie viele Termine hat er dir insgesamt richtig weitergeleitet, und wie oft passieren ihm solche Fehler bei anderen?","rueckmeldung":[{"option":0,"text":"Nicht vorschnell Böses zu unterstellen, ist ein guter Anfang. Wenn aber nur ein Geständnis die Sicht ändern darf, wird die Zufallserklärung unwiderlegbar, und ein einseitiges Muster zählt dann nichts mehr."},{"option":2,"text":"Ein Verdacht ist nach mehreren einseitigen Pannen berechtigt. Ein Beweis ist das Muster aber nicht, nur ein Grund zur Prüfung. Und zweimal kann durchaus noch Zufall sein, Wiederholung allein bestätigt keine Absicht."},{"option":3,"text":"Ob man ein Muster ernst nimmt, hängt an dem, was passiert: wiederholt, einseitig, zu wessen Vorteil. Die Beziehung zur Person ändert die Beweislage nicht, auch wenn man Bekannten gern erst einmal wohlwollend begegnet."}],"familie":"umstaende-vor-absicht","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Quote Investigator: Never Attribute to Malice That Which Is Adequately Explained by Stupidity (30.12.2016, aktual. 18.04.2025)","oeffentlich":true,"url":"https://quoteinvestigator.com/2016/12/30/not-malice/","abruf":"2026-10-12"}],"thema":"Zusammenleben"},{"id":"qx-a1-008","clusterId":"A","werkstueckRef":"A.1.2","stufe":4,"question":"Auf einer Zitatseite steht: „Hanlons Rasiermesser stammt von Robert J. Hanlon, 1980.“ Du willst wissen, wie belastbar diese Zuschreibung ist. Welche Schlussfolgerung ist angemessen?","options":["Die Urheberschaft ist ungeklärt: Der Name ist eine eingeführte Bezeichnung, aber kein Beleg dafür, wer den Gedanken zuerst formuliert hat.","Hanlon ist der Urheber: Dass der Name seit 1980 unter dem Satz steht und eine spätere Quelle ihn nennt, belegt seine Autorschaft eindeutig.","Heinlein ist der Urheber: Dass sein Satz von 1941 älter ist als der Abdruck von 1980, macht den Namen Hanlon zu einer grundlosen Erfindung.","Die Zuschreibung ist unerheblich: Ein bekannter Name zeigt, dass der Satz stimmt, und die Frage nach dem Urheber ändert daran nichts."],"correctIndex":0,"explanation":"Ein Name an einem Satz ist noch kein Beleg für seinen Urheber. Der Abdruck von 1980 nennt keinen Einsender; die Behauptung, ein Robert J. Hanlon habe ihn geschickt, stammt erst von 2001 (eine im Blog weitergegebene E-Mail, die sich auf Credits der Sammlung beruft, die sich nicht finden lassen) und kann den fehlenden Beleg nicht ersetzen. Gleichzeitig ist es voreilig, nun Heinlein als gesicherten Urheber auszurufen: Die sinngleichen Formulierungen bei Heinlein (1941) und Wells (1896) zeigen nur, dass es ältere Formulierungen gibt, nicht, wer den Gedanken zuerst gesagt hat. Der Name kann als eingeführte Bezeichnung bleiben; ob er auch den Urheber bezeichnet, ist offen. Und ob der Gedanke taugt, hängt nicht davon ab, wer ihn zuerst gesagt hat, sondern davon, ob er einer Prüfung standhält.","coreRule":"⚡ Ein eingeführter Name ist kein Urheberbeleg – prüfe, wer etwas wann zuerst gesagt hat, und halte offen, was sich nicht belegen lässt.","beleg":"Werkstück A.1.2; Fn. ga-hanlon (Bloch 1980, S. 52; O’Toole 2016; Jargon File 1990; Heinlein 1941; Wells 1896). Von Sturm am 12.10.2026 im Buch geprüft (Preface, Acknowledgements and Permissions, S. 52): Weder beim Spruch noch an anderer Stelle wird ein Einsender genannt.. Früheste Nennung Hanlons: Stafford-Fraser, Q. (26.11.2001): Hanlon’s Razor, Status-Q, https://statusq.org/archives/2001/11/26/75/ (E-Mail von Joe Biglen, nicht nachprüfbar; abgerufen 12.10.2026).","status":"entwurf","scenario":"Der Satz „Schreibe nie der Böswilligkeit zu, was durch Dummheit hinreichend erklärt werden kann“ trägt im Netz meist den Namen „Hanlons Rasiermesser“. Du findest heraus: Er wurde 1980 in einer Sammlung zu Murphys Gesetz unter der Überschrift „Hanlon’s Razor“ abgedruckt, ohne dass die Sammlung einen Einsender nennt. Dass ein Robert J. Hanlon ihn eingesandt habe, steht erst 2001 in einem Blogeintrag, der die E-Mail eines Bekannten wiedergibt; die dort genannten „Credits“ der Sammlung lassen sich nicht finden. Ähnlich lautende Sätze gab es schon 1941 bei Robert A. Heinlein und 1896 bei H. G. Wells.","kurz":"Der Name steht seit 1980 über dem Satz, doch der Abdruck nennt keinen Einsender; Hanlon als Einsender steht erst 2001 in einer weitergereichten E-Mail und ist nicht nachprüfbar. Ein Name an einem Satz belegt keinen Urheber, also bleibt die Urheberschaft offen.","prueffrage":"Wer wird im Abdruck von 1980 als Einsender des Satzes genannt, und wann taucht ein Name dafür erstmals auf?","rueckmeldung":[{"option":1,"text":"Dass der Name seit 1980 unter dem Satz steht und später eine Quelle Hanlon nennt, wirkt wie eine Spur. Der Abdruck von 1980 nennt aber keinen Einsender, und eine spätere Nennung ersetzt diesen Beleg nicht. „Eindeutig“ ist zu viel."},{"option":2,"text":"Heinleins Satz von 1941 ist tatsächlich älter als der Abdruck von 1980, und bei Wells steht 1896 Ähnliches. Das zeigt aber nur, dass es ältere Formulierungen gibt, nicht, wer den Gedanken zuerst hatte, und auch nicht, dass der Name erfunden ist."},{"option":3,"text":"Daran stimmt: Ob der Gedanke taugt, hängt nicht davon ab, wer ihn zuerst sagte. Ein bekannter Name zeigt aber nicht, dass der Satz stimmt, und wer wissen will, wie belastbar die Zuschreibung ist, kann die Urheberfrage nicht für unerheblich erklären."}],"familie":"zitat-am-original-pruefen","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Quote Investigator: Never Attribute to Malice That Which Is Adequately Explained by Stupidity (30.12.2016, aktual. 18.04.2025)","oeffentlich":true,"url":"https://quoteinvestigator.com/2016/12/30/not-malice/","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Bloch, A. (1980): Murphy's Law, Book Two: More Reasons Why Things Go Wrong!","oeffentlich":false}],"thema":"Geschichte und Wissenschaft"},{"id":"qx-a1-009","clusterId":"A","werkstueckRef":"A.2","stufe":1,"question":"Was ist der entscheidende Grund, warum diese Geschichte allein die Wirkung der Sitzungen nicht belegt?","scenario":"Eine Bekannte erzählt dir bewegt, ihr Onkel sei nach drei Sitzungen bei einem Energieheiler wie durch ein Wunder von seiner schweren Krankheit geheilt worden. Sie meint es ehrlich und ist von der Wirkung fest überzeugt. Du möchtest wissen, wie viel diese Geschichte als Beleg für die Wirkung der Sitzungen taugt.","options":["Die Bekannte ist ehrlich und meint es aufrichtig. Der Bericht taugt deshalb als Beleg, solange niemand einen Gegenbeleg vorlegt.","Der Onkel ist ein einzelner Fall. Erst wenn mehr als zehn ähnliche Berichte vorliegen, ist die Wirkung der Sitzungen belegt.","Die Geschichte ist sehr emotional erzählt. Gefühle machen einen Bericht weniger glaubwürdig, deshalb zählt er als Beleg nicht.","Ehrlichkeit schützt nicht vor Verzerrung. Spontanbesserung, Erwartung und unerzählte Misserfolge bleiben unsichtbar."],"correctIndex":3,"explanation":"Stell dir 100 Menschen vor, die ein völlig wirkungsloses Zuckerkügelchen gegen Kopfschmerzen nehmen: Einige wären ohnehin nach kurzer Zeit besser geworden (natürlicher Krankheitsverlauf), andere fühlen sich allein durch den Glauben an die Wirkung besser (Placebo-Effekt), und nur einer der Zufriedenen schreibt eine glühende Rezension. Von den übrigen hört man nie etwas, denn es melden sich nur die, bei denen es zu klappen schien (Überlebensirrtum). Ob der Erzähler ehrlich ist, ändert daran nichts, denn die Verzerrung steckt nicht in der Absicht, sondern darin, welche Fälle erzählt werden und was sonst noch zur Besserung beigetragen haben könnte. Eine einzelne Geschichte kann deshalb nicht zeigen, ob die Behandlung gewirkt hat. Sie kann aber ein guter Anlass sein, die Frage in einer kontrollierten Untersuchung zu prüfen. Wertlos ist sie also nicht, nur als Beweis reicht sie nicht.","coreRule":"⚡ Eine Anekdote ist ein Startpunkt für eine Hypothese, kein Beweis für eine Wirkung.","quote":"Wo auf der Pyramide der Evidenz befindet sich dieser Beweis, und warum ist er nicht weiter oben?","quoteLabel":"Prüffrage","beleg":"Werkstück A.2 (Ebene 1: Anekdoten, Testimonials & persönliche Erfahrungen; Der Kipppunkt; Das Anti-Denkmuster, Aktivierungs-Frage)","status":"entwurf","kurz":"Eine einzelne Heilungsgeschichte zeigt nicht, was die Besserung bewirkt hat: Sie kann auch vom natürlichen Verlauf oder von der Erwartung kommen, und von Misserfolgen hört man selten. Ehrlichkeit ändert daran nichts; als Anlass zum Prüfen taugt die Geschichte trotzdem.","prueffrage":"Wer hat die Krankheit des Onkels festgestellt, wer seine Heilung, und wann genau geschah beides?","rueckmeldung":[{"option":0,"text":"Dass die Bekannte aufrichtig erzählt, stimmt. Die Verzerrung liegt aber nicht in ihrer Absicht, sondern darin, welche Fälle erzählt werden und was sonst geholfen haben könnte; ein fehlender Gegenbeleg macht den Bericht nicht zum Beleg."},{"option":1,"text":"Ein Einzelfall zeigt tatsächlich wenig. Die Grenze von zehn Berichten ist aber willkürlich: Auch viele Geschichten stammen oft nur von denen, bei denen es zu klappen schien. Wirkung von Spontanbesserung trennt erst ein Vergleich."},{"option":2,"text":"Dass eine bewegende Erzählung mitreißt, ist richtig, doch Gefühle machen einen Bericht weder wahr noch unglaubwürdig. Das Problem liegt in der Auswahl der erzählten Fälle und in anderen möglichen Ursachen der Besserung."}],"familie":"evidenz-gewichten","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Evans, I.; Thornton, H.; Chalmers, I.; Glasziou, P.: Testing Treatments, 2. Aufl. – „Why do we need fair tests of treatments?“","oeffentlich":true,"url":"https://www.testingtreatments.org/book/need-fair-tests-treatments/","abruf":"2026-10-12"},{"typ":"url","kurz":"Evans, I.; Thornton, H.; Chalmers, I.; Glasziou, P.: Testing Treatments, 2. Aufl. – „What are fair tests of treatments?“","oeffentlich":true,"url":"https://www.testingtreatments.org/book/fair-tests-treatments/","abruf":"2026-10-12"}],"thema":"Gesundheit"},{"id":"qx-a1-010","clusterId":"A","werkstueckRef":"A.2","stufe":2,"question":"Was fehlt dieser „Studie“ vor allem, um als Beleg für die Wirkung zu taugen?","scenario":"Eine Kosmetikfirma wirbt: „Wissenschaftlich bewiesen! 95 % von 100 befragten Frauen bestätigen: Die Haut fühlt sich nach vier Wochen Anwendung der neuen Creme straffer an.“ Eine Vergleichsgruppe gab es nicht, gemessen wurde nur das Empfinden der Teilnehmerinnen.","options":["Eine größere Stichprobe: Bei 1.000 statt 100 Befragten wäre dieselbe Umfrage ein Beleg für die Wirkung der Creme.","Eine Veröffentlichung in einer Fachzeitschrift: Dort gedruckt, wäre die Umfrage ein Beleg für die Wirkung der Creme.","Eine verblindete Vergleichsgruppe mit normaler Creme: Sonst bleibt offen, ob die Creme wirkt oder nur die Erwartung.","Eine Nachbefragung nach einem Jahr: Sind die Frauen dann noch zufrieden, wäre das ein Beleg für die Wirkung der Creme."],"correctIndex":2,"explanation":"Die Werbung stützt sich auf eine reine Befragung: Es gibt keine Vergleichsgruppe, das Ergebnis („fühlt sich straffer an“) ist subjektiv, und die Erwartung der Teilnehmerinnen wird nicht kontrolliert. Wer eine neue Creme testet und hofft, dass sie wirkt, nimmt auch ohne echte Wirkung oft eine Besserung wahr. Erst der Vergleich mit einer Gruppe, die eine normale Creme benutzt, ohne dass die Frauen wissen, welche sie bekommen, trennt die tatsächliche Wirkung von Erwartung und Zufall. Mehr Befragte, ein anderer Veröffentlichungsort oder eine spätere Wiederholung beheben dieses Grundproblem nicht: Viele Antworten ohne Vergleich bleiben viele Eindrücke ohne Vergleich.","coreRule":"⚡ Ohne Vergleichsgruppe misst eine Umfrage Erwartungen, nicht Wirkungen.","beleg":"Werkstück A.2 (Ebene 3: Beispiel Anti-Falten-Creme; Gekaufte Institute & Raubjournale)","status":"entwurf","kurz":"Erst der Vergleich mit Frauen, die unwissentlich eine normale Creme benutzen, trennt eine Wirkung der Creme von bloßer Erwartung. Die hohe Zustimmung wirkt beweiskräftig, doch schon die Hoffnung auf Besserung könnte das straffere Gefühl erklären.","prueffrage":"Wie wurde „straffer“ gemessen, und wer hat es beurteilt?","rueckmeldung":[{"option":0,"text":"Mehr Befragte machen das Ergebnis zufallsfester, was grundsätzlich nützlich ist. Die Erwartung der Teilnehmerinnen bleibt aber unkontrolliert: Auch 1.000 Eindrücke ohne Vergleich zeigen nicht, ob die Creme etwas bewirkt."},{"option":1,"text":"Eine Veröffentlichung kann Qualität sichern, sie ersetzt aber kein Studiendesign. Wird dieselbe Umfrage ohne Vergleichsgruppe gedruckt, bleibt sie in der Aussage über die Wirkung genauso schwach wie vorher."},{"option":3,"text":"Ein langer Zeitraum eignet sich gut, um Dauer oder Verträglichkeit zu prüfen. Anhaltende Zufriedenheit zeigt aber nicht, dass die Creme die Ursache ist: Ohne Vergleichsgruppe könnte auch die Erwartung sie erklären."}],"familie":"fair-testen","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Evans, I.; Thornton, H.; Chalmers, I.; Glasziou, P.: Testing Treatments, 2. Aufl. – „What are fair tests of treatments?“","oeffentlich":true,"url":"https://www.testingtreatments.org/book/fair-tests-treatments/","abruf":"2026-10-12"}],"thema":"Geld und Zahlen"},{"id":"qx-a1-011","clusterId":"A","werkstueckRef":"A.2","stufe":3,"question":"Was folgt aus dem Wort „signifikant“ für die Werbeaussage, und was nicht?","scenario":"Ein Hersteller wirbt für sein Diätmittel: „In einer Studie nahmen die Teilnehmer in sechs Monaten signifikant ab!“ Auf Nachfrage räumt er ein, dass der durchschnittliche Unterschied zur Vergleichsgruppe bei 50 Gramm liegt.","options":["Der Effekt ist groß genug, um im Alltag spürbar zu sein, sonst würde man ihn nicht „signifikant“ nennen.","Die Daten passen schlecht zu der Annahme „kein Effekt“, doch ob 50 Gramm irgendeine Bedeutung haben, bleibt offen und muss separat beurteilt werden.","Zufall und Verzerrung sind damit ausgeschlossen, und die Wirkung des Mittels gilt als sicher belegt.","Die Studie war doppelt verblindet und entspricht damit dem Goldstandard, sonst dürfte man das Ergebnis nicht „signifikant“ nennen."],"correctIndex":1,"explanation":"„Statistisch signifikant“ heißt nur: Die Daten passen schlecht zu der Annahme, dass das Mittel gar nichts bewirkt. Über die Größe oder Wichtigkeit des Effekts sagt der Begriff nichts. 50 Gramm in sechs Monaten können daher statistisch ein Erfolg und praktisch nutzlos sein. Ein signifikantes Ergebnis spricht gegen bloßen Zufall, schließt ihn aber nicht aus, und ob Verzerrungen begrenzt wurden, hängt vom Studiendesign ab: von Kontrollgruppe, Randomisierung und Verblindung. Die entscheidende Nachfrage lautet deshalb: Wie groß ist die Effektstärke, und ist sie für den Alltag relevant?","coreRule":"⚡ Signifikant ist nicht dasselbe wie relevant: Frag immer nach der Effektstärke.","beleg":"Werkstück A.2 (Ebene 4: Der Missbrauch durch „Signifikanz“; Die 4 Säulen der Resilienz)","status":"entwurf","kurz":"„Signifikant“ heißt nur, dass die Daten schlecht zu „kein Effekt“ passen, nicht, dass der Effekt groß oder wichtig ist. 50 Gramm in sechs Monaten können statistisch ein Erfolg und praktisch nutzlos sein. Entscheidend ist die Effektstärke.","prueffrage":"Was genau wurde in der Studie verglichen, und wie viele Personen waren in jeder Gruppe?","rueckmeldung":[{"option":0,"text":"Im Alltag bedeutet „signifikant“ so viel wie „bedeutsam“, in der Statistik aber nicht. Das Wort sagt nur, dass die Daten schlecht zu „kein Effekt“ passen, nicht, wie groß ein Effekt ist; 50 Gramm in sechs Monaten zeigen das gut."},{"option":2,"text":"Ein signifikantes Ergebnis spricht gegen „kein Effekt“, schließt Zufall aber nicht aus, und gegen Verzerrung helfen erst Kontrollgruppe, Randomisierung und Verblindung. „Sicher belegt“ geht deshalb zu weit."},{"option":3,"text":"Eine Verblindung ist ein wichtiges Qualitätsmerkmal des Designs, aber das Wort „signifikant“ sagt nichts darüber. Ob verblindet wurde, verrät die Werbung nicht; das Wort beschreibt nur, wie gut die Daten zu „kein Effekt“ passen."}],"familie":"studie-genau-lesen","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"American Statistical Association (2016): ASA releases Statement on Statistical Significance and P-Values (Pressemitteilung mit den sechs Grundsätzen)","oeffentlich":true,"url":"https://www.amstat.org/asa/files/pdfs/p-valuestatement.pdf","abruf":"2026-10-12"}],"thema":"Gesundheit"},{"id":"qx-a1-012","clusterId":"A","werkstueckRef":"A.2","stufe":4,"question":"Welches Vorgehen führt hier am ehesten zu einem verlässlichen Gesamturteil, und worauf bleibt es angewiesen?","scenario":"Ein Ratgeber schreibt: „Fünf Studien belegen die Wirkung von Vitamin X – ein überwältigender Beweis!“ Du findest heraus: Es gibt 95 weitere Studien zum selben Mittel, überwiegend groß und sorgfältig, mit einem Effekt nahe null. Du willst alle 100 Studien zu einem Gesamturteil zusammenführen.","options":["Die gemessenen Effekte aller Studien zu einem Gesamtergebnis verrechnen, wobei große, genaue Studien mehr Gewicht bekommen; das Urteil hängt davon ab, ob auch die erfolglosen Studien veröffentlicht wurden.","Auszählen, wie viele Studien einen signifikanten Effekt fanden, und der Mehrheit folgen, ohne die Größe und Genauigkeit der Effekte zu berücksichtigen; das Urteil hängt davon ab, wie viele Studien das Ergebnis stützen.","Die methodisch beste Einzelstudie auswählen und alle übrigen Studien durch deren Ergebnis ersetzen, ohne die Daten der anderen zu berücksichtigen; das Urteil hängt davon ab, welche Studie ausgewählt wurde.","Alle Studien gleich gewichten, ganz ohne Rücksicht auf ihre Größe und Genauigkeit; das Urteil hängt davon ab, wie viele kleine und große Studien vorliegen."],"correctIndex":0,"explanation":"Ein verlässliches Gesamturteil zählt keine Treffer, sondern verrechnet die gemessenen Effekte aller Studien. Große, genaue Studien liefern dabei sicherere Schätzungen und verdienen mehr Gewicht als kleine, zufallsanfällige. Das bloße Auszählen „signifikanter“ Studien kann dagegen zum falschen Schluss führen, denn es ignoriert, wie groß die Effekte sind und wie präzise sie gemessen wurden. Eine einzelne Studie auszuwählen wirft die übrigen Informationen weg, und gleiches Gewicht für alle lässt kleine, zufällig schwankende Studien genauso viel zählen wie große. Außerdem hängt jede Zusammenfassung von ihrem Material ab: Wenn die erfolglosen Studien in der Schublade liegen, ist auch das Gesamtergebnis verzerrt. Umgekehrt können viele kleine Studien, die einzeln nichts Sicheres zeigen, zusammen einen echten Effekt sichtbar machen.","coreRule":"⚡ Bei der Zusammenfassung vieler Studien zählt das Gewicht der Effekte, nicht die Zahl der Treffer – und das Ergebnis ist nur so gut wie die Studien, die überhaupt veröffentlicht wurden.","beleg":"Werkstück A.2 (Ebene 5); Fn. ga-metaanalyse (Deeks u. a. 2024, Cochrane Handbook 6.5, Kap. 10, Abschn. 10.2.1 und 10.3; McKenzie/Brennan 2024, Kap. 12, Abschn. 12.2.2.1)","status":"entwurf","kurz":"Verlässlich wird das Urteil, wenn die gemessenen Effekte aller Studien verrechnet werden und große, genaue mehr zählen; bloßes Treffer-Zählen übersieht Größe und Genauigkeit. Auch so hängt das Urteil davon ab, ob erfolglose Studien erschienen sind.","prueffrage":"Was haben die fünf zitierten Studien gemeinsam, das die 95 übrigen nicht haben?","rueckmeldung":[{"option":1,"text":"Eine Mehrheit zu zählen wirkt einfach und anschaulich. Dabei bleibt aber unbeachtet, wie groß die Effekte sind und wie genau sie gemessen wurden; so kann ein Zufallsbefund kleiner Studien ein großes, sorgfältiges Ergebnis überstimmen."},{"option":2,"text":"Die beste Einzelstudie ist oft wirklich aussagekräftig, und auf Qualität zu achten ist richtig. Wer aber nur sie nimmt, verwirft die Daten der übrigen 99 Studien und macht das Urteil von der Auswahl abhängig."},{"option":3,"text":"Alle gleich zu behandeln klingt fair, ist aber ungenau: Eine kleine, zufällig schwankende Studie zählte dann so viel wie eine große, sorgfältige. Genauere Schätzungen verdienen mehr Gewicht, so wie hier die überwiegend großen 95 Studien."}],"familie":"studie-genau-lesen","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"Deeks, J. J. u. a.: Analysing data and undertaking meta-analyses. Cochrane Handbook, Kap. 10","oeffentlich":true,"url":"https://www.cochrane.org/authors/handbooks-and-manuals/handbook/current/chapter-10","abruf":"2026-10-07"},{"typ":"url","kurz":"McKenzie, J. E.; Brennan, S. E.: Synthesizing and presenting findings using other methods. Cochrane Handbook, Kap. 12","oeffentlich":true,"url":"https://www.cochrane.org/authors/handbooks-and-manuals/handbook/current/chapter-12","abruf":"2026-10-12"},{"typ":"url","kurz":"Page, M. J.; Higgins, J. P. T.; Sterne, J. A. C.: Assessing risk of bias due to missing evidence in a meta-analysis. Cochrane Handbook, Kap. 13","oeffentlich":true,"url":"https://www.cochrane.org/authors/handbooks-and-manuals/handbook/current/chapter-13","abruf":"2026-10-12"}],"thema":"Geschichte und Wissenschaft"},{"id":"qx-a1-013","clusterId":"A","werkstueckRef":"A.3","stufe":1,"question":"Zwei Forscherinnen stellen jeweils eine Theorie auf. Theorie 1 sagt voraus: „Das Licht ferner Sterne wird am Rand der Sonne um einen bestimmten Betrag abgelenkt; zeigt die nächste Sonnenfinsternis keine oder eine andere Ablenkung, ist die Theorie falsch.“ Theorie 2 sagt: „Eine Ablenkung kann auftreten, muss aber nicht; fällt sie aus, haben eben andere Kräfte mitgewirkt.“ Warum ist Theorie 1 wissenschaftlich wertvoller?","options":["Sie legt sich fest und kann an einer Beobachtung scheitern, denn schon ein abweichendes Ergebnis würde sie widerlegen.","Sie ist glaubwürdiger, denn sie klingt entschlossener und stützt sich auf mehr Selbstvertrauen der Forscherin.","Sie ist sicherer, denn eine Theorie mit klaren Vorhersagen wird in der Praxis fast immer bestätigt.","Sie ist nützlicher, denn eine Theorie sollte möglichst viele Beobachtungen miteinander in Einklang bringen können."],"correctIndex":0,"explanation":"Eine wissenschaftliche Theorie sagt nicht nur voraus, was passieren wird, sondern vor allem, was nicht passieren darf. Theorie 1 nennt eine Beobachtung, die sie widerlegen würde, und setzt sich damit einem echten Risiko aus. So war es auch bei Einsteins Relativitätstheorie vor der Sonnenfinsternis 1919: Hätte die Beobachtung keine oder eine falsche Ablenkung gezeigt, wäre die Theorie in ihrer damaligen Form widerlegt gewesen. Theorie 2 ist mit jedem Ergebnis vereinbar und lässt sich deshalb durch nichts prüfen. Wissenschaftlich wertvoll macht eine Theorie also nicht, dass sie sich bestätigen lässt, sondern dass sie scheitern könnte. Selbstvertrauen oder Ansehen der Urheberin sagen darüber nichts aus.","coreRule":"⚡ Eine Theorie wird durch das Risiko wissenschaftlich, an der Beobachtung zu scheitern, nicht durch ihre Bestätigungen allein.","quote":"","quoteLabel":"","beleg":"Werkstück A.3 (Kontext & Tiefe); Fn. ga-popper (Popper 1935, Logik der Forschung; engl. 1959, Abgrenzungskriterium Abschn. 6)","status":"entwurf","scenario":"","kurz":"Theorie 1 verbietet bestimmte Beobachtungen und riskiert so, widerlegt zu werden. Theorie 2 passt zu jedem Ergebnis und lässt sich deshalb nicht prüfen. Der Trugschluss: Eine Theorie scheint umso besser, je leichter sie sich bestätigen lässt.","prueffrage":"Was würde Theorie 2 sagen, wenn die Ablenkung doppelt so groß, halb so groß oder gar nicht aufträte?","rueckmeldung":[{"option":1,"text":"Entschlossenes Auftreten wirkt überzeugend und färbt leicht auf die Theorie ab. Gemessen wird aber, was die Theorie voraussagt und ausschließt, nicht, wie sicher ihre Urheberin auftritt. Selbstvertrauen sagt nichts über ihren Wert."},{"option":2,"text":"Von klaren Vorhersagen erwartet man leicht, dass sie sich bewähren. Gerade weil sie scheitern können, sind sie wertvoll; dass sie sich in der Praxis fast immer bestätigen, folgt aus ihrer Klarheit nicht."},{"option":3,"text":"Eine Theorie, die vieles zusammenführt, ist nützlich, das stimmt. Theorie 2 passt aber zu jedem Ergebnis, weil sie nichts ausschließt, und erklärt dadurch gerade nichts. Wertvoll wird Passendes erst, wenn es auch hätte danebenliegen können."}],"familie":"widerlegung-benennen","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Thornton, S.: Karl Popper. Stanford Encyclopedia of Philosophy","oeffentlich":true,"url":"https://plato.stanford.edu/entries/popper/","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Popper, K. R. (1959): The Logic of Scientific Discovery. London: Hutchinson (dt. Logik der Forschung, 1935)","oeffentlich":false}],"thema":"Geschichte und Wissenschaft"},{"id":"qx-a1-014","clusterId":"A","werkstueckRef":"A.3","stufe":2,"question":"Welche Rückfrage deckt den Kern des Problems an dieser Behauptung am besten auf?","scenario":"Eine Hellseherin sagt: „Meine Gabe wirkt nicht unter Testbedingungen. Die Anwesenheit von Skeptikern und Messgeräten stört die feinstofflichen Energien.“ Du möchtest ihre Fähigkeit überprüfen.","options":["„Wie hoch ist die Wahrscheinlichkeit, dass Hellsehen überhaupt existiert, und wann scheiden unwahrscheinliche Behauptungen aus der Prüfung aus?“","„Welches Ergebnis eines fairen Tests würdest du als Beleg dafür akzeptieren, dass deine Gabe nicht funktioniert?“","„Wie würdest du die Behauptung formulieren, wenn du ganz auf mehrdeutige Begriffe verzichten müsstest?“","„Warum solltest du glaubwürdig sein, wenn du doch selbst von deiner Fähigkeit überzeugt bist?“"],"correctIndex":1,"explanation":"Die Hellseherin erklärt das Ausbleiben des Effekts schon im Voraus: Sobald jemand prüft, „stört“ das Messen die Gabe. Damit kann kein denkbares Testergebnis sie noch widerlegen, und eine Behauptung, die nicht scheitern kann, sagt nichts über die Welt. Die Rückfrage nach dem akzeptierten Gegenbeleg legt genau das offen: Nennt sie ein Ergebnis, ist die Behauptung prüfbar; findet sie keines, ist sie immunisiert. Unwahrscheinlich ist nicht dasselbe wie unprüfbar: Eine unwahrscheinliche Behauptung, die ein klares Scheitern zuließe, wäre durchaus testbar. Auch Befangenheit oder unscharfe Wortwahl sind hier nicht der Kern. Entscheidend ist, dass die Begründung jedes Scheitern im Voraus wegerklärt.","coreRule":"⚡ Frag bei jeder Behauptung: Welches Ergebnis würde sie widerlegen? Eine Behauptung, die ihr Scheitern schon vorab wegerklärt, sagt nichts mehr über die Welt.","beleg":"Werkstück A.3 (Anwendung & Relevanz: Bei Parawissenschaft & Aberglaube)","status":"entwurf","kurz":"Die Rückfrage nach dem Gegenbeleg zeigt, ob die Behauptung überhaupt scheitern kann. Plausibilität oder Wortwahl anzugreifen trifft nicht den Kern: Schon ihre Begründung erklärt jedes Scheitern im Voraus weg.","prueffrage":"Unter welchen Bedingungen hat sie ihre Gabe bisher gezeigt, und wer war dabei?","rueckmeldung":[{"option":0,"text":"Wie wahrscheinlich Hellsehen ist, spielt für die Beweislast eine Rolle. Den Kern trifft es aber nicht: Auch eine unwahrscheinliche Behauptung wäre testbar, wenn sie klar scheitern dürfte. Hier erklärt die Begründung jedes Scheitern weg."},{"option":2,"text":"Klare Begriffe machen eine Behauptung greifbarer, und „feinstoffliche Energien“ ist tatsächlich unscharf. Selbst ganz präzise formuliert bliebe sie aber immun, solange das Prüfen selbst als Störung gilt."},{"option":3,"text":"Eigene Überzeugung ist tatsächlich noch kein Beleg. Die Frage zielt aber auf die Person statt auf die Behauptung. Wer aufrichtig überzeugt ist, kann trotzdem Prüfbares sagen; entscheidend ist, ob ein Scheitern denkbar bleibt."}],"familie":"widerlegung-benennen","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Thornton, S.: Karl Popper. Stanford Encyclopedia of Philosophy","oeffentlich":true,"url":"https://plato.stanford.edu/entries/popper/","abruf":"2026-10-12"},{"typ":"url","kurz":"Hansson, S. O.: Science and Pseudo-Science. Stanford Encyclopedia of Philosophy","oeffentlich":true,"url":"https://plato.stanford.edu/entries/pseudo-science/","abruf":"2026-10-12"}],"thema":"Geschichte und Wissenschaft"},{"id":"qx-a1-015","clusterId":"A","werkstueckRef":"A.3","stufe":3,"question":"Woran erkennst du, ob die Zusatzannahme des Astronomen brauchbar oder bloße Rettung ist?","scenario":"Ein Astronom sagt: „Meine Theorie passt nicht zu den Messdaten der Bahn dieses Planeten. Ich nehme deshalb einen noch unbekannten Himmelskörper an, dessen Schwerkraft die Abweichung verursacht.“ Eine Kollegin hält dagegen: „Das ist doch nur eine Ausrede, um die Theorie zu retten.“ Beim Uranus führte genau so eine Annahme 1846 zur Entdeckung des Neptun. Beim Merkur ließ sich der angenommene Planet „Vulkan“ nie nachweisen; die Abweichung erklärte erst Einsteins Relativitätstheorie.","options":["Brauchbar ist sie, wenn sie neue, prüfbare Vorhersagen liefert, die scheitern könnten und sich zum Teil bestätigen, sonst flickt sie die Theorie nur nachträglich.","Brauchbar ist sie, solange sie sich bisher nicht widerlegen ließ, denn eine unwiderlegte Annahme gilt als vorläufig bestätigt.","Brauchbar ist sie nie, denn jede Zusatzannahme dient nur der Rettung der Theorie und schwächt sie dadurch zwangsläufig.","Brauchbar ist sie, wenn sie von etablierten Forschern stammt, denn Annahmen von Außenseitern sind unabhängig vom Ergebnis der Prüfung verdächtig."],"correctIndex":0,"explanation":"Eine Zusatzannahme allein ist noch kein Alarmsignal. Entscheidend ist, ob sie etwas Neues vorhersagt, das sich prüfen lässt und scheitern könnte, und ob sich davon etwas bestätigt: Der Planet für die Uranusbahn wurde 1846 gefunden, „Vulkan“ dagegen trotz Suche nie; diese Annahme war prüfbar, hielt der Prüfung aber nicht stand. Bloße Rettung ist eine Annahme, die jeder Prüfung ausweicht, etwa ein Himmelskörper, der grundsätzlich weder zu sehen noch zu messen sein soll; dass sie unwiderlegt bleibt, beweist nichts. Die Herkunft einer Annahme sagt nichts über ihre Qualität, und ein pauschales Verbot von Zusatzannahmen hätte den Neptun nie finden lassen. Das Urteil bleibt dabei graduell und vorläufig.","coreRule":"⚡ Eine Hilfsannahme wird verdächtig, wenn sie nichts Neues vorhersagt, das scheitern könnte.","beleg":"Werkstück A.3 (Red Flags: Die Ad-hoc-Hypothese); Fn. ga-hilfsannahmen (Musgrave/Pigden, Stanford Encyclopedia of Philosophy, „Imre Lakatos“, Abschn. 2.2; McIntyre 2020, S. 38–39)","status":"entwurf","kurz":"Eine Zusatzannahme taugt, wenn sie Neues vorhersagt, das scheitern könnte, und sich davon etwas bestätigt: Der Neptun wurde gefunden, „Vulkan“ nie. Wer dagegen jede Zusatzannahme pauschal als Ausrede abtut, hätte auch den Neptun nie gesucht.","prueffrage":"Was geschah nach der Zusatzannahme beim Uranus, was beim Merkur ausblieb?","rueckmeldung":[{"option":1,"text":"Dass eine Annahme noch nicht widerlegt ist, klingt nach einem Pluspunkt. Aber auch eine Annahme, die sich jeder Prüfung entzieht, bleibt unwiderlegt, ohne etwas zu leisten. Unwiderlegt heißt deshalb noch nicht bestätigt."},{"option":2,"text":"Der Verdacht gegen Zusatzannahmen ist verständlich, denn der Planet „Vulkan“ wurde trotz Suche nie gefunden. Pauschal trägt er aber nicht: Genau eine solche Annahme führte 1846 zum Neptun. Es kommt auf die Prüfbarkeit an."},{"option":3,"text":"Ob jemand etabliert ist, wirkt wie eine bequeme Abkürzung bei der Einschätzung. Über die Qualität der Annahme sagt es aber nichts: Sie wird durch ihre prüfbaren Vorhersagen beurteilt, nicht durch ihre Herkunft."}],"familie":"immunisierung-erkennen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Musgrave, A.; Pigden, C.: Imre Lakatos. Stanford Encyclopedia of Philosophy","oeffentlich":true,"url":"https://plato.stanford.edu/entries/lakatos/","abruf":"2026-10-12"},{"typ":"url","kurz":"Wills, M. (2016): Where in the Solar System is Vulcan? JSTOR Daily","oeffentlich":true,"url":"https://daily.jstor.org/solar-system-vulcan/","abruf":"2026-10-12"},{"typ":"literatur","kurz":"McIntyre, L. (2020): Wir lieben Wissenschaft. Berlin: Springer, S. 38–39 (laut Fußnote ga-hilfsannahmen)","oeffentlich":false}],"thema":"Natur und Klima"},{"id":"qx-a1-016","clusterId":"A","werkstueckRef":"A.3","stufe":4,"question":"Ab wann wird eine nicht widerlegbare Aussage zum Problem?","scenario":"Zwei Sätze: (1) „Ich glaube, dass das Universum mich trägt.“ (2) „Meine Energieheilung wirkt auf einer Ebene, die keine Messung erfassen kann, darum brauchst du deine Therapie nicht.“ Beide sind so gebaut, dass keine Beobachtung sie widerlegen kann. Eine Freundin meint: „Wenn man etwas nicht widerlegen kann, ist beides gleich unproblematisch.“","options":["Der erste Satz bleibt als persönlicher Glaube oder Bild harmlos; der zweite wird zum Problem, weil er die Wirklichkeit beschreiben will und Entscheidungen anderer prägen kann.","Beide sind gleich problematisch, denn jede nicht widerlegbare Aussage ist unwissenschaftlich und deshalb zu bekämpfen, gleichgültig, ob sie jemandem schadet oder nicht.","Keiner ist problematisch: Wer eine Behauptung nicht widerlegen kann, muss sie als gleichwertige Meinung neben der Medizin gelten lassen, sobald sie ernsthaft vorgetragen wird.","Der zweite Satz ist nur dann ein Problem, wenn damit Geld verdient wird; ohne Verkaufsinteresse bleibt er harmlos, auch wenn jemand im Vertrauen darauf auf Behandlung verzichtet."],"correctIndex":0,"explanation":"Eine Aussage, die sich nicht widerlegen lässt, kann als persönliches Glaubensbekenntnis oder als Metapher (etwa in Kunst oder Religion) harmlos sein, denn sie erhebt nicht den Anspruch, eine objektive Beschreibung der Realität zu sein. Problematisch wird sie, wenn sie genau diesen Anspruch erhebt und auf dieser Basis Entscheidungen getroffen werden, die andere betreffen, besonders in Medizin, Politik oder Justiz. Wenn eine unprüfbare Heilmethode eine wirksame medizinische Behandlung ersetzt, kann das tödlich sein. Dass sich eine Aussage nicht widerlegen lässt, macht sie nicht zu einer Beschreibung der Wirklichkeit; entscheidend ist, welchen Anspruch sie erhebt und welche Folgen für Betroffene daran hängen, nicht die Unwiderlegbarkeit an sich. Hinweis: Widerlegbarkeit allein gilt laut Fachdiskussion nicht als scharfe Trennlinie zwischen Wissenschaft und Pseudowissenschaft.","coreRule":"⚡ Nicht die Unwiderlegbarkeit an sich ist das Problem, sondern der Anspruch auf Wirklichkeit, an dem Entscheidungen anderer hängen.","beleg":"Werkstück A.3 (Der Kipppunkt); Fn. ga-popper (Laudan 1983, S. 111–127; Pigliucci/Boudry 2013)","status":"entwurf","kurz":"Unwiderlegbarkeit allein entscheidet nichts. Ein persönlicher Glaube oder ein Bild kann harmlos sein; problematisch wird eine Aussage, wenn sie die Wirklichkeit beschreiben will und andere sich danach richten, etwa indem sie auf eine wirksame Behandlung verzichten.","prueffrage":"Was würde ein schwer kranker Mensch tun, der jeden der beiden Sätze wörtlich nimmt?","rueckmeldung":[{"option":1,"text":"Wissenschaftlich prüfbar ist ein unwiderlegbarer Satz tatsächlich nicht. Bekämpfen muss man ihn deshalb nicht: Ein persönlicher Glaube oder ein Bild erhebt keinen Anspruch, die Wirklichkeit zu beschreiben, und kann harmlos sein."},{"option":2,"text":"Ernsthaft Vorgetragenes verdient eine faire Prüfung, das stimmt. Dass man etwas nicht widerlegen kann, macht es aber nicht gleichwertig mit der Medizin, und wenn eine solche Aussage eine Behandlung ersetzt, kann das tödlich sein."},{"option":3,"text":"Verkaufsinteresse kann den Schaden vergrößern, ist aber nicht das Entscheidende. Auch ohne Gewinn kann der Satz jemanden dazu bringen, auf eine wirksame Behandlung zu verzichten; es kommt auf Anspruch und Folgen an."}],"familie":"ergaenzen-oder-ersetzen","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"Hansson, S. O.: Science and Pseudo-Science. Stanford Encyclopedia of Philosophy","oeffentlich":true,"url":"https://plato.stanford.edu/entries/pseudo-science/","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Laudan, L. (1983): The Demise of the Demarcation Problem. In: Cohen, R. S.; Laudan, L. (Hg.): Physics, Philosophy and Psychoanalysis. Dordrecht: Reidel, 111–127","oeffentlich":false}],"thema":"Geschichte und Wissenschaft"},{"id":"qx-a1-017","clusterId":"A","werkstueckRef":"A.4","stufe":1,"question":"Was ist an der Forderung des Bekannten fehlerhaft?","scenario":"Ein Bekannter sagt über seine Kristalle: „Die haben heilende Energie. Beweise mir doch, dass es nicht stimmt!“ Du hast keinen Beleg dafür, dass es falsch ist, aber auch keinen, dass es stimmt.","options":["Nichts: Solange eine Wirkung nicht widerlegt ist, gilt sie als vorläufig möglich und darf vertreten werden.","Die Last wird umgedreht: Wer eine Wirkung behauptet, muss sie belegen; dass sich ihr Fehlen nicht beweisen lässt, spricht nicht für sie.","Nichts: Da auch die Schulmedizin nicht alles erklären kann, muss jede Seite ihre Position gleichermaßen belegen.","Sie ist nur dann unzulässig, wenn der Fragende keine naturwissenschaftliche Ausbildung hat; Fachleute dürfen so fragen."],"correctIndex":1,"explanation":"Wer eine Behauptung aufstellt, muss sie belegen; wer zweifelt, muss nichts widerlegen. Das ist nicht Willkür, sondern die einzige praktikable Regel: Die Nicht-Existenz beliebiger Dinge lässt sich nie beweisen, nicht bei Russells winziger Teekanne zwischen Erde und Mars, nicht bei Geistern oder Feen. Müsste jeder Zweifler solche Behauptungen widerlegen, wäre man entweder gezwungen, alles zu glauben, oder könnte nie zu einem Urteil kommen. Dass du das Gegenteil nicht beweisen kannst, ist daher kein Hinweis auf die Wahrheit der Behauptung. Der Verweis auf die Grenzen der Schulmedizin ändert daran nichts: Lücken in einer Erklärung sind kein Beleg für eine andere. Auch die Ausbildung des Fragenden ändert daran nichts; für Fachleute gilt keine Ausnahme von dieser Regel.","coreRule":"⚡ „Beweise mir das Gegenteil“ verschiebt die Last – wer behauptet, liefert.","beleg":"Werkstück A.4 (Anwendung & Relevanz: Bei Pseudomedizin & Esoterik); Fn. ga-russell (Russell 1952, Collected Papers Bd. 11, S. 547 f.)","status":"entwurf","kurz":"Wer eine Wirkung behauptet, muss sie belegen; wer zweifelt, muss nichts widerlegen. Dass sich das Gegenteil nicht beweisen lässt, spricht nicht für die Behauptung: Auch dass keine Teekanne zwischen Erde und Mars kreist, lässt sich nicht beweisen.","prueffrage":"Wie könnte man herausfinden, ob es Menschen mit Kristallen besser geht als ohne?","rueckmeldung":[{"option":0,"text":"Denkbar ist vieles, das stimmt. Aber „nicht widerlegt“ ist kein Beleg: Sonst wären auch Feen und Geister vertretbar, nur weil niemand ihr Fehlen beweisen kann. Die Belegpflicht bleibt beim Behauptenden."},{"option":2,"text":"Dass die Schulmedizin Lücken hat, stimmt. Aber Lücken in einer Erklärung sind kein Beleg für eine andere, und die Belegpflicht bleibt bei dem, der die Heilwirkung der Kristalle behauptet."},{"option":3,"text":"Fachwissen hilft, Belege zu bewerten, ändert aber nicht, wer sie liefern muss. Die Regel gilt für alle gleich, auch für Fachleute: Wer eine Wirkung behauptet, trägt die Beweislast."}],"familie":"beweislast-klaeren","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Dowden, B.: Fallacies. Internet Encyclopedia of Philosophy (Einträge „Appeal to Ignorance“, „Misplaced Burden of Proof“)","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Russell, B. (1952): Is There a God? In: Collected Papers of Bertrand Russell, Bd. 11. London: Routledge 1997, 543–548","oeffentlich":false}],"thema":"Gesundheit"},{"id":"qx-a1-018","clusterId":"A","werkstueckRef":"A.4","stufe":2,"question":"Wie viel Beleg darfst du von den beiden Kolleginnen jeweils verlangen, bevor du ihnen glaubst?","scenario":"Eine Kollegin sagt: „Ich habe heute früh einen Kaffee getrunken.“ Eine andere sagt: „Ich wurde heute früh von Außerirdischen entführt und habe mit ihnen Kaffee getrunken.“ Du sollst entscheiden, wem du was glaubst.","options":["Bei beiden gleich viel, weil die Beweislast nicht vom Inhalt abhängt, sondern nur davon, wer spricht.","Bei beiden nichts, weil niemand dadurch zu Schaden kommt und Belege nur dort nötig sind, wo andere betroffen sind.","Bei der zweiten weniger, weil sich niemand so etwas ausdenkt und die Auffälligkeit der Aussage schon für sie spricht.","Bei der ersten kaum, bei der zweiten sehr viel, weil der geforderte Aufwand mit der Außergewöhnlichkeit der Aussage wächst."],"correctIndex":3,"explanation":"Wer etwas behauptet, muss es belegen, und zwar umso gründlicher, je außergewöhnlicher die Behauptung ist. Die Stärke der geforderten Beweise muss zur Außergewöhnlichkeit der Behauptung proportional sein. Die Aussage, heute früh einen Kaffee getrunken zu haben, erfordert kaum Beweise. Die Aussage, von Außerirdischen entführt worden zu sein und mit ihnen Kaffee getrunken zu haben, erfordert massive, stichhaltige und überprüfbare Beweise. Dass eine Aussage auffällig ist, macht sie nicht glaubwürdiger, sondern erhöht die Anforderung an den Beleg. Ob jemand durch die Aussage zu Schaden kommt oder nicht, ändert nichts daran, dass der geforderte Beleg zur Außergewöhnlichkeit der Behauptung passen muss.","coreRule":"⚡ Je ungewöhnlicher die Behauptung, desto stärker müssen die Belege sein.","beleg":"Werkstück A.4 (Kontext & Tiefe)","status":"entwurf","kurz":"Wie viel Beleg nötig ist, hängt davon ab, wie außergewöhnlich die Behauptung ist: Für den Kaffee genügt fast nichts, für die Entführung braucht es massive, überprüfbare Beweise. Dass etwas auffällt, macht es nicht glaubwürdiger, sondern verschärft die Anforderung.","prueffrage":"Was könntest du bei jeder der beiden Kolleginnen nachprüfen, um ihre Aussage zu bestätigen?","rueckmeldung":[{"option":0,"text":"Wer etwas behauptet, muss es tatsächlich belegen, egal wer spricht. Wie viel Beleg reicht, hängt aber vom Inhalt ab: Ein Kaffee am Morgen und eine Entführung durch Außerirdische verlangen nicht denselben Aufwand."},{"option":1,"text":"Schaden für andere kann ein zusätzlicher Grund für Sorgfalt sein. Ob jemand betroffen ist, bestimmt aber nicht, wann man etwas glauben darf: Auch eine harmlose Behauptung braucht einen Beleg, der zu ihrer Außergewöhnlichkeit passt."},{"option":2,"text":"Eine auffällige Aussage weckt Aufmerksamkeit und wirkt, als müsse etwas dran sein. Dass sie auffällt, belegt aber nichts, und Menschen denken sich Dinge aus, irren sich oder scherzen. Je ungewöhnlicher die Behauptung, desto mehr Beleg braucht sie."}],"familie":"beweislast-klaeren","fertigkeit":"F1","quellen":[{"typ":"doi","kurz":"Deming, D. (2016): Do Extraordinary Claims Require Extraordinary Evidence? Philosophia 44(4), 1319–1331","oeffentlich":true,"doi":"10.1007/s11406-016-9779-7","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Sagan, C. (1995): The Demon-Haunted World. New York: Random House","oeffentlich":false}],"thema":"Psychologie"},{"id":"qx-a1-019","clusterId":"A","werkstueckRef":"A.4","stufe":3,"question":"Was ist an dieser Forderung fehlerhaft?","scenario":"In einer Debatte über einen Strafprozess sagt jemand: „Der Angeklagte soll beweisen, dass er unschuldig ist. Kann er das nicht lückenlos, gilt er eben als schuldig.“","options":["Sie kehrt die Beweislast um: Die Schuld muss belegt werden, nicht die Unschuld.","Sie ist im Kern berechtigt: Wer sich verteidigt, behauptet seine Unschuld und muss sie belegen.","Sie betrifft gar nicht die Beweislast: Es geht nur darum, wie stark die vorliegenden Indizien wiegen.","Sie ist bei schweren Taten berechtigt: Je schwerer der Vorwurf wiegt, desto eher muss der Angeklagte entlasten."],"correctIndex":0,"explanation":"Die Forderung verlangt, eine negative Behauptung („nicht schuldig“) lückenlos zu beweisen, und ein Nicht-Geschehen lässt sich kaum je lückenlos beweisen. Belegen muss grundsätzlich, wer etwas behauptet, hier also die Seite, die den Schuldvorwurf erhebt; im deutschen Strafverfahren müssen Staatsanwaltschaft und Gericht die Schuld von Amts wegen aufklären, und Zweifel gehen nach dem Grundsatz „im Zweifel für den Angeklagten“ nicht zu seinen Lasten. Genau diese Verteilung schützt die Unschuldsvermutung. Im privaten Glauben kann jeder annehmen, was er will; vor Gericht aber ist die Umkehr der Beweislast gefährlich, weil sie Unschuldige zu Verurteilten machen kann.","coreRule":"⚡ Wo über andere entschieden wird, trägt die Last, wer anklagt oder behauptet – nicht, wer sich verteidigt.","beleg":"Werkstück A.4 (Kontext & Tiefe; Der Kipppunkt)","status":"entwurf","kurz":"Wer etwas behauptet, muss es belegen, und das ist hier die Anklage mit ihrem Schuldvorwurf. Die Forderung dreht das um und verlangt, ein Nicht-Geschehen lückenlos zu beweisen, was kaum möglich ist und die Unschuldsvermutung aushebelt.","prueffrage":"Was müsste der Angeklagte vorlegen, um lückenlos zu zeigen, dass er etwas nicht getan hat?","rueckmeldung":[{"option":1,"text":"Sich zu verteidigen heißt nicht, etwas zu behaupten, das man belegen müsste: Der Vorwurf kommt von der Anklage, dort liegt die Last. Entlastendes darf der Angeklagte vorbringen, muss es aber nicht, und lückenlos ließe sich Unschuld kaum zeigen."},{"option":2,"text":"Indizien und ihre Würdigung gehören zum Verfahren, doch die Forderung ist gerade ein Streit um die Beweislast: Sie legt dem Angeklagten die Pflicht auf, seine Unschuld zu belegen. Wie Indizien gewichtet werden, ändert nichts daran, wer belegen muss."},{"option":3,"text":"Ein schwerer Vorwurf verlangt gründliche Aufklärung, aber durch die Anklage. Wo die Folgen für den Betroffenen am größten sind, ist die Unschuldsvermutung am wichtigsten; die Beweislast wandert nicht mit der Schwere der Tat."}],"familie":"beweislast-klaeren","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Europarat/EGMR: Europäische Menschenrechtskonvention (deutsche Fassung), Art. 6 Abs. 2","oeffentlich":true,"url":"https://www.echr.coe.int/documents/d/echr/convention_deu","abruf":"2026-10-12"},{"typ":"url","kurz":"Bundesministerium der Justiz: Strafprozessordnung § 160 (gesetze-im-internet.de)","oeffentlich":true,"url":"https://www.gesetze-im-internet.de/stpo/__160.html","abruf":"2026-10-12"},{"typ":"url","kurz":"Bundesministerium der Justiz: Strafprozessordnung § 244 (gesetze-im-internet.de)","oeffentlich":true,"url":"https://www.gesetze-im-internet.de/stpo/__244.html","abruf":"2026-10-12"}],"thema":"Zusammenleben"},{"id":"qx-a1-020","clusterId":"A","werkstueckRef":"A.4","stufe":4,"question":"Was ist an dieser Forderung der Kern des Denkfehlers?","scenario":"Jemand behauptet, die Mondlandung sei gefälscht. Als man ihm Belege zeigt, verlangt er: „Beweis mir mit hundertprozentiger Sicherheit, dass jeder einzelne Schatten auf den Fotos echt ist.“ Eigene Belege für die Fälschung nennt er nicht.","options":["Er verlangt von der Gegenseite lückenlose Gewissheit, statt seine eigene Behauptung zu belegen.","Er setzt die Fälschung bereits voraus und erklärt damit alle Fotos vorab für gefälscht, ohne sie zu prüfen.","Er unterstellt der Gegenseite eine Position, die sie nie vertreten hat, und widerlegt dann diese erfundene Position.","Er verlangt zu Recht Genauigkeit, denn solange nicht jedes Detail belegt ist, bleibt die Fälschungsthese gleichberechtigt."],"correctIndex":0,"explanation":"Wer eine außergewöhnliche Behauptung aufstellt, muss sie selbst belegen. Hier wird die Beweislast umgekehrt: Die Gegenseite soll etwas nahezu Unmögliches leisten, nämlich absolute Sicherheit in jedem Detail. Die gibt es in der realen Welt fast nie, auch nicht bei gut gesicherten Tatsachen. Dass einzelne Details offen bleiben, macht die Fälschungsthese nicht wahr. Sie braucht eigene, überprüfbare Belege. Und um eine unbelegte Behauptung zu verwerfen, muss man nicht erst das Gegenteil beweisen.","coreRule":"⚡ Lücken beim Gegenüber sind kein Beleg für die eigene These: Wer eine Fälschung behauptet, muss sie belegen.","beleg":"Werkstück A.4 (Anwendung & Relevanz: Bei Verschwörungsmythen; Red Flags)","status":"entwurf","quote":"","quoteLabel":"","kurz":"Wer eine Fälschung behauptet, muss sie selbst belegen. Der Denkfehler: Die Beweislast wird umgedreht, und die Gegenseite soll lückenlose Gewissheit liefern, die es selbst bei gesicherten Tatsachen fast nie gibt.","prueffrage":"Was wurde ihm an Belegen gezeigt, und auf welchen davon geht er in seiner Antwort ein?","rueckmeldung":[{"option":1,"text":"Dass er keine eigenen Belege nennt, stimmt. Er erklärt die Fotos aber nicht vorab für gefälscht, sondern stellt eine überzogene Forderung an die Gegenseite; der Kern liegt bei der Beweislast, nicht bei einem Zirkelschluss."},{"option":2,"text":"Ein Strohmann verzerrt die Position der Gegenseite, um sie leichter anzugreifen. Hier wird ihr aber nichts unterstellt: Er verlangt einen Beweis, der kaum zu liefern ist. Der Fehler liegt in seiner Forderung, nicht in einer Zuschreibung."},{"option":3,"text":"Genauigkeit zu verlangen ist an sich nicht falsch. Hundertprozentige Sicherheit in jedem Detail gibt es aber fast nie, auch bei gut gesicherten Tatsachen. Offene Details machen die Fälschungsthese nicht gleichberechtigt; sie braucht eigene Belege."}],"familie":"beweislast-klaeren","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Dowden, B.: Fallacies. Internet Encyclopedia of Philosophy (Einträge „Appeal to Ignorance“, „Misplaced Burden of Proof“)","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"}],"thema":"Geschichte und Wissenschaft"},{"id":"qx-a1-021","clusterId":"A","werkstueckRef":"A.5","stufe":1,"question":"Was ist die sparsamste Erklärung für diesen Zusammenhang?","scenario":"Im Vergleich von 17 europäischen Ländern hängen die Zahl der Storchenpaare und die Zahl der Geburten deutlich zusammen: Die Korrelation liegt bei 0,62 und ist statistisch signifikant. Ein Kommentator schreibt daraus: „Störche bringen eben doch die Babys.“","options":["Die Geburten ziehen die Störche an: Wo viele Kinder zur Welt kommen, siedeln sich dort mehr Störche an.","Die Landesgröße treibt beides an: Große Länder haben mehr Platz für Störche und mehr Einwohner.","Der Zufall erzeugt das Muster: Bei nur 17 Ländern kann eine Korrelation von 0,62 nicht bedeutsam sein.","Die Störche sind die Ursache: Ab einer Korrelation von etwa 0,6 gilt eine Wirkung als nachgewiesen."],"correctIndex":1,"explanation":"Die Korrelation ist echt: Sie wurde für 17 Länder berechnet (r = 0,62) und ist statistisch hochsignifikant. Daraus folgt aber nicht, dass Störche Babys bringen. Bei einem Zusammenhang zwischen A und B gibt es mindestens vier Möglichkeiten: A verursacht B, B verursacht A, ein dritter Faktor verursacht beide, oder es ist Zufall. Hier liegt ein dritter Faktor nahe: Große Länder haben mehr Platz für Störche und mehr Einwohner, also auch mehr Geburten. Die Landesgröße steckt hinter beiden Zahlen. Umgekehrte Kausalität ist logisch denkbar, aber unplausibel, denn es ist keine Wirkungskette erkennbar, wie Babys Störche herbeilocken sollten. Auch „reiner Zufall“ trägt nicht: Bei einem hochsignifikanten Zusammenhang ist Zufall keine tragfähige Erklärung. Und ein bestimmter Korrelationswert beweist nie eine Ursache, egal wie hoch er ist.","coreRule":"⚡ Bevor du A als Ursache von B nimmst, such nach einem Faktor C, der beide antreibt.","beleg":"Werkstück A.5 (Kontext & Tiefe: Ein dritter Faktor C); Fn. ga-stoerche (Matthews 2000, Teaching Statistics 22(2), S. 36–38; dt. Fassung 2001, S. 22)","status":"entwurf","kurz":"Bei zwei zusammenhängenden Zahlen kann ein dritter Faktor beide treiben: Große Länder haben mehr Platz für Störche und mehr Einwohner, also auch mehr Geburten. Der Fehler ist, aus dem echten Zusammenhang gleich eine Ursache zu machen.","prueffrage":"Worin unterscheiden sich die 17 Länder sonst noch, außer in der Zahl der Störche und der Geburten?","rueckmeldung":[{"option":0,"text":"Die Richtung lässt sich logisch umdrehen, und das ist bei Zusammenhängen immer zu bedenken. Hier ist aber keine Wirkungskette erkennbar, wie Geburten Störche herbeilocken sollten. Und ein gemeinsamer Hintergrund erklärt beide Zahlen einfacher."},{"option":2,"text":"Bei nur 17 Ländern ist Vorsicht angebracht, doch selbst bei so wenigen Werten ist eine Korrelation von 0,62 statistisch signifikant: Reiner Zufall würde sie nur selten erzeugen. Ein gemeinsamer Faktor liegt viel näher."},{"option":3,"text":"Der Zusammenhang selbst ist echt, nur der Schluss trägt nicht. Es gibt keinen Korrelationswert, ab dem eine Wirkung als nachgewiesen gilt, denn er beschreibt, dass zwei Zahlen zusammen steigen, aber nie, warum."}],"familie":"korrelation-und-ursache","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Matthews, R. (2001): Der Storch bringt die Babys zur Welt (p = 0.008). Stochastik in der Schule 21(2)","oeffentlich":true,"url":"https://www.stochastik-in-der-schule.de/sisonline/struktur/jahrgang21-2001/heft2/Langfassungen/2001-2_Matth.pdf","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Matthews, R. (2000): Storks Deliver Babies (p = 0.008). Teaching Statistics 22(2), 36–38","oeffentlich":false,"doi":"10.1111/1467-9639.00013"}],"thema":"Geld und Zahlen"},{"id":"qx-a1-022","clusterId":"A","werkstueckRef":"A.5","stufe":2,"question":"Was lässt sich aus diesem beobachteten Zusammenhang allein ableiten?","scenario":"Eine Schlagzeile lautet: „Menschen, die Diät-Cola trinken, wiegen im Schnitt mehr.“ Ein Kommentar folgert: „Diät-Cola macht dick.“","options":["Dass Diät-Cola dick macht, denn bei sehr vielen Beobachtungen wird aus einer Korrelation ein Kausalnachweis, auch ohne Vergleichsgruppe.","Dass Diät-Cola nicht dick machen kann, denn Süßstoffe ersetzen Zucker und können deshalb nichts bewirken.","Nichts über die Richtung: Es kann auch umgekehrt sein, denn wer abnehmen will, greift eher zur Diät-Cola.","Dass eine Gesundheitsbehörde den Zusammenhang schon eindeutig geklärt hat, denn Süßstoffe gelten dort als bewiesen schädlich."],"correctIndex":2,"explanation":"Eine Korrelation zwischen Diät-Cola-Konsum und Körpergewicht lässt zunächst offen, in welche Richtung der Zusammenhang läuft. Es ist ebenso gut möglich, dass Menschen, die mit ihrem Gewicht kämpfen und abnehmen wollen, häufiger zur Diät-Cola greifen: Dann verursacht das Gewicht den Konsum und nicht umgekehrt. Eine bloße Korrelation, auch aus vielen Beobachtungen, belegt noch keine Ursache; die Richtung bleibt offen. Ebenso falsch wäre der Gegenschluss, es könne gar keinen Effekt geben: In kurzen Versuchen senkten Süßstoffe das Gewicht leicht, aber nur gegenüber Zucker, wohl zumindest teils über weniger Kalorien. Die Sachfrage selbst ist offen: In Beobachtungsstudien ging mehr Süßstoff mit höherem BMI einher, umgekehrte Kausalität gilt der WHO aber nicht als alleinige Erklärung, und ihre bedingte Empfehlung gegen Süßstoffe zur Gewichtskontrolle stützt sich auf Evidenz geringer Sicherheit. Für die Frage zählt: Die Schlagzeile allein verrät nicht, was Ursache und was Wirkung ist.","coreRule":"⚡ Eine Korrelation zeigt keine Richtung: Frag auch, ob B der Grund für A sein kann.","beleg":"Werkstück A.5 (Kontext & Tiefe: Umgekehrte Kausalität); Fn. ga-suessstoff (WHO 2023, S. viii–xi und 14)","status":"entwurf","kurz":"Dass Menschen mit mehr Gewicht öfter Diät-Cola trinken, sagt noch nichts über die Richtung. Es kann ebenso sein, dass wer abnehmen will, eher zur Diät-Cola greift. Der Fehler wäre, aus dem Zusammentreffen gleich eine Ursache zu machen.","prueffrage":"Wurden dieselben Menschen nur einmal gewogen oder schon vor und nach dem Umstieg auf Diät-Cola?","rueckmeldung":[{"option":0,"text":"Viele Beobachtungen können den Zusammenhang selbst gut absichern. Sie klären aber nicht, was Ursache und was Wirkung ist: Auch eine sehr große Zahl von Beobachtungen macht eine Korrelation nicht zum Kausalbeleg."},{"option":1,"text":"Dass Süßstoffe Zucker ersetzen und so Kalorien sparen können, stimmt. Daraus folgt aber nicht, dass sie gar nichts bewirken: Ihre Langzeitwirkung auf das Gewicht ist offen, und „kann nicht dick machen“ ist so unbelegt wie „macht dick“."},{"option":3,"text":"Ein Behördenurteil klingt nach einem sicheren Anker. Geklärt ist die Frage aber nicht: Die WHO rät nur bedingt von Süßstoffen zur Gewichtskontrolle ab, gestützt auf Evidenz geringer Sicherheit, nicht auf einen Beweis."}],"familie":"korrelation-und-ursache","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"WHO (2023): Use of non-sugar sweeteners: WHO guideline","oeffentlich":true,"url":"https://www.who.int/publications/i/item/9789240073616","abruf":"2026-10-12"}],"thema":"Gesundheit"},{"id":"qx-a1-023","clusterId":"A","werkstueckRef":"A.5","stufe":3,"question":"Jemand sagt: „Dass Rauchen Lungenkrebs verursacht, ist nie in einem Experiment bewiesen worden, denn niemand kann Menschen per Los zum Rauchen verpflichten. Also ist es bis heute bloß eine Korrelation.“ Was ist an diesem Schluss fehlerhaft?","options":["Er übersieht, dass sich Kausalität auch ohne Experiment erhärten kann, wenn viele große, unabhängige Beobachtungsstudien über Jahrzehnte immer wieder dasselbe zeigen.","Er übersieht, dass jede Korrelation mit genügend großer Stichprobe automatisch zur Ursache wird, sobald der Zusammenhang statistisch signifikant ist.","Er übersieht, dass ein denkbarer Wirkungsweg allein schon genügt, um aus einer Korrelation eine gesicherte Ursache zu machen.","Er übersieht, dass ethisch problematische Experimente grundsätzlich nichts beweisen können und deshalb nur Beobachtungen zählen."],"correctIndex":0,"explanation":"Der Schluss behandelt „kein Losexperiment am Menschen“ als „kein Beweis“. Solche Experimente liefern zwar den saubersten Nachweis, sind aber nicht der einzige Weg. Beim Rauchen und Lungenkrebs kam der Beleg vor allem aus großen, jahrzehntelangen Beobachtungsstudien, deren Befunde sich immer wieder bestätigten; Tierversuche mit Tabakteer und der Nachweis krebserregender Stoffe im Rauch passten dazu. Eine einzelne Studie, eine große Stichprobe oder ein plausibler Mechanismus allein reichen dafür nicht. Der Satz „Korrelation ist nicht Kausalität“ verbietet also nicht, Ursachen zu erkennen, wenn die Evidenz so breit und beständig ist.","coreRule":"⚡ Auch ohne Experiment kann sich Kausalität belegen lassen: durch große, jahrzehntelange Beobachtungsstudien, deren Befunde sich immer wieder bestätigen.","beleg":"Werkstück A.5 (Kontext & Tiefe: A verursacht B); Werkstück A.2 (Ebene 3: Die Gefahr der „Störfaktoren“)","status":"entwurf","scenario":"","kurz":"Aus „kein Experiment“ folgt nicht „kein Beweis“. Beim Rauchen kam der Beleg vor allem aus vielen großen, unabhängigen Beobachtungsstudien über Jahrzehnte, gestützt durch Tierversuche. „Korrelation ist nicht Kausalität“ heißt nicht, dass Ursachen nie erkennbar wären.","prueffrage":"Welche Arten von Belegen außer einem Losexperiment lässt der Sprecher überhaupt gelten?","rueckmeldung":[{"option":1,"text":"Eine große Stichprobe und ein signifikanter Wert machen den Zusammenhang sicherer, aber nicht automatisch kausal. Störfaktoren bleiben, auch wenn die Zahl der Untersuchten riesig ist. Entscheidend ist, dass viele unabhängige Studien dasselbe zeigen."},{"option":2,"text":"Ein denkbarer Wirkungsweg macht eine Ursache plausibler, ist für sich genommen aber kein Beleg, denn plausible Erklärungen lassen sich fast immer finden. Erst im Zusammenspiel mit breiten, wiederholten Befunden wird daraus eine gesicherte Ursache."},{"option":3,"text":"Das Experiment wäre der sauberste Nachweis. Dass man es aus ethischen Gründen nicht durchführt, entwertet es nicht, es fehlt nur. Beobachtungsstudien können Ursachen erhärten, ohne dass Experimente „nichts beweisen“."}],"familie":"korrelation-und-ursache","fertigkeit":"F2","quellen":[{"typ":"doi","kurz":"Parascandola, M.; Weed, D. L.; Dasgupta, A. (2006): Two Surgeon General's reports on smoking and cancer: a historical investigation of the practice of causal inference. Emerging Themes in Epidemiology 3:1","oeffentlich":true,"doi":"10.1186/1742-7622-3-1","abruf":"2026-10-12"},{"typ":"doi","kurz":"Doll, R.; Peto, R.; Boreham, J.; Sutherland, I. (2004): Mortality in relation to smoking: 50 years' observations on male British doctors. BMJ 328, 1519","oeffentlich":true,"doi":"10.1136/bmj.38142.554479.AE","abruf":"2026-10-12"},{"typ":"doi","kurz":"Doll, R.; Hill, A. B. (1950): Smoking and carcinoma of the lung; preliminary report. BMJ 2(4682), 739–748","oeffentlich":true,"doi":"10.1136/bmj.2.4682.739","abruf":"2026-10-12"}],"thema":"Gesundheit"},{"id":"qx-a1-024","clusterId":"A","werkstueckRef":"A.5","stufe":4,"question":"Wie beurteilst du diesen Schluss?","scenario":"Eltern berichten: Kurz nach der Impfung ihres Kindes seien erste Anzeichen von Autismus bemerkt worden. Sie schließen daraus, die Impfung sei die Ursache.","options":["Er ist nicht belegt, weil erste Anzeichen oft genau in dem Alter auftreten, in dem auch geimpft wird, und große Studien keinen ursächlichen Zusammenhang fanden.","Er ist belegt, weil eine Veränderung unmittelbar nach einem Ereignis jede andere Erklärung ausschließt, ganz gleich, wie viele Kinder sonst betroffen sind.","Er ist wertlos, weil Elternberichte zu Zeitpunkten keinerlei Aussagewert haben und die Erinnerung an Zeitpunkte grundsätzlich unzuverlässig ist.","Er bleibt offen, weil Beobachtungsstudien nichts widerlegen können und die Frage deshalb grundsätzlich unentschieden ist, auch bei sehr großen Studien."],"correctIndex":0,"explanation":"Das ist der klassische Post-hoc-Fehlschluss („danach, also deswegen“). Das zeitliche Zusammentreffen erklärt sich dadurch, dass erste Anzeichen von Autismus oft genau in dem Alter auftreten, in dem auch geimpft wird. Es ist eine zeitliche Korrelation, kein Beleg für Kausalität. Einen ursächlichen Zusammenhang haben große Studien immer wieder gesucht und nicht gefunden: In einer dänischen Studie mit 657.461 Kindern lag das Hazard Ratio für Autismus nach der Masern-Mumps-Röteln-Impfung bei 0,93; die Studie fand kein erhöhtes Autismusrisiko. Der Fehlschluss liegt in der Ableitung einer Ursache aus der zeitlichen Abfolge.","coreRule":"⚡ „Danach“ heißt nicht „deswegen“. Prüfe, ob der Zeitpunkt ohnehin zusammenfällt, und frag nach Vergleichen mit vielen Fällen.","beleg":"Werkstück A.5 (Anwendung & Relevanz: Bei der Anti-Impf-Bewegung); Fn. ga-hviid (Hviid u. a. 2019, Annals of Internal Medicine 170(8), S. 513–520)","status":"entwurf","kurz":"Dass eine Veränderung auf ein Ereignis folgt, zeigt noch keine Ursache. Erste Anzeichen treten oft genau im Impfalter auf, und große Studien fanden keinen ursächlichen Zusammenhang. Der Fehler: aus „danach“ ein „deswegen“ zu machen.","prueffrage":"Wie viele Kinder bekommen dieselbe Impfung, ohne dass danach irgendetwas auffällt?","rueckmeldung":[{"option":1,"text":"Dass es unmittelbar danach auffiel, wirkt wie ein starkes Indiz, und die Beobachtung der Eltern kann stimmen. Doch eine zeitliche Abfolge schließt andere Erklärungen nicht aus: Erste Anzeichen zeigen sich oft genau im Impfalter."},{"option":2,"text":"Vorsicht gegenüber einzelnen Berichten ist berechtigt, denn sie belegen keine Ursache. Sie sind aber nicht wertlos und die Erinnerung nicht grundsätzlich unzuverlässig. Schwach ist der Schluss auf Kausalität, nicht die Glaubwürdigkeit der Eltern."},{"option":3,"text":"Beobachtungsstudien beweisen Ursachen tatsächlich nicht endgültig. Sie können einen nennenswerten Zusammenhang aber sehr unwahrscheinlich machen: Eine dänische Studie mit über 650.000 Kindern fand kein erhöhtes Autismusrisiko."}],"familie":"was-waere-ohne","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Hviid, A.; Hansen, J. V.; Frisch, M.; Melbye, M. (2019): Measles, Mumps, Rubella Vaccination and Autism: A Nationwide Cohort Study. Annals of Internal Medicine 170(8), 513–520 (Abstract)","oeffentlich":true,"doi":"10.7326/M18-2101","url":"https://pubmed.ncbi.nlm.nih.gov/30831578/","abruf":"2026-10-12"}],"thema":"Gesundheit"},{"id":"qx-a1-025","clusterId":"A","werkstueckRef":"A.6","stufe":1,"question":"Was erklärt diese Entwicklung am besten?","options":["Die neue Fahrspur war zu schmal geplant, und deshalb konnte sie den Verkehr nicht aufnehmen.","Die Bauarbeiten haben den Verkehr zunächst behindert, und danach haben sich die Autofahrer an die Lage gewöhnt.","Die neue Fahrspur hat das Autofahren attraktiver gemacht, und deshalb sind mehr Menschen gefahren, bis der Stau wieder da war.","Der Stau war schon immer unvermeidlich, und deshalb bleibt jede einzelne Maßnahme dagegen ohne Wirkung."],"correctIndex":2,"explanation":"Die Maßnahme setzt vermutlich eine verstärkende Schleife in Gang: Mehr Kapazität macht das Autofahren attraktiver, mehr Menschen fahren, und dadurch steigt die Auslastung, bis der Gewinn aufgezehrt ist. Der Plan betrachtete nur die direkte Kette „mehr Platz, weniger Stau“ und übersah die Rückkopplung samt Zeitverzögerung. Die anderen Erklärungen bleiben bei einzelnen Teilen oder bei einer einzigen Ursache stehen: Eine zu schmale Spur oder die Gewöhnung an eine Baustelle erklären nicht, warum das Verkehrsaufkommen insgesamt steigt, und die Behauptung, jede Maßnahme sei wirkungslos, ist eine Ausrede statt einer Erklärung, die zum Beobachteten passt. Wer so einen Eingriff plant, fragt deshalb nicht nur nach der direkten Folge, sondern auch nach den Folgen der Folgen.","coreRule":"⚡ Wer nur die direkte Ursache-Wirkungs-Kette betrachtet, übersieht Rückkopplungen und Verzögerungen. Frage: Was sind die Konsequenzen der Konsequenzen?","quote":"Lineares Denken sieht einen fallenden Dominostein. Systemdenken sieht ein Spinnennetz: Zupft man an einer Stelle, vibriert das ganze Netz.","quoteLabel":"Zum Weiterdenken:","beleg":"Werkstück A.6 (Kernidee; Kontext & Tiefe; Red Flags)","status":"entwurf","scenario":"Eine Stadt will die Staus in der Innenstadt bekämpfen und baut eine zusätzliche Fahrspur. Der Stadtrat verlässt sich dabei auf eine einfache Rechnung: Mehr Fahrspuren bedeuten mehr Platz, mehr Platz bedeutet weniger Stau. Zwei Jahre später steht die Innenstadt wieder im Stau, und das Verkehrsaufkommen insgesamt ist gestiegen.","kurz":"Mehr Fahrspuren machen das Autofahren attraktiver, also fahren mehr Menschen, bis der Stau wieder da ist. Der Plan sah nur „mehr Platz, weniger Stau“ und übersah diese Rückkopplung, die erst mit Verzögerung sichtbar wird.","prueffrage":"Wie verlief der Stau in den zwei Jahren nach dem Ausbau: Kam er sofort zurück oder erst nach und nach?","rueckmeldung":[{"option":0,"text":"Eine zu schmale Spur würde erklären, warum die Kapazität gering bleibt. Sie erklärt aber nicht, warum das Verkehrsaufkommen insgesamt gestiegen ist, und genau das ist hier das Auffällige."},{"option":1,"text":"Eine Baustelle stört den Verkehr nur für eine begrenzte Zeit, zwei Jahre später wirkt sie kaum noch nach. Und Gewöhnung erklärt, warum Leute ausharren, aber nicht, warum insgesamt mehr gefahren wird."},{"option":3,"text":"„Unvermeidlich“ und „jede Maßnahme wirkungslos“ klingen nach Erfahrung, erklären aber nichts. Sie lassen offen, warum der Verkehr gerade nach dem Ausbau gestiegen ist, und passen deshalb nicht zum Beobachteten."}],"familie":"systemisch-denken","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"Duranton, G.; Turner, M. A. (2009): The Fundamental Law of Road Congestion: Evidence from US Cities. NBER Working Paper 15376 (später American Economic Review 2011)","oeffentlich":true,"url":"https://www.nber.org/papers/w15376","abruf":"2026-10-12"},{"typ":"url","kurz":"Meadows, D.: Leverage Points: Places to Intervene in a System. Donella Meadows Project","oeffentlich":true,"url":"https://donellameadows.org/archives/leverage-points-places-to-intervene-in-a-system/","abruf":"2026-10-12"}],"thema":"Zusammenleben"},{"id":"qx-a1-026","clusterId":"A","werkstueckRef":"A.6","stufe":2,"question":"Welche Erklärung beschreibt am besten, was hier geschieht und warum die Hilfe nach hinten losgeht?","scenario":"Eine Hilfsorganisation verschenkt kostenlos Güter in einem armen Land, um die Armut zu lindern. In den ersten Monaten sieht das nach einem Erfolg aus. Nach einigen Jahren geht es der lokalen Wirtschaft jedoch schlechter als zuvor, und die Armut ist gewachsen. Ein Mitarbeiter schlägt vor: „Wir müssen einfach mehr verteilen.“","options":["Die Menge war zu klein: Mit doppelt so vielen Gütern hätte sich die lokale Wirtschaft erholt, weil die Armut dann schneller gesunken und die Nachfrage gestiegen wäre.","Die Verschlechterung ist nur scheinbar: Hilfe zeigt grundsätzlich erst nach Jahren Wirkung, die aktuelle Entwicklung ist deshalb kein Grund zur Sorge.","Die kostenlosen Güter unterbieten lokale Anbieter, deren Einkommen sinkt, die Armut wächst und mit ihr der Hilfsbedarf: Die Hilfe verstärkt das Problem, das sie lösen soll.","Ein einzelner Verteilungsfehler ist schuld: Das Problem liegt bei der Auslieferung, die Wirtschaft selbst blieb von der Hilfe unberührt."],"correctIndex":2,"explanation":"Wer ein Symptom (Armut) direkt bekämpft, ohne das System zu betrachten, übersieht Rückwirkungen: Kostenlose Güter unterbieten die lokale Wirtschaft, sie bricht zusammen, und langfristig wächst die Armut weiter. Das ist eine verstärkende Rückkopplungsschleife. Da die Hilfe selbst Teil dieser Schleife ist, ist mehr vom Gleichen kaum eine Lösung. Zeitverzögerungen gibt es zwar in Systemen, aber hier wird die Lage schlechter als vor der Hilfe. Das spricht dafür, dass die Hilfe selbst die Rückkopplung auslöst, und nicht dafür, dass man nur abwarten müsste. Und wer nur einen Verteilungsfehler sucht, behandelt die Wirtschaft wie ein unbeteiligtes Zahnrad statt wie ein System, das auf Eingriffe reagiert. Ein Systemdenker erwartet solche unbeabsichtigten Nebenwirkungen und fragt nach den Konsequenzen der Konsequenzen.","coreRule":"⚡ Wer nur ein Symptom behandelt, setzt oft eine Schleife in Gang, die das Problem verschärft.","beleg":"Werkstück A.6 (Anwendung & Relevanz: Bei sozialen und politischen Problemen)","status":"entwurf","kurz":"Die Hilfe löst die Schleife selbst aus: Kostenlose Güter unterbieten lokale Anbieter, deren Einkommen sinkt, die Armut wächst, und der Hilfsbedarf mit ihr. Der naheliegende Fehler ist, nur das Symptom Armut zu bekämpfen, ohne die Rückwirkung auf das System zu bedenken.","prueffrage":"Welche Kennzahlen der lokalen Wirtschaft haben sich nach Beginn der Verteilung zuerst verschlechtert, und in welchen Branchen?","rueckmeldung":[{"option":0,"text":"Mehr Güter wirken wie ein größerer Hebel, doch derselbe Mechanismus würde sich verstärken: Noch mehr Gratisware drückt die lokalen Anbieter noch stärker, und schon die bisherige Menge ging mit wachsender Armut einher."},{"option":1,"text":"Zeitverzögerungen gibt es in Systemen tatsächlich, und Hilfe braucht manchmal Zeit. Hier steht es aber schlechter als vor der Hilfe, und das spricht dafür, dass die Hilfe selbst die Verschlechterung auslöst, nicht dafür, dass sich Abwarten lohnt."},{"option":3,"text":"Auslieferungsfehler kommen vor, doch von einem ist hier nirgends die Rede. Und die Wirtschaft bleibt nicht unberührt: Dass es ihr nach den Gratisgütern schlechter geht als zuvor, spricht dafür, dass sie auf den Eingriff reagiert hat."}],"familie":"systemisch-denken","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"Frazer, G. (2008): Used-Clothing Donations and Apparel Production in Africa. Economic Journal 118(532), 1764–1784 (Abstract, IDEAS/RePEc)","oeffentlich":true,"url":"https://ideas.repec.org/a/ecj/econjl/v118y2008i532p1764-1784.html","abruf":"2026-10-12"},{"typ":"url","kurz":"Meadows, D.: Leverage Points: Places to Intervene in a System. Donella Meadows Project","oeffentlich":true,"url":"https://donellameadows.org/archives/leverage-points-places-to-intervene-in-a-system/","abruf":"2026-10-12"}],"thema":"Geld und Zahlen"},{"id":"qx-a1-027","clusterId":"A","werkstueckRef":"A.6","stufe":3,"question":"Was ist an dieser Schlussfolgerung fehlerhaft?","scenario":"In einer Sitzung geht es um ein Problem, an dem viele Faktoren beteiligt sind. Jemand sagt: „Das ist ein komplexes System, da können wir ohnehin nichts bewirken – also lassen wir es.“","options":["Aus Komplexität folgt nicht, dass Handeln sinnlos ist: Man kann Teile einzeln untersuchen und zugleich prüfen, wie sie ins Ganze passen, und so überlegt eingreifen.","Sie ist folgerichtig: Wo viele Wechselwirkungen bestehen, schaden Eingriffe meist mehr, als sie nützen, daher ist Zurückhaltung geboten und Handeln unklug.","Sie ist falsch, weil man in komplexen Systemen einzelne Teile nie für sich untersuchen darf, da jede Einzelanalyse das Gesamtbild verzerrt und täuscht.","Sie ist ein Zeichen zu detailverliebten Denkens: Wer zu viele Einzelheiten analysiert, verliert das Gesamtbild und sollte deshalb lieber zügig handeln."],"correctIndex":0,"explanation":"Die Aussage schließt von „komplex“ auf „nichts zu bewirken“ – das ist ein Fehlschluss. Komplexität heißt, dass Wirkungen verzögert, indirekt und mit Rückkopplungen auftreten und dass es unbeabsichtigte Nebenwirkungen geben kann. Das ist ein Grund, sorgfältiger vorzugehen, kein Grund, nichts zu tun. Sinnvoll ist ein Wechsel der Perspektive: Ein einzelnes Teil lässt sich isoliert analysieren (wie ein Zahnrad), und danach fragt man, wie es mit dem Ganzen zusammenhängt (wie das Zahnrad im Uhrwerk). So entstehen überlegte Eingriffe, die sowohl das einzelne Teil als auch sein Zusammenspiel im Ganzen berücksichtigen. Wer Komplexität als Ausrede für Untätigkeit benutzt, macht das Denkwerkzeug selbst zum Hindernis.","coreRule":"⚡ Komplexität ist ein Grund für sorgfältiges Handeln, nicht für Untätigkeit – wechsle zwischen Teil und Ganzem.","beleg":"Werkstück A.6 (Der Kipppunkt: Systemdenken als Ausrede für Untätigkeit; Wechsel zwischen reduktionistischer Analyse und systemischer Synthese)","status":"entwurf","quote":"","quoteLabel":"","kurz":"Aus „komplex“ folgt nicht „nichts zu bewirken“. Verzögerte Wirkungen und Nebenwirkungen sind ein Grund, sorgfältiger vorzugehen, etwa ein Teil einzeln zu untersuchen und dann zu fragen, wie es ins Ganze passt, nicht ein Grund, nichts zu tun.","prueffrage":"Gab es bei ähnlich verzweigten Problemen schon Eingriffe, die etwas bewirkt haben, und woran ließ sich das ablesen?","rueckmeldung":[{"option":1,"text":"Dass Eingriffe in vernetzten Systemen Nebenwirkungen haben können, stimmt. Daraus folgt aber Sorgfalt, nicht, dass Handeln meist schadet oder unklug wäre. Auch dieser Schluss verwandelt Komplexität in einen Grund, nichts zu tun."},{"option":2,"text":"Die Einzelanalyse allein reicht in der Tat nicht, denn das Zusammenspiel zählt. Sie ist aber nicht verboten: Ein Teil lässt sich durchaus für sich untersuchen, wenn man danach fragt, wie es mit dem Ganzen zusammenhängt."},{"option":3,"text":"Im Satz ist von zu vielen Einzelheiten nichts zu sehen; er verzichtet auf jede Analyse. Auch zügiges Handeln ohne Prüfung wäre hier der falsche Rat, denn gerade bei vielen Wechselwirkungen braucht es sorgfältiges Vorgehen."}],"familie":"systemisch-denken","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"Meadows, D.: Dancing With Systems. Donella Meadows Project","oeffentlich":true,"url":"https://donellameadows.org/archives/dancing-with-systems/","abruf":"2026-10-12"},{"typ":"url","kurz":"Meadows, D.: Leverage Points: Places to Intervene in a System. Donella Meadows Project","oeffentlich":true,"url":"https://donellameadows.org/archives/leverage-points-places-to-intervene-in-a-system/","abruf":"2026-10-12"}],"thema":"Zusammenleben"},{"id":"qx-a1-028","clusterId":"A","werkstueckRef":"A.6","stufe":4,"question":"Wie bewertest du diese Behauptung am sinnvollsten?","scenario":"Ein viral geteiltes Video behauptet: „Als in Yellowstone wieder Wölfe angesiedelt wurden, haben sie sogar den Lauf der Flüsse verändert.“ Du weißt: Es gab dort zeitgleich auch Jagd, Dürrejahre, Bären und Pumas, und in der Umgebung wurden Biber ausgewildert.","options":["Die Behauptung ist vollständig belegt: Die Wölfe allein haben die Landschaft umgebaut, und unter Fachleuten gibt es keinen Streit über die Stärke der Wirkung.","Die Wirkkette über Hirsche und Pflanzen gilt als weitgehend unstrittig, ihre Stärke ist umstritten, und der veränderte Flusslauf gilt als überzeichnet.","Die Behauptung ist frei erfunden: Die Wiederansiedlung hatte keine messbare Wirkung auf Hirsche oder Pflanzen, und jede angebliche Kette von Folgen ist Einbildung.","Die Behauptung ist aus anderem Grund halbwahr: Entscheidend war allein die Zahl der Biber, und die Wölfe spielten für die Veränderungen im Park keine Rolle."],"correctIndex":1,"explanation":"In einem System wirkt selten nur eine einzige Ursache. Die Behauptung nimmt eine plausible Wirkkette (Wölfe, weniger Hirsche, erholte Weiden, mehr Biber) und kürzt sie zur Ein-Ursache-Story, bis hin zum veränderten Flusslauf. Dagegen sprechen mehrere Mitverursacher: Jagd, Dürrejahre, Bären und Pumas hatten ebenfalls ihren Anteil am Rückgang der Hirsche, die Weiden erholten sich nur stellenweise, und Biber profitierten auch von Auswilderungen in der Umgebung. Ökologen halten eine Kaskade vom Wolf zur Vegetation weitgehend für unstrittig, streiten aber über ihre Stärke (Ripple/Beschta 2012 für eine starke, Brice u. a. 2022 für eine überschätzte Kaskade). Die Flusslauf-Aussage stammt aus einer populären Zuspitzung und gilt als deutlich überzeichnet. Die Aussagen „vollständig belegt“ und „frei erfunden“ verfehlen beide den Stand der Dinge, und „allein die Biber“ ersetzt nur eine Einzelursache durch eine andere.","coreRule":"⚡ Auch die schönste Kaskade hat mehrere Ursachen: Prüfe, wie stark der Einzelfaktor wirklich wirkt und was sonst noch mitspielt.","beleg":"Werkstück A.6 (Der Wolf und der Fluss); Fn. ga-yellowstone (Ripple/Beschta 2012, Biological Conservation 145(1), S. 205–213; Brice u. a. 2022, Ecology Letters 25(1), S. 177–188)","status":"entwurf","kurz":"In einem System wirkt selten nur eine Ursache: Die Kette von den Wölfen über Hirsche zu den Pflanzen gilt als weitgehend unstrittig, ihre Stärke als umstritten, der Flusslauf als überzeichnet. Der Fehler liegt darin, sie zur Ein-Ursache-Geschichte zu kürzen.","prueffrage":"Was geschah im selben Zeitraum in Yellowstone und seiner Umgebung noch, das dieselben Veränderungen erklären könnte?","rueckmeldung":[{"option":0,"text":"Eine Wirkung der Wölfe ist plausibel, und gerade das macht die Geschichte glaubwürdig. „Vollständig belegt“ und „allein“ tragen aber nicht: Jagd, Dürrejahre, Bären, Pumas und Biber-Auswilderungen wirkten mit, und über die Stärke wird gestritten."},{"option":2,"text":"Am Flusslauf ist die Behauptung tatsächlich stark überzeichnet, und so liegt der Schluss auf „erfunden“ nahe. Die Kette von den Wölfen über Hirsche zu den Pflanzen gilt aber als weitgehend unstrittig; offen ist ihre Stärke, nicht ihr Dasein."},{"option":3,"text":"Dass Biber auch durch Auswilderungen in der Umgebung profitierten, ist richtig und zeigt die Verkürzung der Behauptung. „Allein die Biber“ ersetzt aber nur eine Einzelursache durch eine andere und streicht die Wölfe, die an der Kette beteiligt sind."}],"familie":"monokausal-erkennen","fertigkeit":"F2","quellen":[{"typ":"doi","kurz":"Brice, E. M.; Larsen, E. J.; MacNulty, D. R. (2022): Sampling bias exaggerates a textbook example of a trophic cascade. Ecology Letters 25(1), 177–188","oeffentlich":true,"doi":"10.1111/ele.13915","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Ripple, W. J.; Beschta, R. L. (2012): Trophic cascades in Yellowstone: The first 15 years after wolf reintroduction. Biological Conservation 145(1), 205–213","oeffentlich":false,"doi":"10.1016/j.biocon.2011.11.005"},{"typ":"literatur","kurz":"Smith, D. W.; Tyers, D. B. (2012): The History and Current Status and Distribution of Beavers in Yellowstone National Park. Northwest Science 86(4)","oeffentlich":false,"doi":"10.3955/046.086.0404"}],"thema":"Natur und Klima"},{"id":"qx-a1-029","clusterId":"A","werkstueckRef":"A.7","stufe":1,"question":"Was wäre jetzt die vernünftigste Reaktion deines Kollegen?","scenario":"Ein Kollege sagt in der Besprechung: „Es ist zu 100 % sicher, dass das neue Produkt floppt.“ Du fragst ihn, wie sicher er sich auf einer Skala von 1 bis 100 wirklich ist. Er antwortet nach kurzem Zögern: „Na ja, vielleicht 70.“ Kurz darauf kommen erste Rückmeldungen aus einem Testmarkt: Die Kundschaft reagiert deutlich besser als erwartet.","options":["Seine Einschätzung nach unten anpassen, etwa auf 50 %, weil die neuen Rückmeldungen gegen einen Flop sprechen, aber nur ein Testmarkt noch nicht reicht.","Bei seiner Einschätzung bleiben und die Rückmeldungen ignorieren, weil eine frühe Festlegung im Team Verlässlichkeit und Klarheit zeigt.","Auf 0 % herunterkorrigieren und das Produkt als sicheren Erfolg bezeichnen, weil die Rückmeldungen aus dem Testmarkt eindeutig sind.","Gar keine Einschätzung mehr abgeben, weil sich mit unvollständigen Daten jede Zahl später als falsch herausstellen kann."],"correctIndex":0,"explanation":"Eine Einschätzung ist ein Vertrauensgrad, der auf der Basis neuer Informationen angepasst werden sollte. Die Rückmeldungen sprechen gegen den Flop, also darf der Wert sinken. Dabei kippt er nicht in ein neues Extrem: Wer wegen eines einzigen Hinweises von „sicher Flop“ auf „sicherer Erfolg“ springt, ersetzt die eine Gewissheit durch die nächste. Wer an der alten Zahl klebt, behandelt sie wie eine Gewissheit. Und wer sich gar nicht mehr äußert, entzieht sich der Prüfung. Wie hoch der neue Wert genau liegt, ist eine Einschätzungsfrage; entscheidend ist, dass er sich mit den neuen Informationen bewegt. Handeln bei Unsicherheit gelingt gerade dadurch, dass man ausdrückt, wie sicher man ist, und bereit bleibt, die Zahl zu korrigieren.","coreRule":"⚡ Sag nicht „sicher“ oder „unmöglich“, sondern wie sicher – und passe die Zahl an, wenn neue Hinweise kommen.","beleg":"Werkstück A.7 (Kernidee; Red Flags)","status":"entwurf","kurz":"Die Rückmeldungen sprechen gegen einen Flop, also darf die Einschätzung sinken, aber nicht ins Gegenteil kippen. Sonst ersetzt man die alte Gewissheit durch eine neue; eine Zahl ist ein Vertrauensgrad, der sich mit den Informationen bewegen soll.","prueffrage":"Wie gut haben Testmärkte bei früheren Produkten vorhergesagt, ob diese später floppten?","rueckmeldung":[{"option":1,"text":"Eine feste Linie wirkt im Team souverän und klar. Aber wer trotz deutlich besserer Rückmeldungen bei seiner Zahl bleibt, behandelt sie wie eine Gewissheit; verlässlich wird man dadurch, dass man Änderungen der Einschätzung nachvollziehbar begründet."},{"option":2,"text":"Die Richtung stimmt: Die Rückmeldungen sprechen gegen den Flop, also darf der Wert sinken. Ein Sprung auf 0 % macht aus einem einzelnen Testmarkt aber eine neue Gewissheit und ersetzt die alte Sicherheit nur durch das Gegenteil."},{"option":3,"text":"Dass sich eine Zahl später als falsch erweisen kann, stimmt. Genau deshalb gehört sie aber offen auf den Tisch: Wer keine Einschätzung mehr nennt, entzieht sich der Prüfung, statt sie bei neuen Daten anzupassen."}],"familie":"gewissheit-kalibrieren","fertigkeit":"F5","quellen":[{"typ":"url","kurz":"Joyce, J.: Bayes' Theorem. Stanford Encyclopedia of Philosophy (Erstveröffentlichung 2003)","oeffentlich":true,"url":"https://plato.stanford.edu/entries/bayes-theorem/","abruf":"2026-10-12"},{"typ":"doi","kurz":"Atanasov, P.; Witkowski, J.; Ungar, L.; Mellers, B.; Tetlock, P. (2020): Small steps to accuracy: Incremental belief updaters are better forecasters. Organizational Behavior and Human Decision Processes 160, 19–35","oeffentlich":true,"doi":"10.1016/j.obhdp.2020.02.001","url":"https://faculty.wharton.upenn.edu/wp-content/uploads/2022/03/1-s2.0-S0749597819300949-main.pdf","seite":"S. 19 (Abstract)","abruf":"2026-10-12"}],"thema":"Zusammenleben"},{"id":"qx-a1-030","clusterId":"A","werkstueckRef":"A.7","stufe":2,"question":"Wie solltest du dein Vertrauen in die Meldung ansetzen und anpassen?","scenario":"Eine Freundin schickt dir eine schockierende Schlagzeile von einer Seite, die in der Vergangenheit überwiegend Falsches veröffentlicht hat. Sie schreibt: „Das ist bestimmt wahr, so etwas würde niemand erfinden.“ Weitere Belege nennt sie nicht.","options":["Zunächst hoch, weil eine schockierende Meldung so wichtig wirkt, dass man sie ernst nehmen muss; dass die Quelle früher oft Falsches brachte, ändert am Einzelfall nichts.","Zunächst bei 50 %, weil du ohne eigene Beweise weder für noch gegen die Meldung sprechen kannst und beide Seiten gleich plausibel sind.","Zunächst niedrig, weil Meldungen dieser Quelle nur selten zutreffen; erst weitere, bessere Belege würden dein Vertrauen anheben.","Gar nicht einschätzbar, weil eine Meldung entweder wahr oder falsch ist und Wahrscheinlichkeiten bei einer einzelnen Nachricht nichts nützen."],"correctIndex":2,"explanation":"Der sinnvolle Ausgangspunkt ist die Basisrate: Wie oft stimmen Meldungen dieser Art von dieser Quelle? Ist die Rate gering, ist auch das anfängliche Vertrauen gering, wie dramatisch die Schlagzeile auch klingt, denn dass sie schockiert, macht sie nur auffälliger, nicht wahrscheinlicher. Ein Vertrauen von 50 % wäre nur angemessen, wenn Meldungen der Quelle etwa zur Hälfte stimmten. Dass eine Meldung am Ende wahr oder falsch ist, schließt Wahrscheinlichkeiten nicht aus: Sie beschreiben deinen Wissensstand, nicht die Natur der Sache. Neue Belege verschieben den Ausgangswert, ersetzen ihn aber nicht: Trifft eine Krankheit nur einen von 10 000 Menschen, hebt selbst ein positives Ergebnis eines Tests, der in 99 % der Fälle richtig liegt, die Wahrscheinlichkeit nur auf knapp 1 %.","coreRule":"⚡ Beginne mit der Basisrate der Quelle und lass nur bessere Belege dein Vertrauen heben.","beleg":"Werkstück A.7 (Anwendung & Relevanz: Bei Fake News; Das Anti-Denkmuster)","status":"entwurf","kurz":"Den Ausgangspunkt setzt die Trefferquote der Quelle: Stimmen ihre Meldungen selten, ist dein Vertrauen zunächst gering. Ein schockierender Inhalt macht eine Meldung nicht wahrscheinlicher, nur auffälliger. Erst bessere Belege heben das Vertrauen.","prueffrage":"Was wusstest du über diese Seite schon, bevor deine Freundin dir die Schlagzeile schickte?","rueckmeldung":[{"option":0,"text":"Eine wichtige Meldung verdient Aufmerksamkeit und eine Prüfung. Wie groß das Vertrauen sein sollte, bestimmt aber nicht die Schockwirkung, sondern die frühere Trefferquote der Quelle, und die ändert sehr wohl etwas am Einzelfall."},{"option":1,"text":"Ohne eigene Beweise wirken 50 % neutral und fair. Gleich plausibel sind beide Seiten aber nur, wenn die Quelle etwa zur Hälfte recht hätte. Ihre Bilanz ist bekannt und schlecht, deshalb liegt der Ausgangswert deutlich darunter."},{"option":3,"text":"Am Ende ist die Meldung tatsächlich entweder wahr oder falsch. Wahrscheinlichkeiten beschreiben aber deinen Wissensstand, nicht die Sache selbst, und die Bilanz der Quelle gibt dir dafür einen brauchbaren Anhaltspunkt."}],"familie":"basisrate-beachten","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"Joyce, J.: Bayes' Theorem. Stanford Encyclopedia of Philosophy","oeffentlich":true,"url":"https://plato.stanford.edu/entries/bayes-theorem/","abruf":"2026-10-12"},{"typ":"doi","kurz":"Gigerenzer, G.; Gaissmaier, W.; Kurz-Milcke, E.; Schwartz, L. M.; Woloshin, S. (2007): Helping Doctors and Patients Make Sense of Health Statistics. Psychological Science in the Public Interest 8(2), 53–96","oeffentlich":true,"doi":"10.1111/j.1539-6053.2008.00033.x","url":"https://kops.uni-konstanz.de/entities/publication/1c820f2d-aeed-4bfd-b65b-0e3f86803750/full","abruf":"2026-10-12"}],"thema":"Netz und Medien"},{"id":"qx-a1-031","clusterId":"A","werkstueckRef":"A.7","stufe":3,"question":"Was ist an dieser Haltung des Teams ein Denkfehler?","scenario":"Euer Team soll bis Freitag entscheiden, ob es ein Angebot annimmt. Seit drei Wochen rechnet ihr Wahrscheinlichkeiten für jede denkbare Folge durch. Eine Kollegin sagt: „Wir entscheiden erst, wenn wir die Wahrscheinlichkeiten ganz genau kennen.“ Neue Informationen sind in absehbarer Zeit nicht zu erwarten.","options":["Das Team verwechselt Abwägen mit Entscheiden: Wer nie auf unvollständiger Grundlage handelt, bleibt handlungsunfähig.","Das Team verwechselt Rechnen mit Wissen: Sobald man Wahrscheinlichkeiten nennt, wird die Entscheidung unsicherer als nach Bauchgefühl.","Das Team verwechselt Wahrscheinlichkeit mit Gewissheit: Erst ab 50 % darf man eine Folge wie eine Tatsache behandeln.","Das Team verwechselt Sorgfalt mit Qualität: Je mehr man berechnet, desto besser wird die Entscheidung, bis eine sichere Zahl vorliegt."],"correctIndex":0,"explanation":"Das Team rechnet seit Wochen und entscheidet nicht. Im Alltag müssen wir oft Entscheidungen auf der Grundlage unvollständiger Informationen treffen. Der Punkt ist nicht, niemals zu handeln, sondern sich des Unsicherheitsgrades bewusst zu sein. Wahrscheinlichkeiten machen Unsicherheit sichtbar, sie beseitigen sie nicht. Wer auf völlige Genauigkeit wartet, die gar nicht zu bekommen ist, verwechselt Abwägen mit Entscheiden.","coreRule":"⚡ Unsicherheit ist ein Grund, sie zu beziffern – nicht, auf die Entscheidung zu verzichten.","beleg":"Werkstück A.7 (Der Kipppunkt)","status":"entwurf","kurz":"Das Team rechnet seit Wochen, wartet aber auf eine Genauigkeit, die es ohne neue Informationen gar nicht geben wird. Wahrscheinlichkeiten machen Unsicherheit sichtbar, beseitigen sie nicht. Wer darauf wartet, verwechselt Abwägen mit Entscheiden.","prueffrage":"Was würde sich an den Zahlen ändern, wenn das Team noch eine weitere Woche rechnet?","rueckmeldung":[{"option":1,"text":"Ein Zahlenwert wirkt schnell wie Wissen, und Rechnen schafft in der Tat keine Gewissheit. Wahrscheinlichkeiten nennen die Unsicherheit aber nur offen, sie vergrößern sie nicht. Das Problem liegt im Warten auf Genauigkeit, nicht im Rechnen."},{"option":2,"text":"Wahrscheinlichkeit ist tatsächlich nicht dasselbe wie Gewissheit. Eine Schwelle von 50 %, ab der etwas wie eine Tatsache gilt, gibt es aber nicht, und das Team behandelt gar keine Folge als Tatsache. Es schiebt die Entscheidung auf."},{"option":3,"text":"Sorgfältiges Rechnen ist wertvoll, und das Team hat drei Wochen darauf verwendet. Ohne neue Informationen wird die Zahl aber nicht sicherer, und irgendwann bringt weiteres Rechnen nur noch Zeitverlust statt einer besseren Entscheidung."}],"familie":"gewissheit-kalibrieren","fertigkeit":"F5","quellen":[{"typ":"url","kurz":"Stanford Encyclopedia of Philosophy: Bounded Rationality (Erstveröffentlichung 2018, überarbeitet 2024)","oeffentlich":true,"url":"https://plato.stanford.edu/entries/bounded-rationality/","abruf":"2026-10-12"},{"typ":"url","kurz":"Joyce, J.: Bayes' Theorem. Stanford Encyclopedia of Philosophy","oeffentlich":true,"url":"https://plato.stanford.edu/entries/bayes-theorem/","abruf":"2026-10-12"}],"thema":"Zusammenleben"},{"id":"qx-a1-032","clusterId":"A","werkstueckRef":"A.7","stufe":4,"question":"Welche Reaktion auf das Video ist am besten begründet?","scenario":"Nach einer Wahl kursiert ein Video, das einen Zählfehler in einem einzelnen Wahllokal zeigt. Jemand ruft: „Die Wahl wurde zu 100 % gestohlen!“ Eine Zuhörerin hält dagegen und will den Hinweis nach Wahrscheinlichkeiten einordnen.","options":["Sie hält die offizielle Version für widerlegt, denn eine Anomalie, die diese Version nicht erklärt, hebt die Wahrscheinlichkeit des Gegenteils auf nahezu 100 %.","Sie fragt, wie wahrscheinlich Wahlbetrug vorher war und wie stark der Hinweis ist, denn ein einzelner Zählfehler hebt die Wahrscheinlichkeit nur minimal an.","Sie verwirft das Video als wertlos, denn eine Anomalie gegen ein gut belegtes System verändert die Wahrscheinlichkeit nicht.","Sie legt sich auf 50 : 50 fest, denn nun sind beide Erklärungen möglich, und solange keine die andere ausschließt, sind sie gleich wahrscheinlich."],"correctIndex":1,"explanation":"Wer „zu 100 % gestohlen“ ruft, denkt in Gewissheiten. Besser ist die Frage, wie wahrscheinlich Wahlbetrug in diesem System von vornherein war und wie stark der neue Hinweis ist. Ein einzelner Zählfehler ist ein schwacher Hinweis, weil sich auch bei korrekten Wahlen gelegentlich jemand verzählt: Er passt zu beiden Erklärungen fast gleich gut, verschiebt die Wahrscheinlichkeit deshalb allenfalls minimal, und sie bleibt sehr gering. Von vornherein wertlos ist er trotzdem nicht: Man sollte ihn einordnen, etwa prüfen, ob sich solche Fehler häufen oder alle in dieselbe Richtung weisen, statt ihn ungeprüft zu verwerfen. Dass zwei Erklärungen denkbar sind, macht sie noch nicht gleich wahrscheinlich.","coreRule":"⚡ Eine kleine Anomalie ist ein kleines Update, kein Urteil – gewichte Hinweise nach Stärke und Ausgangswahrscheinlichkeit.","beleg":"Werkstück A.7 (Anwendung & Relevanz: Bei Verschwörungsmythen; Red Flags)","status":"entwurf","kurz":"Ein einzelner Zählfehler ist ein schwacher Hinweis, denn solche Fehler kommen auch bei korrekten Wahlen vor; war Betrug vorher unwahrscheinlich, bleibt er es. Der Fehler liegt im Denken in Gewissheiten statt in Wahrscheinlichkeiten.","prueffrage":"Wie viele Wahllokale gab es insgesamt, und in wie vielen davon wurden Zählfehler gefunden?","rueckmeldung":[{"option":0,"text":"Auch ein Zählfehler ist Information, die man nicht wegwischen darf. Er passt aber ebenso zur offiziellen Version, denn verzählt wird auch bei korrekten Wahlen; deshalb hebt er die Wahrscheinlichkeit von Betrug nur minimal an."},{"option":2,"text":"Ein einzelner Fehler wiegt tatsächlich wenig, und Vertrauen in ein gut belegtes System ist begründet. Dass ein Hinweis grundsätzlich nichts verändere, geht aber zu weit: Man sollte prüfen, etwa ob sich Fehler häufen, statt ihn vorab zu verwerfen."},{"option":3,"text":"Beide Erklärungen sind denkbar, aber denkbar heißt nicht gleich wahrscheinlich. 50 : 50 übergeht, wie unwahrscheinlich Betrug von vornherein war und wie schwach ein einzelner Zählfehler als Hinweis ist."}],"familie":"gewissheit-kalibrieren","fertigkeit":"F5","quellen":[{"typ":"url","kurz":"Joyce, J.: Bayes' Theorem. Stanford Encyclopedia of Philosophy","oeffentlich":true,"url":"https://plato.stanford.edu/entries/bayes-theorem/","abruf":"2026-10-12"}],"thema":"Netz und Medien"},{"id":"qx-a1-033","clusterId":"A","werkstueckRef":"A.8","stufe":1,"question":"Wer hat recht, und womit lässt sich das am besten begründen?","scenario":"Ein Kollege sagt: „Ich esse jeden Mittag einen Burger, weil ich Hunger habe. Satt zu sein ist die Folge erster Ordnung. Dass ich nachmittags müde bin und langsam zunehme, ist die zweite. Dass mein Herzrisiko steigt und meine Gesundheitskosten in 20 Jahren höher ausfallen, ist die dritte.“ Seine Kollegin widerspricht: „Das Herzrisiko wiegt doch am schwersten, also müsste es die erste Ordnung sein.“","options":["Die Kollegin: Je schwerer eine Folge wiegt, desto früher gehört sie in die Reihenfolge, also steht das Herzrisiko an erster Stelle.","Der Kollege: Die Ordnung zählt die Schritte zwischen Handlung und Folge, nicht das Gewicht der Folge.","Die Kollegin: Folgen, die man erst nach Jahren bemerkt, sind bedeutsamer und bilden deshalb die erste Ordnung der Kette.","Der Kollege: Alle genannten Folgen gehen letztlich auf den Burger zurück, also sind sie alle gleichermaßen von erster Ordnung."],"correctIndex":1,"explanation":"Die Ordnung einer Folge sagt, an welcher Stelle der Kette sie steht, nicht, wie schwer sie wiegt. Wer bei jeder Folge „Und was dann?“ fragt und die Antworten der Reihe nach ordnet, erhält genau diese Kette. Im Beispiel führt der Burger direkt zum Sattsein, das ist die erste Ordnung. Müdigkeit und Gewichtszunahme kommen als nächster Schritt hinzu, Herzrisiko und Gesundheitskosten stehen noch eine Stufe später. Dass alle Folgen irgendwie vom Burger herrühren, ändert an dieser Reihenfolge nichts. Dass eine schwere Folge auch von dritter Ordnung sein kann, ist eine Schlussfolgerung aus dieser Zählweise, denn das Gewicht einer Folge bestimmt ihre Stelle in der Kette nicht.","coreRule":"⚡ Die Ordnung zählt Schritte in der Kette der Folgen, nicht, wie schwer eine Folge wiegt.","beleg":"Werkstück A.8 (Kontext & Tiefe)","status":"entwurf","kurz":"Die Ordnung einer Folge zählt die Schritte von der Handlung bis zu ihr, nicht ihr Gewicht. Der naheliegende Fehler ist, Wichtiges nach vorn zu schieben, obwohl das Herzrisiko erst am Ende der Kette steht.","prueffrage":"Welche der genannten Folgen bliebe noch, wenn er vom täglichen Burger weder müde würde noch zunähme?","rueckmeldung":[{"option":0,"text":"Dass das Herzrisiko schwer wiegt, stimmt. Wie schwer eine Folge ist, sagt aber nichts darüber, an welcher Stelle der Kette sie steht. Das Herzrisiko braucht mehrere Zwischenschritte und bleibt daher dritte Ordnung."},{"option":2,"text":"Spät bemerkte Folgen können sehr bedeutsam sein. Ihre Stelle in der Kette hängt aber weder davon ab, wie bedeutsam sie sind, noch davon, wann man sie bemerkt, sondern davon, wie viele Schritte zwischen Burger und Folge liegen."},{"option":3,"text":"Alle Folgen gehen tatsächlich auf den Burger zurück. Dieser gemeinsame Ursprung sagt aber nichts über die Schritte dazwischen: Das Sattsein folgt direkt, das Herzrisiko erst über weitere Zwischenschritte."}],"familie":"systemisch-denken","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"Parrish, S. (Farnam Street, 2016): Second-Order Thinking: What Smart People Use to Outperform","oeffentlich":true,"url":"https://fs.blog/second-order-thinking/","abruf":"2026-10-12"}],"thema":"Gesundheit"},{"id":"qx-a1-034","clusterId":"A","werkstueckRef":"A.8","stufe":2,"question":"Welche Folgenkette zeigt, was du mit der Frage „Und was dann?“ bei dieser Gewohnheit entdeckst?","scenario":"Eine Freundin visualisiert täglich eine halbe Stunde lang ihren künftigen Reichtum. Dafür lässt sie ihre Weiterbildung ausfallen. Sie ist überzeugt, dass das „Gesetz der Anziehung“ das Geld schon herbeiführen wird.","options":["Das Ausbleiben des Erfolgs gilt als Beleg gegen die Methode, sie gibt sie auf; die verlorene Zeit war nur ein harmloser Umweg ohne weitere Folgen.","Wer tagtäglich nur Gedanken übt, riskiert nichts: Eine reine Denkübung kostet weder Zeit noch Chancen und kann deshalb keine Nebenwirkungen haben.","Folgen höherer Ordnung gibt es nur bei teuren Entscheidungen, nicht bei Gewohnheiten, die man jederzeit beenden und ohne Verlust wieder aufnehmen kann.","Die Zeit für Qualifizierung fehlt; bleibt der Erfolg aus, sucht sie die Schuld bei sich („zu wenig positiv gedacht“) und steigert sich noch tiefer in die Methode hinein."],"correctIndex":3,"explanation":"Die Frage „Und was dann?“ legt eine Kette offen. Erste Folge: Die Zeit fließt ins Visualisieren und fehlt für Qualifizierung, Arbeit und die Lösung realer Probleme. Zweite Folge: Wirkt die Methode nicht, bleibt die Methode selbst unangetastet, denn sie lässt sich so deuten, dass das Scheitern am eigenen „nicht positiven Denken“ liegt. Das erzeugt Schuldgefühle und kann zu noch intensiverem magischem Denken führen, einem Teufelskreis. Die anderen Antworten halten den Blick bei der ersten, bequemen Ebene fest: Sie unterstellen, dass eine Gewohnheit ohne Kosten sei, nur weil sie unsichtbar bleibt. Dabei kostet jede Stunde, die man in eine Sache steckt, auch die Alternative, die man dafür nicht tut.","coreRule":"⚡ Frag nach jeder Lösung „Und was dann?“ – auch nach den Folgen der Folgen.","beleg":"Werkstück A.8 (Anwendung & Relevanz: Bei Aberglaube & magischem Denken)","status":"entwurf","kurz":"Die halbe Stunde täglich fehlt für Weiterbildung, und bleibt der Erfolg aus, lässt sich das als zu wenig positives Denken deuten. So wird die Methode nie widerlegt, es entsteht Schuld, und das magische Denken kann sich noch verstärken.","prueffrage":"Wie oft ist ihre Weiterbildung schon ausgefallen, und was hat sich an ihrer Lage seitdem verändert?","rueckmeldung":[{"option":0,"text":"Ein Misserfolg müsste eigentlich gegen eine Methode sprechen. Hier lässt er sich aber umdeuten: Es lag dann am eigenen Denken, nicht an der Methode. Zudem war die Zeit nicht folgenlos, denn die Weiterbildung blieb liegen."},{"option":1,"text":"Es werden zwar nur Gedanken geübt, doch dafür geht täglich eine halbe Stunde drauf, und die Weiterbildung fällt aus. Wer Zeit verwendet, hat immer Kosten, auch wenn sie unsichtbar bleiben."},{"option":2,"text":"Bei teuren Entscheidungen fällt die Kette der Folgen sofort auf, bei Gewohnheiten weniger. Sie ist aber auch hier da: Die Zeit ist schon weg, die Weiterbildung ausgefallen, und Selbstvorwürfe können dazukommen."}],"familie":"systemisch-denken","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"Parrish, S. (Farnam Street, 2016): Second-Order Thinking: What Smart People Use to Outperform","oeffentlich":true,"url":"https://fs.blog/second-order-thinking/","abruf":"2026-10-12"}],"thema":"Psychologie"},{"id":"qx-a1-035","clusterId":"A","werkstueckRef":"A.8","stufe":3,"question":"Wie solltest du in dieser Lage vorgehen?","scenario":"Ein Team diskutiert seit Wochen alle denkbaren Folgen einer kleinen Software-Umstellung bis in die vierte und fünfte Ordnung und kommt zu keinem Beschluss.","options":["Die wahrscheinlichsten und schädlichsten Folgen der nächsten Stufe einbeziehen und dann handeln.","Alle Folgen bis in höchste Ordnungen weiterdenken und erst danach handeln, um jede Überraschung auszuschließen.","Einfache, unmittelbare Lösungen grundsätzlich verwerfen, weil sie kurzsichtig sind und später überholt werden.","Die Folgen ganz ignorieren und sofort handeln, weil sich spätere Folgen ohnehin nicht vorhersehen lassen."],"correctIndex":0,"explanation":"Wer sich in einem unendlichen Netz möglicher Konsequenzen verliert, fällt in die „Analyse-Paralyse“ und kann nicht mehr handeln. Alle Folgen vorherzusehen ist unmöglich. Das Ziel ist nicht Perfektion, sondern Verbesserung: die wahrscheinlichsten und schädlichsten Folgen der nächsten Stufe identifizieren, in die Entscheidung einbeziehen und dann handeln. Manchmal ist sogar eine Lösung erster Ordnung die beste verfügbare Option.","coreRule":"Ziel ist nicht Perfektion, sondern Verbesserung: die wahrscheinlichsten und schädlichsten Folgen erkennen und einbeziehen.","beleg":"Werkstück A.8 (Der Kipppunkt)","status":"entwurf","kurz":"Alle Folgen vorherzusehen ist unmöglich, und wer es versucht, landet in der Analyse-Paralyse. Besser ist, die wahrscheinlichsten und schädlichsten Folgen der nächsten Stufe zu bedenken und dann zu handeln: Verbesserung statt Perfektion.","prueffrage":"Wie viel Neues hat die Diskussion der vierten und fünften Ordnung in den letzten Wochen zur Entscheidung beigetragen?","rueckmeldung":[{"option":1,"text":"Gründlichkeit wirkt hier verantwortungsvoll, und Folgen zu bedenken ist richtig. Aber Überraschungen lassen sich nie ganz ausschließen, weil sich nicht alle Folgen vorhersehen lassen. Das Warten auf diese Gewissheit erzeugt genau die Lähmung, die das Team schon hat."},{"option":2,"text":"Einfache Lösungen als kurzsichtig abzutun, klingt nach Weitblick. Doch sie sind nicht grundsätzlich schlechter: Manchmal ist eine Lösung erster Ordnung die beste verfügbare Option, und ob sie später überholt wird, lässt sich vorab kaum sagen."},{"option":3,"text":"Dass sich späte Folgen nicht sicher vorhersehen lassen, stimmt. Daraus folgt aber nicht, dass sich gar nichts abschätzen lässt: Die wahrscheinlichsten und schädlichsten Folgen der nächsten Stufe kann man durchaus erkennen, und sie gehören in die Entscheidung."}],"familie":"systemisch-denken","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"Stanford Encyclopedia of Philosophy: Bounded Rationality","oeffentlich":true,"url":"https://plato.stanford.edu/entries/bounded-rationality/","abruf":"2026-10-12"},{"typ":"url","kurz":"Parrish, S. (Farnam Street, 2016): Second-Order Thinking","oeffentlich":true,"url":"https://fs.blog/second-order-thinking/","abruf":"2026-10-12"}],"thema":"Technik und KI"},{"id":"qx-a1-036","clusterId":"A","werkstueckRef":"A.8","stufe":4,"question":"Ein Kollege sagt in der Diskussion über Bonusprogramme: „Das beweist doch, dass Kopfgelder nach hinten losgehen: In Delhi wurde auf Kobras ein Kopfgeld ausgesetzt, die Leute haben die Schlangen gezüchtet, und am Ende gab es mehr Kobras als vorher.“ Du recherchierst kurz: Die Geschichte wird seit der Jahrtausendwende als Lehrbeispiel für Fehlanreize erzählt, doch für Kobra-Zuchtbetriebe im britischen Indien findet sich kein zeitgenössischer Beleg. Wie gehst du mit dem Argument um?","options":["Du lässt das Argument gelten: Eine so oft erzählte Geschichte stützt sich vermutlich auf Behördenakten, auch wenn du diese nicht gesehen hast.","Du verwirfst die Aussage ganz: Ist das Beispiel nicht belegt, kann auch die Aussage dahinter nicht stimmen und es gibt daraus nichts zu lernen.","Du trennst beides: Das Beispiel taugt nicht als Beleg, die Aussage prüfst du an besser dokumentierten Fällen.","Du übernimmst die Kernaussage mit Vorbehalt: Die Zucht gilt als gesichert, nur das Freilassen der Kobras am Ende ist vermutlich später ausgeschmückt."],"correctIndex":2,"explanation":"Eine Geschichte wird nicht dadurch wahr, dass sie oft erzählt wird. Wo die Quelle fehlt, trägt das Beispiel als Beweis nicht. Dass es sich nicht belegen lässt, widerlegt aber auch nicht die allgemeine Aussage: Dass Anreize das Gegenteil des Beabsichtigten bewirken können, ist an anderen, gut dokumentierten Fällen zeigbar. Also trennst du beides und prüfst den Mechanismus mit solideren Belegen. Im konkreten Fall führt die Spur zu einem Zeitungsbericht von 1873, der die Zucht nur als Gerücht wiedergab, und zu Fachleuten, die sie schon damals für unwahrscheinlich hielten. Ein Kopfgeldprogramm in Madras wurde 1873 tatsächlich eingeschränkt, aber wegen der Kosten, nicht wegen aufgedeckten Betrugs.","coreRule":"⚡ Eine gute Lehrgeschichte ist kein Beleg – trenne den Mechanismus von der Anekdote.","beleg":"Werkstück A.8 (Das Kobra-Problem); Fn. ga-kobra (Siebert 2001; Friends of Snakes Society 2025); Anmerkung anm-ga-kobra","status":"entwurf","scenario":"","kurz":"Wo die Quelle fehlt, trägt das Beispiel nicht als Beweis. Das widerlegt aber nicht die Aussage dahinter, denn Fehlanreize lassen sich an gut dokumentierten Fällen zeigen. Du trennst also Beleg und Behauptung und prüfst den Mechanismus woanders.","prueffrage":"Woher stammt die Geschichte ursprünglich, und was lässt sich aus der Zeit selbst dazu finden?","rueckmeldung":[{"option":0,"text":"Eine oft erzählte Geschichte wirkt, als müsse irgendwo ein Beleg dahinterstehen. Häufiges Erzählen ersetzt ihn aber nicht, und hier führt die Spur nur zu einem Gerücht aus dem Jahr 1873."},{"option":1,"text":"Daran stimmt: Das Beispiel selbst beweist nichts. Daraus folgt aber nicht, dass die Aussage falsch ist, denn ein fehlender Beleg widerlegt nichts. Dass Anreize das Gegenteil bewirken können, zeigen andere, gut dokumentierte Fälle."},{"option":3,"text":"Ein Kompromiss, der nur die Ausschmückung abzieht, klingt maßvoll. Gerade die Zucht ist aber nicht gesichert: Der Bericht von 1873 gab sie nur als Gerücht wieder, und schon damals hielten Fachleute sie für unwahrscheinlich."}],"familie":"lehrgeschichte-pruefen","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Friends of Snakes Society (2025, aktualisiert 16.09.2026): The Cobra Effect: Colonial Misinformation Masquerading as Economic Theory","oeffentlich":true,"url":"https://friendsofsnakes.org.in/cobra-effect/","abruf":"2026-10-12"},{"typ":"url","kurz":"Gilbert, M. J.: Interview mit Michael G. Vann zur Rattenjagd in Hanoi 1902. World History Connected 15.2","oeffentlich":true,"url":"https://worldhistoryconnected.press.uillinois.edu/15.2/vann_interview.html","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Siebert, H. (2001): Der Kobra-Effekt. Wie man Irrwege der Wirtschaftspolitik vermeidet","oeffentlich":false}],"thema":"Geschichte und Wissenschaft"},{"id":"qx-a1-037","clusterId":"A","werkstueckRef":"A.8.1","stufe":1,"question":"Welche Schlussfolgerung ist hier am besten begründet?","options":["Die Annahme ist unbegründet: Mehr Weitererzählen führt zu noch mehr Weitererzählen, ohne bremsende Gegenkraft schaukelt sich der Prozess weiter auf.","Die Annahme ist begründet: Jeder Prozess, der stark wächst, erreicht irgendwann von selbst einen Zielzustand und pendelt sich dort ein, ähnlich wie eine Raumtemperatur.","Die Annahme ist begründet: Was schnell wächst, ist meist harmlos, denn schädliche Entwicklungen verlaufen immer langsam und lassen sich früh erkennen.","Die Annahme ist unbegründet, weil Gerüchte und andere soziale Vorgänge nie zurückwirken: Rückkopplung gibt es nur in technischen Systemen wie einer Heizung."],"correctIndex":0,"explanation":"Entscheidend ist die Richtung der Rückkopplung. Beim Gerücht führt mehr Verbreitung zu mehr Weitererzählen und damit zu noch mehr Verbreitung: eine verstärkende Schleife, die sich aufschaukelt, bis eine ausgleichende Kraft sie bremst, etwa weil kaum noch jemand übrig ist, der das Gerücht nicht kennt, oder weil das Interesse nachlässt. Ein Zielzustand, zu dem ein System von selbst zurückkehrt, entsteht nur bei ausgleichenden Schleifen: Beim Thermostat führt eine zu hohe Temperatur zu weniger Heizen und damit wieder zu sinkender Temperatur. Dass sich das Gerücht von selbst beruhigt und zum Normalzustand zurückfindet, folgt aus der beschriebenen Dynamik also nicht. Rückkopplung gibt es überall, wo das Ergebnis eines Vorgangs auf ihn zurückwirkt, auch in Gesprächen, Märkten und Körpern.","coreRule":"⚡ Frag bei jedem Prozess: Bremst das Ergebnis den Vorgang (ausgleichend, Richtung Zielzustand) oder treibt es ihn weiter an (verstärkend, Richtung Eskalation)?","beleg":"Werkstück A.8.1 (Kernidee: Zwei Haupttypen)","status":"entwurf","scenario":"In einer Diskussion über ein Gerücht sagt jemand: „Das Gerücht hat sich in zwei Tagen verzehnfacht. Je mehr Leute es hören, desto mehr erzählen es weiter. Das System wird sich bestimmt von selbst wieder beruhigen und zu seinem Normalzustand zurückfinden.“","kurz":"Beim Gerücht bringt mehr Verbreitung mehr Weitererzählen und damit noch mehr Verbreitung. Eine solche verstärkende Schleife schaukelt sich auf, bis eine Gegenkraft bremst. Dass sich alles von selbst beruhigt, gilt nur bei ausgleichenden Schleifen.","prueffrage":"Wie viele Leute haben das Gerücht am ersten Tag weitererzählt, und wie viele am zweiten?","rueckmeldung":[{"option":1,"text":"Das Raumtemperatur-Bild passt, aber nur für Prozesse, in denen ein Anstieg die eigene Ursache abschwächt, etwa beim Thermostat. Beim Gerücht verstärkt der Anstieg sich selbst; starkes Wachstum allein führt also nicht zu einem Zielzustand."},{"option":2,"text":"Dass sich Schädliches langsam und früh erkennbar anbahnt, wäre beruhigend, stimmt aber nicht. Gerade verstärkende Schleifen wachsen schnell, und über den Schaden sagt das Tempo nichts: Auch rasche Entwicklungen können gefährlich sein."},{"option":3,"text":"Die Schlussfolgerung, die Annahme sei unbegründet, stimmt, ihre Begründung nicht. Rückkopplung gibt es nicht nur in der Technik, sondern überall, wo ein Ergebnis auf den Vorgang zurückwirkt, auch in Gesprächen, Märkten und Körpern."}],"familie":"systemisch-denken","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"Meadows, D.: Leverage Points: Places to Intervene in a System (Donella Meadows Project)","oeffentlich":true,"url":"https://donellameadows.org/archives/leverage-points-places-to-intervene-in-a-system/","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Meadows, D. H. (2008): Thinking in Systems: A Primer","oeffentlich":false}],"thema":"Netz und Medien"},{"id":"qx-a1-038","clusterId":"A","werkstueckRef":"A.8.1","stufe":2,"question":"Was ist hier der klügste nächste Schritt?","scenario":"Du verlierst mit Sport und weniger Kalorien zunächst Gewicht, doch nach einigen Monaten stagniert es, obwohl du dich scheinbar an alles hältst wie am Anfang. Du überlegst, wie du jetzt vorgehst.","options":["Du machst unverändert weiter, denn ein Plateau ist ein Messfehler und verschwindet von selbst, wenn man dem Plan lange genug treu bleibt.","Du verdoppelst die Anstrengung nach demselben Muster, denn mehr vom Gleichen führt am Ende immer zum Ziel.","Du brichst ab, denn ein Plateau beweist, dass der Plan nie gewirkt hat und der anfängliche Erfolg nur Zufall war.","Du fragst, wie sich dein Körper und dein Essverhalten durch deine Handlung verändert haben, und passt dein Vorgehen daran an."],"correctIndex":3,"explanation":"Eine Handlung verändert das System, auf das sie wirkt: Ein leichterer Körper verbraucht weniger Energie, der Stoffwechsel passt sich zum Teil an, und oft lockert sich unbemerkt auch das eigene Essverhalten. Dieselbe Handlung führt dann nicht mehr zum selben Ergebnis. Statt stur weiterzumachen, abzubrechen oder blind mehr vom Gleichen zu tun, prüfst du, was sich verändert hat, und passt dein Vorgehen an. Ein Vorbehalt gehört dazu: Nach einer Modellrechnung von Hall und Kollegen (2011) liegt die Ursache des typischen Plateaus nach 6 bis 8 Monaten eher in nachlassender Einhaltung der Diät als in einem plötzlich gebremsten Stoffwechsel. Gerade deshalb lohnt es sich, ehrlich nachzumessen, statt nur zu raten.","coreRule":"⚡ Führt die Handlung nicht mehr zum Ziel, hat sich das System verändert: Prüfe die Rückmeldung und passe an, statt mehr vom Gleichen zu tun.","beleg":"Werkstück A.8.1 (Geschichte des Thermostats und des Diät-Plateaus); Fn. ga-diaet-plateau (Hall u. a. 2011, The Lancet 378(9793), S. 826–837)","status":"entwurf","kurz":"Eine Handlung verändert das, worauf sie wirkt: Ein leichterer Körper verbraucht weniger, und oft lockert sich unbemerkt das Essverhalten. Deshalb prüfst du, was sich verändert hat, und passt dein Vorgehen an, statt nur weiterzumachen oder abzubrechen.","prueffrage":"Zeigen Waage und Maßband seit Wochen dieselben Werte, wenn du immer zur gleichen Tageszeit misst?","rueckmeldung":[{"option":0,"text":"Durchhalten wirkt diszipliniert, und Schwankungen auf der Waage gibt es tatsächlich. Ein anhaltendes Plateau ist aber meist kein Messfehler, sondern Folge veränderter Bedingungen; von selbst verschwindet es deshalb nicht zwingend."},{"option":1,"text":"Mehr Einsatz fühlt sich nach dem naheliegenden Hebel an. „Immer“ stimmt aber nicht: Wenn sich Körper und Essverhalten verändert haben, bringt mehr vom Gleichen nicht automatisch das alte Ergebnis. Erst eine Prüfung zeigt, was sich verschoben hat."},{"option":2,"text":"Das Stocken enttäuscht, und der Plan wirkt jetzt wirklich nicht mehr wie am Anfang. Daraus folgt aber nicht, dass er nie gewirkt hat: Der frühe Gewichtsverlust war real. Sinnvoller ist, die veränderten Bedingungen zu klären und anzupassen."}],"familie":"systemisch-denken","fertigkeit":"F4","quellen":[{"typ":"doi","kurz":"Hall, K. D. u. a. (2011): Quantification of the effect of energy imbalance on bodyweight. The Lancet 378(9793), 826–837","oeffentlich":true,"doi":"10.1016/S0140-6736(11)60812-X","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC3880593","abruf":"2026-10-12"}],"thema":"Gesundheit"},{"id":"qx-a1-039","clusterId":"A","werkstueckRef":"A.8.1","stufe":3,"question":"Eine Gemeinde senkt die Abwasserbelastung eines Sees. Fachleute erwarten, dass die Wirkung der Maßnahmen erst nach rund 20 Jahren sichtbar wird. Nach fünf Jahren ohne erkennbare Besserung fordern einige, die Maßnahmen als wirkungslos aufzugeben, andere wollen sie verdoppeln. Welche Überlegung zur Steuerung dieser Schleife ist am stichhaltigsten?","options":["Bei stark verzögerter Rückmeldung sagt das Ausbleiben von Wirkung wenig aus: Wer früh abbricht oder verdoppelt, steuert womöglich falsch, deshalb braucht es früher messbare Zwischenindikatoren.","Bei stark verzögerter Rückmeldung gleicht sich das System von selbst aus: Wer nach fünf Jahren ohne Besserung nichts unternimmt, steuert richtig, deshalb braucht es keine weiteren Prüfungen.","Bei schneller Rückmeldung schaukelt sich eine Schleife besonders leicht auf: Wer rasches Feedback bekommt, übersteuert zwangsläufig, deshalb braucht es möglichst späte Messungen.","Bei ausbleibender Besserung liegt der Fehler im Zielwert: Wer ein ehrgeiziges Ziel setzt, macht jedes Feedback wertlos, deshalb braucht es zuerst ein bescheideneres Ziel."],"correctIndex":0,"explanation":"Eine ausgleichende Schleife steuert gut, solange ihre Rückmeldung rechtzeitig kommt. Ist sie stark verzögert, zeigt sich die Wirkung einer Handlung erst, wenn längst nachgesteuert wurde: Wer nach fünf Jahren ohne sichtbaren Effekt abbricht, gibt womöglich eine wirksame Maßnahme auf; wer verdoppelt, schießt womöglich über das Ziel hinaus. Früher messbare Zwischenindikatoren verkürzen diese Verzögerung, etwa die Frage, ob die Zuflüsse tatsächlich weniger belastet sind. Schnelles Feedback macht Schleifen dagegen gerade gut steuerbar, und Abwarten ohne jede Prüfung hilft nicht, weil man dann blind steuert. Ein ehrgeiziges Ziel macht eine Rückmeldung nicht wertlos; entscheidend ist, wann die Information eintrifft.","coreRule":"⚡ Je länger die Rückmeldung braucht, desto weniger darfst du aus fehlender Wirkung schließen. Suche früher messbare Zwischenindikatoren, bevor du abbrichst oder verdoppelst.","beleg":"Werkstück A.8.1 (Der Kipppunkt: Der Verzögerungs-Kipppunkt)","status":"entwurf","scenario":"","quote":"","quoteLabel":"","kurz":"Wenn die Wirkung erst nach rund 20 Jahren sichtbar wird, sagen fünf Jahre ohne Besserung wenig. Abbrechen oder Verdoppeln steuert womöglich falsch, weil man ohne rechtzeitige Rückmeldung blind nachsteuert. Hilfreich sind früher messbare Zwischenindikatoren.","prueffrage":"Was genau wurde in den fünf Jahren im See gemessen, und wie oft?","rueckmeldung":[{"option":1,"text":"Dass fehlende Besserung nach fünf Jahren noch nichts beweist, stimmt. Von selbst gleicht sich das System deshalb aber nicht aus, und ohne weitere Prüfungen steuert man ebenso blind wie beim Abbrechen oder Verdoppeln."},{"option":2,"text":"Hier liegt gerade keine schnelle Rückmeldung vor, sondern eine stark verzögerte. Rasches Feedback macht eine Schleife gut steuerbar, und späte Messungen würden das Problem der Verzögerung eher verschärfen."},{"option":3,"text":"Ein ehrgeiziges Ziel kann Enttäuschung erzeugen, doch die Besonderheit hier ist die Verzögerung von rund 20 Jahren. Ein Ziel macht Rückmeldung nicht wertlos; entscheidend ist, wann die Information eintrifft."}],"familie":"systemisch-denken","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"Meadows, D.: Leverage Points: Places to Intervene in a System (Donella Meadows Project)","oeffentlich":true,"url":"https://donellameadows.org/archives/leverage-points-places-to-intervene-in-a-system/","abruf":"2026-10-12"},{"typ":"doi","kurz":"Jeppesen, E. u. a. (2005): Lake responses to reduced nutrient loading – an analysis of contemporary long-term data from 35 case studies. Freshwater Biology 50, 1747–1771","oeffentlich":true,"doi":"10.1111/j.1365-2427.2005.01415.x","url":"https://kops.uni-konstanz.de/bitstreams/862b4528-106d-4161-9d82-4edf44290472/download","seite":"S. 1747–1748 (Summary, Punkt 2)","abruf":"2026-10-12"}],"thema":"Natur und Klima"},{"id":"qx-a1-040","clusterId":"A","werkstueckRef":"A.8.1","stufe":4,"question":"Welche Einschätzung wird der Lage am ehesten gerecht?","scenario":"Ein Bekannter klickt aus Neugier auf ein „skeptisches“ Video über Chemtrails. Danach werden ihm immer mehr und immer extremere Videos zum Thema vorgeschlagen, und er hält die Behauptung zunehmend für belegt: „Das gibt es ja überall, das kann kein Zufall sein.“ Eine Kollegin meint: „Die Plattform hat ihn radikalisiert. Er hat anfangs nur ein einziges Video angeklickt, alles Weitere hat der Algorithmus ihm vorgesetzt.“","options":["Die Dynamik ist eine verstärkende Schleife aus Klick, Empfehlung und wachsender Überzeugung. Die Behauptung, der Algorithmus allein sei schuld, ist aber zu stark, denn er verstärkt eher vorhandene Neigungen, als dass er sie erzeugt.","Die Dynamik ist eine ausgleichende Schleife, weil der Algorithmus auf jeden Klick reagiert und so den Ausgangszustand des Nutzers stabilisiert. Die Behauptung der Kollegin ist deshalb falsch, denn von einer Eskalation kann hier keine Rede sein.","Die Dynamik ist eine verstärkende Schleife aus Klick, Empfehlung und wachsender Überzeugung. Die Behauptung der Kollegin trifft deshalb zu, denn der Algorithmus erzeugt die Überzeugung, die der Nutzer vorher nicht gehabt hat.","Die Dynamik ist keine Schleife, weil der Nutzer aus den Videos kein Feedback zieht, das seine Überzeugung verändern würde. Die Behauptung der Kollegin ist deshalb hinfällig, denn zwischen Klick und Überzeugung besteht kein Zusammenhang."],"correctIndex":0,"explanation":"Hier greifen zwei Dinge ineinander: Der Klick signalisiert Interesse, die Plattform spielt mehr und extremeres Material aus, der Nutzer sieht „überall Beweise“ und klickt weiter. Das ist eine verstärkende Schleife, in der Output wieder zum Input wird. Daraus folgt aber nicht, dass der Algorithmus allein die Überzeugung formt. Die Rolle von Empfehlungssystemen ist umstritten: Sie wirken eher als Verstärker vorhandener Neigungen denn als Puppenspieler, und tiefer hinein führen oft Abonnements und Links, die andere schicken. Die Schleife braucht beide Seiten, die Technik und den Menschen, der darauf reagiert. Wer nur eine Seite verantwortlich macht, verkürzt die Ursachen. Auch der Gegensatz stimmt nicht: Eine ausgleichende Schleife würde den Ausgangszustand stabilisieren, statt zu eskalieren, hier wächst die Überzeugung aber immer weiter. Und von fehlendem Feedback kann keine Rede sein, denn der Nutzer deutet jede neue Empfehlung als weiteren Beleg.","coreRule":"⚡ Eine Schleife braucht beide Seiten: Auch ein Algorithmus verstärkt oft nur, was schon da ist. Wer „allein schuld“ sagt, hat die Rückkopplung nicht verstanden.","beleg":"Werkstück A.8.1 (Anwendung & Relevanz: Der algorithmische Kaninchenbau)","status":"entwurf","quote":"","quoteLabel":"","kurz":"Klick, Empfehlung und wachsende Überzeugung verstärken sich gegenseitig, doch das heißt nicht, dass der Algorithmus allein schuld ist. Er verstärkt eher vorhandene Neigungen, als sie zu erzeugen, und die Schleife braucht auch den Menschen, der darauf reagiert.","prueffrage":"Wie viele der vorgeschlagenen Videos hat er tatsächlich angeklickt, und wie viele hat er übersprungen?","rueckmeldung":[{"option":1,"text":"Dass der Algorithmus auf jeden Klick reagiert, stimmt. Doch das stabilisiert nichts, sondern treibt die Sache voran: Es kommen mehr und extremere Videos, und die Überzeugung wächst. Das ist eine Eskalation, also eine verstärkende Schleife."},{"option":2,"text":"Die verstärkende Schleife ist richtig erkannt, der Schluss daraus geht aber zu weit. Empfehlungssysteme wirken eher als Verstärker vorhandener Neigungen denn als Erzeuger, und oft führen auch Abonnements und Links von anderen tiefer hinein."},{"option":3,"text":"Eine Schleife gibt es durchaus: Jede Empfehlung deutet er als weiteren Beleg („überall“) und klickt weiter. Zwischen Klick und Überzeugung besteht also ein Zusammenhang. Zu einfach ist nur die Behauptung der Kollegin, nicht der Zusammenhang selbst."}],"familie":"systemisch-denken","fertigkeit":"F4","quellen":[{"typ":"doi","kurz":"Chen, A. Y.; Nyhan, B.; Reifler, J.; Robertson, R. E.; Wilson, C. (2023): Subscriptions and external links help drive resentful users to alternative and extremist YouTube channels. Science Advances 9(35), eadd8080","oeffentlich":true,"doi":"10.1126/sciadv.add8080","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC10468121/","abruf":"2026-10-12"},{"typ":"doi","kurz":"Hosseinmardi, H. u. a. (2021): Examining the consumption of radical content on YouTube. PNAS 118(32), e2101967118","oeffentlich":true,"doi":"10.1073/pnas.2101967118","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC8364190/","abruf":"2026-10-12"}],"thema":"Netz und Medien"},{"id":"qx-a1-041","clusterId":"A","werkstueckRef":"A.9","stufe":1,"question":"Was spricht dafür, dass die Leiterin hier klüger vorgeht als der Kollege?","scenario":"Ein Projektteam plant die Einführung einer neuen Software. Kurz vor dem Start sagt die Leiterin: „Stellen wir uns vor, in einem Jahr ist dieses Projekt die größte Katastrophe unserer Firmengeschichte. Was ist passiert?“ Ein Kollege widerspricht: „Das ist Schwarzmalerei. Wir sollten uns lieber darauf konzentrieren, wie wir erfolgreich sind.“","options":["Sie bereitet das Team darauf vor, dass das Scheitern wahrscheinlich ist, damit später niemand von einem schlechten Ergebnis überrascht wird.","Sie lässt das Team den Erfolg möglichst lebendig ausmalen, damit alle motiviert bleiben und Zweifel gar nicht erst aufkommen.","Sie lässt das Team die Wege des Scheiterns durchdenken, damit die größten und wahrscheinlichsten Fehler gezielt vermieden werden können.","Sie legt schon vor dem Start fest, wer bei einem Misserfolg verantwortlich ist, damit später niemand ausweichen kann und die Schuld klar ist."],"correctIndex":2,"explanation":"Die Leiterin kehrt die Frage um: Statt „Wie gelingt das Projekt?“ fragt sie „Was würde es garantiert ruinieren?“. Das ist oft leichter zu beantworten, denn über Gefahren und Fehlerquellen lässt sich meist konkreter nachdenken als über eine perfekte Erfolgsstrategie. Aus den gefundenen Ursachen entsteht eine Liste von Dingen, die man gezielt vermeidet. So schließt man die größten und dümmsten Fehler aus, und das verbessert das Ergebnis oft deutlich. Das ist keine Schwarzmalerei, denn es geht nicht darum, das Scheitern zu erwarten, sondern es zu verhindern. Reines Ausmalen des Erfolgs dagegen ignoriert die Inversion und macht anfällig für katastrophale Fehler.","coreRule":"⚡ Frag nicht nur, wie du gewinnst, sondern auch, wie du sicher scheiterst – und meide genau das.","beleg":"Werkstück A.9 (Die Rede des Piloten; Kernidee)","status":"entwurf","kurz":"Die Leiterin fragt, was das Projekt ruinieren würde, denn über Gefahren lässt sich oft konkreter nachdenken als über die perfekte Erfolgsstrategie. Aus den Ursachen entsteht eine Liste von Fehlern, die man gezielt vermeidet. Das ist kein Schwarzmalen, sondern Verhinderung.","prueffrage":"Wann stellt die Leiterin ihre Frage, und was ließe sich zu diesem Zeitpunkt noch ändern?","rueckmeldung":[{"option":0,"text":"Auf ein mögliches Scheitern gefasst zu sein, wirkt realistisch. Die Leiterin hält es aber nicht für wahrscheinlich, sie fragt, wie es entstehen könnte, um genau das zu verhindern."},{"option":1,"text":"Ein motiviertes Team ist viel wert, doch das Ausmalen des Erfolgs blendet gerade die Fehlerquellen aus, die das Projekt gefährden. Wer Zweifel gar nicht erst aufkommen lässt, kann sie auch nicht nutzen."},{"option":3,"text":"Klare Verantwortung kann in Projekten hilfreich sein, ist hier aber nicht der Punkt. Die Leiterin sucht vorab nach Ursachen möglichen Scheiterns, um sie zu vermeiden; einen Schuldigen zu bestimmen, deckt keine einzige Fehlerquelle auf."}],"familie":"vom-scheitern-her-denken","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"Klein, G. (2007): Performing a Project Premortem. Harvard Business Review (September 2007)","oeffentlich":true,"url":"https://hbr.org/2007/09/performing-a-project-premortem","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Mitchell, D. J.; Russo, J. E.; Pennington, N. (1989): Back to the future: Temporal perspective in the explanation of events. Journal of Behavioral Decision Making","oeffentlich":false},{"typ":"doi","kurz":"Van Vleck, E. B. (1916): Current Tendencies of Mathematical Research. Bulletin of the American Mathematical Society 23(1), 1–13","oeffentlich":true,"doi":"10.1090/S0002-9904-1916-02863-1","seite":"S. 3","abruf":"2026-10-04"}],"thema":"Zusammenleben"},{"id":"qx-a1-042","clusterId":"A","werkstueckRef":"A.9","stufe":2,"question":"Welches Vorgehen deckt die größten Risiken am zuverlässigsten auf?","scenario":"Dein Team plant den Start eines neuen Produkts. Alle sind begeistert, und im Plan steht nur, was alles gut laufen soll. Eine Kollegin fragt, wie ihr den Plan am besten auf Schwachstellen prüft.","options":["Ihr nehmt an, der Start sei ein Jahr später eine Katastrophe, sammelt, was dazu geführt haben müsste, und macht daraus eine verbindliche „Nicht-tun“-Liste.","Ihr formuliert das Erfolgsszenario noch detaillierter und visualisiert es gemeinsam, damit jeder weiß, wie der Weg zum Ziel aussieht.","Ihr lasst jeden Beteiligten schätzen, wie optimistisch er ist, und wertet die Zahl der Optimisten als Maß für die Erfolgsaussicht aus.","Ihr sammelt alle Bedenken und streicht den Plan, sobald auch nur ein Risiko nicht vollständig ausgeräumt werden kann."],"correctIndex":0,"explanation":"Ein Plan, der nur aus Best-Case-Annahmen besteht, übersieht Risiken, weil niemand nach den Wegen des Scheiterns gesucht hat. Der Perspektivwechsel, das Scheitern als Tatsache anzunehmen und rückwärts zu fragen, was dazu geführt haben müsste, macht diese Wege sichtbar. Das fällt leichter, als einen perfekten Erfolgsweg zu entwerfen, denn Gefahren und Fehlerquellen erkennen wir meist besser als komplexe Erfolgsstrategien. Aus den gefundenen Ursachen entsteht eine konkrete „Nicht-tun“-Liste. Das Erfolgsbild weiter auszumalen, bestätigt nur die Annahmen, die ohnehin schon alle teilen. Die Stimmung im Team zu zählen, misst Begeisterung, nicht Erfolgsaussicht, denn viele Optimisten machen ein Risiko nicht kleiner. Den Plan bei jedem ungelösten Restrisiko zu streichen, endet in Lähmung: Risiken lassen sich nie auf null senken, es geht darum, die größten und wahrscheinlichsten zu erkennen und zu vermeiden.","coreRule":"⚡ Mach vorab die Autopsie: Wie ist das Projekt gescheitert? Und plane gegen genau das.","beleg":"Werkstück A.9 (Kontext & Tiefe: „Worst-Case“-Inversion; Werkbank-Frage)","status":"entwurf","kurz":"Wer das Scheitern als Tatsache annimmt und rückwärts fragt, was dazu geführt haben müsste, findet Fehlerquellen, die im Best-Case-Plan unsichtbar blieben. Das Erfolgsbild weiter auszumalen, bestätigt dagegen nur, was ohnehin alle annehmen.","prueffrage":"Welche Annahmen im Plan hat bisher noch niemand ernsthaft in Frage gestellt, und wer hätte einen Grund, sie anzuzweifeln?","rueckmeldung":[{"option":1,"text":"Ein genaueres Erfolgsbild schafft Klarheit über den Weg und kann motivieren. Es bestätigt aber nur die Annahmen, die alle schon teilen, und sucht nirgends nach Wegen des Scheiterns. Neue Risiken tauchen so nicht auf."},{"option":2,"text":"Eine Umfrage unter den Beteiligten ist schnell gemacht und liefert eine greifbare Zahl. Sie misst aber die Begeisterung im Team, nicht die Erfolgsaussicht: Auch viele Optimisten machen kein einziges Risiko kleiner."},{"option":3,"text":"Bedenken zu sammeln ist ein guter Anfang. Doch Risiken lassen sich nie auf null senken, nach dieser Regel würde also jeder Plan gestrichen. Wichtiger ist, die größten und wahrscheinlichsten Risiken zu erkennen und gezielt zu vermeiden."}],"familie":"vom-scheitern-her-denken","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"Klein, G. (2007): Performing a Project Premortem. Harvard Business Review","oeffentlich":true,"url":"https://hbr.org/2007/09/performing-a-project-premortem","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Mitchell, D. J.; Russo, J. E.; Pennington, N. (1989): Back to the future: Temporal perspective in the explanation of events. Journal of Behavioral Decision Making","oeffentlich":false}],"thema":"Zusammenleben"},{"id":"qx-a1-043","clusterId":"A","werkstueckRef":"A.9","stufe":3,"question":"Was ist an diesem Vorgehen verfehlt?","scenario":"In jeder Besprechung zählt ein Kollege neue Risiken auf. Das Projekt wird nie gestartet, weil nie alle Risiken beseitigt sind.","options":["Es ist nicht verfehlt, denn wer sorgfältig prüft, muss den Start so lange verschieben, bis jedes einzelne Risiko ausgeräumt ist, auch das kleinste Risiko.","Es ist verfehlt, denn die Suche nach Risiken ist nur dann sinnvoll, wenn ein Team zu Optimismus neigt; in vorsichtigen Teams erzeugt sie bloß zusätzliche Angst.","Es ist verfehlt, denn nur Risiken mit einer Eintrittswahrscheinlichkeit von über 50 % verdienen Beachtung; alle kleineren Risiken dürfen einfach ignoriert werden.","Es ist verfehlt, denn null Risiko ist unerreichbar; man muss die gewichtigsten Risiken vermeiden und dann mit dem Rest handeln, statt zu warten."],"correctIndex":3,"explanation":"Risiken zu suchen und zu vermeiden ist nützlich, es senkt die Wahrscheinlichkeit des Scheiterns. Es kippt aber in Lähmung, sobald man verlangt, vor dem Handeln alle Risiken auszuräumen. Das ist unmöglich, denn alle Risiken auf null zu senken, gelingt nie. Klug ist, die größten, dümmsten und wahrscheinlichsten Fehlerquellen gezielt auszuschließen, mit dem Rest bewusst zu leben und zu handeln. Eine starre Schwelle wie „über 50 %“ ist ebenfalls nicht das Kriterium; entscheidend sind die größten, dümmsten und wahrscheinlichsten Risiken. Ob ein Team eher optimistisch oder vorsichtig ist, ändert daran nichts.","coreRule":"⚡ Risiken suchen heißt gewichten, nicht abschaffen: Die größten, dümmsten und wahrscheinlichsten vermeiden, dann mit klugem Mut handeln.","beleg":"Werkstück A.9 (Der Kipppunkt)","status":"entwurf","kurz":"Alle Risiken auf null zu senken gelingt nie, wer das vor dem Start verlangt, startet nie. Sinnvoll ist, die gewichtigsten Fehlerquellen gezielt auszuschließen und mit dem Rest bewusst zu handeln. Gründlichkeit kippt sonst in Lähmung.","prueffrage":"Wie viele der aufgezählten Risiken hätten das Projekt ernsthaft gefährdet, und wie viele waren eher Kleinigkeiten?","rueckmeldung":[{"option":0,"text":"Sorgfältig zu prüfen ist wertvoll, und Risikosuche senkt die Wahrscheinlichkeit des Scheiterns. Aber „jedes Risiko ausräumen“ lässt sich nie erfüllen, und genau deshalb wird das Projekt hier nie gestartet."},{"option":1,"text":"Dass Risikosuche ein vorsichtiges Team zusätzlich ängstigen kann, ist denkbar. Der Fehler liegt aber im Vorgehen selbst: Es verlangt, vor dem Handeln jedes Risiko auszuräumen, und das scheitert in jedem Team."},{"option":2,"text":"Kleine Risiken muss man nicht alle ausräumen. Eine feste Grenze wie „über 50 %“ taugt aber nicht: Ein unwahrscheinliches, aber folgenschweres Risiko darf man nicht ignorieren. Es kommt auf die gewichtigsten und wahrscheinlichsten Fehlerquellen an."}],"familie":"vom-scheitern-her-denken","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"Stanford Encyclopedia of Philosophy: Bounded Rationality","oeffentlich":true,"url":"https://plato.stanford.edu/entries/bounded-rationality/","abruf":"2026-10-12"},{"typ":"url","kurz":"Klein, G. (2007): Performing a Project Premortem. Harvard Business Review","oeffentlich":true,"url":"https://hbr.org/2007/09/performing-a-project-premortem","abruf":"2026-10-12"}],"thema":"Zusammenleben"},{"id":"qx-a1-044","clusterId":"A","werkstueckRef":"A.9","stufe":4,"question":"Was ist hier die klügste Prüffrage, bevor du dich entscheidest?","scenario":"Eine Gemeinschaft verspricht dir „totale Freiheit“ und „Erleuchtung“ und wirbt mit begeisterten Erfolgsberichten ihrer Mitglieder. Du überlegst, ob du beitreten sollst.","options":["Ich frage mich, woran man erkennen würde, dass ich in geistige Unfreiheit gerate, und prüfe, ob die Gruppe genau diese Schritte von mir verlangt.","Ich zähle die begeisterten Erfolgsberichte der Mitglieder und prüfe, ob viele übereinstimmen; je mehr es sind, desto sicherer ist die Gruppe.","Ich frage die Mitglieder, ob sie sich frei fühlen, und prüfe, ob alle einhellig zustimmen; dann halte ich die Gruppe für unbedenklich.","Ich stelle mir die versprochene Erleuchtung konkret vor und prüfe, ob sich dieses Gefühl echt anfühlt und mir langfristig guttun würde."],"correctIndex":0,"explanation":"Wer nur fragt, wie der versprochene Weg zum Ziel führt, bleibt im Erzählrahmen der Gruppe. Die umgekehrte Frage ist schärfer: Was müsste ich tun, um garantiert in geistiger Unfreiheit zu landen? Typische Antworten sind das kritische Denken aufgeben, sich von anderen Informationsquellen abschneiden, eine Person als unfehlbar akzeptieren und das eigene Vermögen übertragen. Verlangt die Gruppe genau das, ist das ein starkes Warnsignal, egal wie schön ihr Versprechen klingt. Begeisterte Berichte zeigen dagegen nur Erfolgsgeschichten; die Inversion lenkt den Blick auf die Wege des Scheiterns (vgl. Überlebensirrtum). Auch einhellige Zustimmung der Mitglieder ist kein Beweis, denn sie sagt nichts über die Schritte, die die Gruppe von dir verlangt. Und ein Wohlgefühl bei der Visualisierung belegt nicht, dass die Gruppe dir guttut.","coreRule":"⚡ Frag, wie du dich garantiert in Unfreiheit bringen würdest, und prüfe, ob eine Gruppe genau diese Schritte von dir verlangt.","beleg":"Werkstück A.9 (Anwendung & Relevanz: Bei Kulten & manipulativen Systemen; Verbindungen: Überlebensirrtum)","status":"entwurf","kurz":"Wer fragt, was ihn sicher in geistige Unfreiheit führen würde, prüft die Gruppe an ihren Forderungen statt an ihrem Versprechen. Begeisterte Berichte zeigen nur Erfolgsfälle, nicht die Wege des Scheiterns.","prueffrage":"Was weißt du über Mitglieder, die die Gruppe wieder verlassen haben, und warum sie gegangen sind?","rueckmeldung":[{"option":1,"text":"Viele übereinstimmende Berichte wirken wie ein Beleg. Sie stammen aber von denen, die geblieben und zufrieden sind; Ausgestiegene oder Gescheiterte kommen in der Werbung nicht vor. Mehr Berichte machen die Auswahl nicht aussagekräftiger."},{"option":2,"text":"Mitglieder zu fragen, klingt nach direkter Information aus erster Hand. Auch einhellige Zustimmung sagt aber nichts darüber, was die Gruppe von dir verlangt; wer drin ist, kann sich frei fühlen und trotzdem in Abhängigkeit geraten sein."},{"option":3,"text":"Auf die langfristige Wirkung für dich zu achten, ist sinnvoll. Ein gutes Gefühl bei der Vorstellung der Erleuchtung bleibt aber im Rahmen des Versprechens und sagt nichts darüber, was die Gruppe tatsächlich von dir fordert."}],"familie":"vom-scheitern-her-denken","fertigkeit":"F4","quellen":[{"typ":"doi","kurz":"Van Vleck, E. B. (1916): Current Tendencies of Mathematical Research. Bulletin of the American Mathematical Society 23(1), 1–13","oeffentlich":true,"doi":"10.1090/S0002-9904-1916-02863-1","seite":"S. 3","abruf":"2026-10-04"},{"typ":"literatur","kurz":"Lifton, R. J. (1961): Thought Reform and the Psychology of Totalism (Kap. 22)","oeffentlich":false}],"thema":"Zusammenleben"},{"id":"qx-a1-045","clusterId":"A","werkstueckRef":"A.10","stufe":1,"question":"In einer Debatte über Homeoffice sagt Jana: „Wer Homeoffice will, möchte doch nur den ganzen Tag im Schlafanzug auf dem Sofa liegen und nichts leisten.“ Anschließend widerlegt sie diese Behauptung ausführlich. Ihr Gegenüber Murat zuckt nur mit den Schultern. Warum ändert Janas Widerlegung an der Frage nach dem Homeoffice kaum etwas?","options":["Sie hat eine verzerrte, leicht angreifbare Version der Gegenposition widerlegt, nicht die Position, die Murat tatsächlich vertritt.","Sie hat zu ausführlich argumentiert, und Zuhörer halten lange Widerlegungen automatisch für weniger glaubwürdig.","Sie hat Murats Position zu freundlich zusammengefasst, sodass er aus Höflichkeit nicht mehr widersprechen kann.","Sie hat ihre eigene Position nicht belegt, und deshalb gilt Murats Position als bewiesen."],"correctIndex":0,"explanation":"Wer eine Karikatur der Gegenposition besiegt, hat über die eigentliche Position nichts gezeigt. Janas Widerlegung trifft nur die Schlafanzug-Version, nicht Murats mögliche Gründe wie Zeitersparnis, konzentriertes Arbeiten oder Vereinbarkeit mit Familie. Ein Sieg zählt erst, wenn die stärkste, fairste Fassung der Gegenseite standhält. Erst dann hat man die Idee wirklich geprüft und nicht nur eine bequeme Attrappe. Die andere Richtung kann nicht das Problem sein: Eine faire Zusammenfassung entwaffnet niemanden aus Höflichkeit, sie macht die Kritik erst aussagekräftig. Länge und Beweislast ändern daran nichts: Eine lange Widerlegung der falschen Zielscheibe bleibt wertlos, und eine fehlende Begründung auf einer Seite beweist die andere nicht.","coreRule":"⚡ Nur die stärkste Version einer Idee zu besiegen, ist ein Sieg – einen Strohmann zu besiegen, beweist nichts.","quote":"","quoteLabel":"","beleg":"Werkstück A.10 (Kontext & Tiefe)","status":"entwurf","scenario":"","kurz":"Jana hat nur die Schlafanzug-Karikatur widerlegt, nicht Murats mögliche Gründe wie Zeitersparnis oder Familie. Ein Sieg über eine bequeme Attrappe sagt nichts über die eigentliche Position; erst ihre stärkste, fairste Fassung zählt.","prueffrage":"Wer hat die Schlafanzug-Behauptung in die Debatte gebracht, und was hat Murat selbst dazu gesagt?","rueckmeldung":[{"option":1,"text":"Eine Widerlegung wird nicht schwächer, weil sie lang ist. Entscheidend ist, was sie trifft: Auch die ausführlichste Widerlegung bleibt wertlos, wenn sie das falsche Ziel hat."},{"option":2,"text":"Die Richtung stimmt nicht: Jana hat Murats Position nicht freundlich, sondern verzerrt dargestellt. Und eine faire Zusammenfassung entwaffnet niemanden aus Höflichkeit, sie macht Kritik erst aussagekräftig."},{"option":3,"text":"Belege für die eigene Position sind wichtig, aber aus einer fehlenden Begründung auf der einen Seite folgt nicht, dass die andere Seite bewiesen ist. Das Problem liegt darin, was Jana überhaupt widerlegt hat."}],"familie":"fair-wiedergeben","fertigkeit":"F3","quellen":[{"typ":"url","kurz":"3 Quarks Daily (23.05.2013): Daniel Dennett's seven tools for thinking – Auszug aus Dennett 2013, zuerst The Guardian, Abschn. „Respect your opponent“","oeffentlich":true,"url":"https://3quarksdaily.com/?p=18487","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Dennett, D. C. (2013): Intuition Pumps and Other Tools for Thinking","oeffentlich":false}],"thema":"Zusammenleben"},{"id":"qx-a1-046","clusterId":"A","werkstueckRef":"A.10","stufe":2,"question":"Welches Vorgehen ist am sinnvollsten, um Jana fair und trotzdem wirksam zu widersprechen?","options":["Zuerst Janas Position so genau und stark wiedergeben, dass sie zustimmt; dann Gemeinsamkeiten nennen und was du von ihr gelernt hast; erst danach deine Kritik äußern.","Zuerst deine eigene Position darlegen; dann Schwächen von Janas Position nennen; zum Schluss Gemeinsamkeiten betonen und ihre Sicht kurz zusammenfassen.","Zuerst Gemeinsamkeiten auflisten; dann sofort deine Kritik an Janas Position äußern; zum Schluss ihre Sicht kurz zusammenfassen.","Zuerst Kritik an der schwächsten Stelle ihrer Position üben; dann ihre Sicht wiedergeben; zum Schluss Gemeinsamkeiten und Gelerntes erwähnen."],"correctIndex":0,"explanation":"Wer die Gegenposition erst in ihrer stärksten Form wiedergibt und sich bestätigen lässt, zwingt sich selbst zum echten Verstehen. Danach trifft die Kritik die tatsächliche Position und nicht eine Karikatur. Wer eine schwache Version widerlegt, hat nichts erreicht; wer die stärkste Version widerlegt, hat die Idee wirklich geprüft. Außerdem hört ein Gegenüber, das sich fair behandelt fühlt, der Kritik eher zu. Die Reihenfolge ist: verstehen und fair wiedergeben, Übereinstimmungen benennen, Gelerntes würdigen, erst dann widersprechen. Diese Abfolge ist als „Rapoports Regeln“ bekannt.","coreRule":"⚡ Erst verstehen und würdigen, dann widersprechen.","beleg":"Werkstück A.10 (Kontext & Tiefe: Rapoports Regeln)","status":"entwurf","scenario":"In einer Gesprächsrunde vertritt Jana die Ansicht, innerorts solle überall Tempo 30 gelten. Du hältst das für überzogen und willst ihr widersprechen, ohne dass sie sich missverstanden fühlt.","kurz":"Wer Janas Position zuerst so stark wiedergibt, dass sie zustimmt, kritisiert danach ihre tatsächliche Position und keine Karikatur. Außerdem hört ein Gegenüber, das sich fair behandelt fühlt, der Kritik eher zu.","prueffrage":"Wie geht Jana vermutlich mit deinen Einwänden um, wenn sie den Eindruck hat, du hättest ihre Sicht gar nicht verstanden?","rueckmeldung":[{"option":1,"text":"Die eigene Sicht zuerst zu klären, wirkt effizient, und Gemeinsamkeiten am Ende sind ein guter Abschluss. Jana hat aber nie bestätigt, dass du sie richtig verstanden hast, und fühlt sich daher eher übergangen."},{"option":2,"text":"Gemeinsamkeiten zum Einstieg schaffen ein gutes Klima. Dann folgt jedoch sofort die Kritik, ohne dass Janas Sicht in ihrer stärksten Form wiedergegeben und von ihr bestätigt wurde. So bleibt offen, ob du ihre tatsächliche Position triffst."},{"option":3,"text":"Gleich die schwächste Stelle anzugreifen, wirkt zielgerichtet. So prüfst du aber nicht die stärkste Fassung ihrer Position, und Jana dürfte sich vom ersten Satz an angegriffen fühlen. Ihre Sicht erst danach wiederzugeben, kommt zu spät."}],"familie":"fair-wiedergeben","fertigkeit":"F3","quellen":[{"typ":"url","kurz":"3 Quarks Daily (23.05.2013): Daniel Dennett's seven tools for thinking – Auszug aus Dennett 2013, zuerst The Guardian, Abschn. „Respect your opponent“","oeffentlich":true,"url":"https://3quarksdaily.com/?p=18487","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Rapoport, A. (1960): Fights, Games, and Debates","oeffentlich":false}],"thema":"Zusammenleben"},{"id":"qx-a1-047","clusterId":"A","werkstueckRef":"A.10","stufe":3,"question":"Was ist an dieser Schlussfolgerung falsch?","scenario":"Eine Bekannte meint: „Wer fair diskutieren will, muss die Position seines Gegenübers erst in ihrer stärksten Form darstellen, bevor er sie kritisiert. Also muss er das auch bei der Behauptung tun, 2 + 2 sei 5, und bei Propaganda, die gezielt Falschinformationen verbreitet.“","options":["Sie wendet eine Regel für Gespräche mit gutem Willen und Vernunft auch dort an, wo diese Voraussetzungen fehlen.","Sie verwechselt Fairness mit Höflichkeit und übersieht, dass es in jeder Debatte vor allem ums Gewinnen geht.","Sie unterstellt, dass man die Position des Gegenübers verstehen kann, bevor man sie überhaupt kritisiert hat.","Sie übersieht, dass man eine Position nur dann fair darstellen darf, wenn die Gegenseite dasselbe auch tut."],"correctIndex":0,"explanation":"Absurde oder gefährliche Thesen muss man nicht als legitim behandeln und deshalb auch nicht in ihrer „stärksten Version“ konstruieren, etwa die Behauptung, 2 + 2 sei 5. Die Regel, eine Gegenposition erst in ihrer stärksten Form darzustellen, gilt für Debatten, in denen ein Minimum an gutem Willen und Rationalität auf der Gegenseite angenommen werden kann. Bei reiner Propaganda oder bösartiger Desinformation fehlt diese Grundlage. Dort können andere Werkzeuge, etwa das klare Benennen der rhetorischen Taktiken, wirksamer sein. Der Fehlschluss liegt also darin, eine Regel auszudehnen, ohne zu prüfen, ob ihre Voraussetzungen erfüllt sind.","coreRule":"⚡ Eine Regel gilt nur, solange ihre Voraussetzungen erfüllt sind: Die stärkste Version einer Position zu formulieren setzt guten Willen voraus.","beleg":"Werkstück A.10 (Der Kipppunkt)","status":"entwurf","kurz":"Die Regel, eine Gegenposition erst in ihrer stärksten Form darzustellen, setzt ein Minimum an gutem Willen und Rationalität voraus. Bei „2 + 2 = 5“ oder gezielter Propaganda fehlt das; wer die Regel trotzdem anwendet, dehnt sie ohne Prüfung ihrer Voraussetzungen aus.","prueffrage":"Was bezweckt jemand, der gezielt Falschinformationen verbreitet, mit seinen Behauptungen?","rueckmeldung":[{"option":1,"text":"Dass in Debatten manchmal das Siegenwollen überwiegt, stimmt. Verallgemeinern lässt sich das nicht, und Fairness dient meist dem Verstehen. Der Fehler liegt woanders: Die Regel wird auf Fälle ausgedehnt, in denen ihre Voraussetzungen fehlen."},{"option":2,"text":"Diese Annahme steckt zwar in der Regel, ist aber kein Fehler: Eine Position zu verstehen, bevor man sie kritisiert, ist gerade ihr Sinn. Fragwürdig ist, dass die Regel auch dort gelten soll, wo ihre Voraussetzungen fehlen."},{"option":3,"text":"Gegenseitigkeit hilft oft, ist aber keine Bedingung: Man kann eine Position auch fair darstellen, wenn die Gegenseite es nicht tut. Entscheidend ist, ob ein Minimum an gutem Willen und Rationalität vorhanden ist, nicht ob der andere nachzieht."}],"familie":"fair-wiedergeben","fertigkeit":"F3","quellen":[{"typ":"url","kurz":"3 Quarks Daily (23.05.2013): Daniel Dennett's seven tools for thinking – Auszug aus Dennett 2013, zuerst The Guardian","oeffentlich":true,"url":"https://3quarksdaily.com/?p=18487","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Dennett, D. C. (2013): Intuition Pumps and Other Tools for Thinking","oeffentlich":false}],"thema":"Zusammenleben"},{"id":"qx-a1-048","clusterId":"A","werkstueckRef":"A.10","stufe":4,"question":"Welche Eröffnung ist der beste erste Schritt, bevor du deine Kritik äußerst?","scenario":"Dein Onkel schwört auf Homöopathie. Du hältst ihre Wirksamkeit für nicht belegt, willst ihn aber nicht gleich vor den Kopf stoßen. Du überlegst, wie du das Gespräch beginnst, damit er dir wirklich zuhört und du seine Position nicht zur Karikatur machst.","options":["„Homöopathie ist wissenschaftlich widerlegt, dazu gibt es genug Studien. Wir können also gleich zum nächsten Thema übergehen, ohne weiter darüber zu reden.“","„Du hast recht, die Schulmedizin kann nicht alles. Dann ist Homöopathie bestimmt genauso wirksam, und wir müssen da nichts weiter prüfen.“","„Du misstraust der oft unpersönlichen Medizin mit ihren starken Nebenwirkungen und suchst eine sanfte Methode, die dir Kontrolle und Fürsorge gibt. Habe ich dich da richtig verstanden?“","„Du glaubst also ernsthaft, dass ein paar Zuckerkügelchen eine Erkältung heilen können, und gibst dafür auch noch bereitwillig Geld aus?“"],"correctIndex":2,"explanation":"Die Eröffnung gibt die Gründe und Bedürfnisse des Onkels so fair und stark wieder, dass er zustimmen kann, und lädt ausdrücklich zur Bestätigung ein. Erst danach hat Kritik Gewicht, denn wer sich verstanden fühlt, hört eher zu, und wer die stärkste Fassung einer Position prüft, widerlegt wirklich etwas und nicht bloß eine Karikatur. Wer das Gespräch mit „widerlegt, nächstes Thema“ abwürgt, prüft die Position gar nicht erst, und der Onkel fühlt sich abgetan. Die spöttische Rückfrage („Du glaubst also ernsthaft …?“) verzerrt dagegen seine Haltung zur Karikatur und zielt auf die Person statt auf ihre Gründe: ein Strohmann. Pauschale Zustimmung wiederum ist kein Verstehen, sondern ein Rückzug, denn sie gibt die eigene Prüfung auf; eine faire Wiedergabe ist gerade keine Zustimmung, sondern die Grundlage einer ehrlichen Widerlegung.","coreRule":"⚡ Gib die Position des anderen so wieder, dass er „genau“ sagt, ohne ihr damit zuzustimmen. Erst dann kritisiere.","beleg":"Werkstück A.10 (Anwendung & Relevanz: Im Dialog mit Anhängern von Pseudomedizin; Red Flags)","status":"entwurf","kurz":"Wer die Gründe des Onkels so wiedergibt, dass er zustimmen kann, schafft die Grundlage dafür, dass er der Kritik zuhört und dass sie seine stärkste Position trifft statt einer Karikatur. Verzerren, Abwürgen oder bloßes Zustimmen verfehlt das.","prueffrage":"Wie reagiert dein Onkel vermutlich, wenn er sich schon durch deinen ersten Satz belächelt oder abgewiesen fühlt?","rueckmeldung":[{"option":0,"text":"Die Studienlage spricht tatsächlich gegen eine Wirkung über Placebo hinaus. Mit dem Abwürgen erfährst du aber nie, was deinen Onkel überzeugt, und er fühlt sich abgetan statt gehört. So wird nichts widerlegt, nur ein Gespräch beendet."},{"option":1,"text":"Dass die Schulmedizin Grenzen hat, stimmt. Daraus folgt aber nicht, dass Homöopathie wirkt. Mit der Zustimmung gibst du deine eigene Prüfung auf; verstehen heißt nicht, der Kritik zu entsagen."},{"option":3,"text":"Dass Globuli oft keinen nachweisbaren Wirkstoff enthalten, trifft zu. Der spöttische Ton macht aus der Haltung deines Onkels aber eine Karikatur und unterstellt ihm Naivität: ein Angriff auf die Person statt Auseinandersetzung mit seinen Gründen."}],"familie":"fair-wiedergeben","fertigkeit":"F3","quellen":[{"typ":"url","kurz":"3 Quarks Daily (23.05.2013): Daniel Dennett's seven tools for thinking – Auszug aus Dennett 2013, zuerst The Guardian, Abschn. „Respect your opponent“","oeffentlich":true,"url":"https://3quarksdaily.com/?p=18487","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Rapoport, A. (1960): Fights, Games, and Debates","oeffentlich":false}],"thema":"Gesundheit"},{"id":"qx-a1-049","clusterId":"A","werkstueckRef":"A.11","stufe":1,"question":"Was ist an Peters Schluss am problematischsten?","scenario":"Dein Team hat einen Plan ohne eine einzige Gegenstimme beschlossen. Peter fasst zusammen: „Alle sind dafür, niemand hat einen Einwand gebracht. Also wissen wir: Der Plan hat keine ernsthaften Schwächen.“","options":["Er behandelt das Fehlen geäußerter Einwände als Beweis, dass keine Schwächen existieren, obwohl der Wunsch nach Harmonie berechtigte Einwände unterdrücken kann.","Er schließt aus der Zustimmung von Menschen auf die Qualität des Plans, obwohl nur Fachleute mit einschlägiger Erfahrung die Qualität eines Plans beurteilen können.","Er verlässt sich auf die Gruppe statt auf Einzelne, obwohl Entscheidungen in Teams grundsätzlich schlechter ausfallen als Entscheidungen einer einzelnen Person.","Er zieht seinen Schluss zu früh, obwohl sich Schwächen eines Plans immer erst nach seiner Umsetzung zeigen und vorher gar nicht erkennbar sind."],"correctIndex":0,"explanation":"Dass niemand widerspricht, zeigt nur, dass niemand widersprochen hat, nicht, dass es nichts einzuwenden gäbe. Wo der Wunsch nach Harmonie stark ist, kann er auch berechtigte Einwände unterdrücken: Wer Zweifel hat, schweigt womöglich, weil Kritik als persönlicher Angriff oder Illoyalität gelten könnte, und sieht ringsum nur Zustimmung. Einstimmigkeit ist deshalb kein Beleg für einen guten Plan, sondern kann ein Alarmsignal für Gruppendenken sein. Ein mögliches Gegenmittel ist, Widerspruch ausdrücklich zu verlangen, etwa durch einen bestellten Teufelsanwalt; in einem Experiment von Nemeth, Brown und Rogers (2001) regte echter Widerspruch allerdings mehr Lösungen an als jede geprüfte Form des bestellten Teufelsanwalts, bei der Güte allein war kein Unterschied gesichert. Dass Zustimmung allein wenig beweist, heißt nicht, dass Teams grundsätzlich schlechter entscheiden oder dass Schwächen erst nach der Umsetzung erkennbar wären.","coreRule":"⚡ Schweigen ist kein Beweis für Zustimmung, und Einstimmigkeit ist kein Beweis für Qualität: Wo niemand widerspricht, muss jemand ausdrücklich den Auftrag zum Widerspruch bekommen.","beleg":"Werkstück A.11 (Kontext & Tiefe; Red Flags)","status":"entwurf","kurz":"Dass niemand widersprochen hat, zeigt nur das Schweigen, nicht, dass der Plan keine Schwächen hat. Wer Zweifel hat, äußert sie womöglich nicht, um die Harmonie zu wahren, und sieht dann nur Zustimmung.","prueffrage":"Hat vor der Abstimmung jemand ausdrücklich nach Einwänden oder Schwachstellen gefragt?","rueckmeldung":[{"option":1,"text":"Zustimmung allein sagt tatsächlich wenig über die Qualität eines Plans. Dass nur Fachleute einen Plan beurteilen könnten, geht aber zu weit; der Fehler liegt darin, aus fehlenden Einwänden auf fehlende Schwächen zu schließen."},{"option":2,"text":"Gruppendenken ist ein echtes Risiko, doch Teams entscheiden nicht grundsätzlich schlechter als Einzelne. Peters Fehler liegt nicht darin, dass er auf eine Gruppe baut, sondern dass er Schweigen mit Schwächenfreiheit gleichsetzt."},{"option":3,"text":"Schwächen sind nicht erst nach der Umsetzung erkennbar: Ein Plan lässt sich vorher kritisch prüfen, etwa durch ausdrücklich verlangten Widerspruch. Peters Problem ist nicht der Zeitpunkt, sondern dass er fehlende Einwände für eine Prüfung hält."}],"familie":"schweigen-ist-keine-zustimmung","fertigkeit":"F2","quellen":[{"typ":"literatur","kurz":"Janis, I. L. (1972): Victims of Groupthink","oeffentlich":false},{"typ":"doi","kurz":"Esser, J. K. (1998): Alive and Well after 25 Years: A Review of Groupthink Research. OBHDP 73(2–3), 116–141","oeffentlich":false,"doi":"10.1006/obhd.1998.2758"}],"thema":"Zusammenleben"},{"id":"qx-a1-050","clusterId":"A","werkstueckRef":"A.11","stufe":2,"question":"Was ist der beste Weg, die Entscheidung vor der Unterschrift zu prüfen?","scenario":"Du hast ein Jobangebot in einer anderen Stadt und willst es annehmen. Freunde und Familie gratulieren dir begeistert, niemand äußert Bedenken. Du möchtest sichergehen, dass die Entscheidung gut ist, bevor du unterschreibst.","options":["Du fragst weitere Freunde und Familienmitglieder nach ihrer Meinung, denn je einhelliger die Zustimmung ausfällt, desto verlässlicher ist die Entscheidung.","Du stellst eine Liste aller Gründe zusammen, die für den Umzug sprechen, damit du bei aufkommenden Zweifeln darauf zurückgreifen kannst.","Du schläfst eine Nacht darüber und verwirfst jeden Einwand, der dir am nächsten Morgen nicht mehr einfällt.","Du nimmst dir eine feste Zeit und listest jeden erdenklichen Grund auf, warum die Entscheidung scheitern könnte, und prüfst danach, welche dieser Gründe tragen."],"correctIndex":3,"explanation":"Einhellige Zustimmung ist kein Beleg für eine gute Entscheidung: Wer gratuliert, will sich mitfreuen und die Stimmung nicht trüben, deshalb bleiben Bedenken oft unausgesprochen. Wer nur Gründe dafür sammelt, bestätigt sich selbst; wer Einwände nach kurzem Überschlafen verwirft, prüft sie nicht auf ihr Gewicht. Gezielt nach Schwächen zu suchen heißt dagegen, vor einer großen Entscheidung bewusst die Rolle des Advocatus Diaboli einzunehmen und jeden erdenklichen Grund aufzulisten, warum sie scheitern könnte. Danach werden die Einwände geprüft: Tragen sie, beseitigst du die Schwäche oder verwirfst den Plan; tragen sie nicht, entscheidest du mit mehr Sicherheit. Die Kritik soll die Idee stärken oder aussortieren, nicht endlos zerreden.","coreRule":"⚡ Bevor du dich festlegst, gib dir den Auftrag, deine eigene Entscheidung zu widerlegen.","beleg":"Werkstück A.11 (Anwendung & Relevanz: Im Alltag; Der Kipppunkt)","status":"entwurf","kurz":"Wer gezielt nach Gründen für ein Scheitern sucht und diese Einwände danach auf ihr Gewicht prüft, deckt Schwächen auf, die Zuspruch und eine reine Pro-Liste verdecken. Einhellige Zustimmung kann sogar bloß aus dem Wunsch nach Harmonie entstehen.","prueffrage":"Wer würde dir offen widersprechen, wenn er Bedenken hätte, und was würde er dabei riskieren?","rueckmeldung":[{"option":0,"text":"Weitere Meinungen einzuholen kann nützlich sein, wenn sie unabhängig und kritisch sind. Mehr Zustimmung aus demselben Umfeld kann aber auch nur zeigen, dass niemand die Harmonie stören will. Einhelligkeit ist kein Beleg für eine gute Entscheidung."},{"option":1,"text":"Eine Liste der Pro-Gründe hilft, die eigenen Motive zu klären. Sie sucht aber nur nach Bestätigung und kann keine Schwäche aufdecken, die du noch gar nicht gesehen hast."},{"option":2,"text":"Abstand tut Entscheidungen oft gut. Dass dir ein Einwand am nächsten Morgen nicht mehr einfällt, sagt aber nichts über sein Gewicht. Ein Einwand ist nicht erledigt, nur weil er vergessen wurde."}],"familie":"gegenbeleg-suchen","fertigkeit":"F5","quellen":[{"typ":"url","kurz":"Lord, C. G.; Lepper, M. R.; Preston, E. (1984): Considering the opposite: a corrective strategy for social judgment. JPSP 47(6), 1231–1243 (Abstract, PubMed)","oeffentlich":true,"doi":"10.1037//0022-3514.47.6.1231","url":"https://pubmed.ncbi.nlm.nih.gov/6527215/","abruf":"2026-10-12"},{"typ":"url","kurz":"Behavioral Scientist (Schlitz, I., 10.07.2018): Stop Playing Devil's Advocate, and Other Advice for Better Decision Making (Interview mit Charlan Nemeth)","oeffentlich":true,"url":"https://behavioralscientist.org/stop-playing-devils-advocate-and-other-advice-for-better-decision-making/","abruf":"2026-10-12"}],"thema":"Zusammenleben"},{"id":"qx-a1-051","clusterId":"A","werkstueckRef":"A.11","stufe":3,"question":"Wie schätzt du die Aussage der Geschäftsführerin ein?","scenario":"In einer Firma wurde nach einem teuren Fehlentscheid beschlossen, dass in jeder Sitzung reihum ein Teammitglied den „Teufelsanwalt“ spielt und ausdrücklich die Gegenposition zur Mehrheitsmeinung vertritt. Nach einigen Wochen meint die Geschäftsführerin: „Damit ist das Problem des fehlenden Widerspruchs gelöst.“ In einem Versuch mit Vierergruppen, die über einen Urlaubsplan berieten, hatte sich Folgendes gezeigt: Ein vorgegebener Widerspruch wirkte unterschiedlich, je nachdem, ob die Person ihn als echte Überzeugung vorbrachte oder als zugewiesene Rolle spielte.","options":["Sie ist zu optimistisch: Ein zugewiesener Widerspruch kann ein nützliches Hilfsmittel sein, doch echter Widerspruch von jemandem, der wirklich abweicht, ist ihm in der Wirkung auf die Lösungen überlegen.","Sie ist berechtigt: Ein zugewiesener Widerspruch ist beliebter als der eines echten Abweichlers, deshalb löst er den Konflikt auf und führt zu besseren Lösungen.","Sie ist berechtigt: Die Art des Widerspruchs spielt keine Rolle, entscheidend ist allein, dass die Gruppe überhaupt Gegenargumente hört.","Sie ist zu pessimistisch: Ein gespielter Gegenredner regt die Gruppe zuverlässig dazu an, offen über andere Positionen nachzudenken, solange er die Gegenposition glaubwürdig vorträgt."],"correctIndex":0,"explanation":"Die Behauptung „Problem gelöst“ ist ein Sprung von „es gibt jetzt eine Rolle“ zu „es gibt jetzt wirksamen Widerspruch“. Genau das hat ein kleiner Versuch mit 94 Studentinnen in Vierergruppen geprüft: Nach echtem Widerspruch nannten die Teilnehmerinnen mehr Lösungen als nach jeder Form des bestellten Teufelsanwalts, und auch ein Maß aus Zahl und Güte fiel zugunsten des echten Widerspruchs aus; bei der Güte allein war kein Unterschied gesichert. Beliebter als ein echter Abweichler war der Rollenspieler nicht, und die Diskussion mit ihm wurde als ebenso konfliktreich erlebt. In einer Vorstudie regte der gespielte Gegenredner vor allem Gedanken an, die die Ausgangsposition untermauerten, nicht solche über andere Positionen. Du darfst die Rolle also als Hilfsmittel schätzen, aber nicht darauf vertrauen, dass sie echten Widerspruch ersetzt.","coreRule":"⚡ Eine gespielte Gegenrede ersetzt keinen echten Widerspruch. Sie ist ein Hilfsmittel, kein Heilmittel.","beleg":"Werkstück A.11 (Kontext & Tiefe; Der Kipppunkt); Fn. ga-nemeth (Nemeth, Brown, Rogers 2001, European Journal of Social Psychology 31(6), S. 707–720)","status":"entwurf","kurz":"„Problem gelöst“ springt von „es gibt jetzt eine Rolle“ zu „es gibt wirksamen Widerspruch“. Im Versuch war echter Widerspruch dem bestellten überlegen; die Rolle kann helfen, ersetzt ihn aber nicht.","prueffrage":"Was lässt sich in den Sitzungen beobachten, das zeigt, dass der Widerspruch wirklich etwas verändert hat?","rueckmeldung":[{"option":1,"text":"Ein bestellter Gegenredner wirkt, als brächte er weniger Streit. Im Versuch war er aber nicht beliebter als ein echter Abweichler, die Diskussion galt als ebenso konfliktreich, und echter Widerspruch schnitt bei den Lösungen besser ab."},{"option":2,"text":"Gegenargumente sind an sich wichtig. Doch die Art des Widerspruchs spielte im Versuch eine Rolle: Echter Widerspruch war jeder Form des bestellten Teufelsanwalts überlegen, auch wenn der Unterschied bei der Güte allein nicht gesichert war."},{"option":3,"text":"Ein glaubwürdig vorgetragener Gegenpart wirkt, als würde er zum Umdenken anregen. In einer Vorstudie regte der gespielte Gegenredner aber vor allem Gedanken an, die die Ausgangsposition stützten, nicht solche über andere Positionen."}],"familie":"gegenbeleg-suchen","fertigkeit":"F5","quellen":[{"typ":"doi","kurz":"Nemeth, C.; Brown, K.; Rogers, J. (2001): Devil's advocate versus authentic dissent: stimulating quantity and quality. European Journal of Social Psychology 31(6), 707–720","oeffentlich":false,"doi":"10.1002/ejsp.58"},{"typ":"url","kurz":"Behavioral Scientist (Schlitz, I., 10.07.2018): Stop Playing Devil's Advocate, and Other Advice for Better Decision Making (Interview mit Charlan Nemeth)","oeffentlich":true,"url":"https://behavioralscientist.org/stop-playing-devils-advocate-and-other-advice-for-better-decision-making/","abruf":"2026-10-12"}],"thema":"Zusammenleben"},{"id":"qx-a1-052","clusterId":"A","werkstueckRef":"A.11","stufe":4,"question":"Wie solltest du diese Behauptung einordnen?","scenario":"Im Netz heißt es: „Seit Johannes Paul II. 1983 die Prüfung durch den Advocatus Diaboli bei Heiligsprechungen entmachtet hat, explodierten die Heiligsprechungen – der Beweis, dass diese Rolle funktioniert hat.“ Belegt ist: Er sprach in seinem Pontifikat 482 Menschen heilig, mehr als seine Vorgänger der vorangegangenen fünf Jahrhunderte zusammen. Zugleich wurde mit derselben Reform ein Großteil der Ermittlungsarbeit auf die Ortsbistümer verlagert, und er setzte sich persönlich stark für Heiligsprechungen ein.","options":["Der Beweis ist erbracht: Die Rolle wurde geschwächt, und die Zahl der Heiligsprechungen stieg danach, also hing das eine am anderen, denn zeitliche Nähe genügt als Nachweis.","Die Zahlen sind belegt, aber andere Ursachen bleiben offen; solange sie nicht ausgeschlossen sind, ist die Aussage nur eine Vermutung und kein Beweis.","Die Behauptung ist widerlegt: Nach der Reform stieg die Zahl der Heiligsprechungen nicht, die Angabe von 482 Fällen ist nicht belegt.","Der Zusammenhang ist gesichert, aber umgekehrt: Wegen der vielen Heiligsprechungen wurde die Rolle geschwächt, nicht andersherum."],"correctIndex":1,"explanation":"Die Zahl ist gut belegt und der zeitliche Zusammenfall ebenfalls. Daraus folgt aber noch keine Ursache: Dieselbe Reform hat auch die Ermittlungsarbeit auf die Ortsbistümer verlagert, und der Papst setzte sich persönlich für Heiligsprechungen ein. Jede dieser Erklärungen kommt als Mitursache in Frage; ob und wie stark, ist unter Kirchenhistorikern umstritten. Wer den Anstieg als Beweis für die Wirkung der Rolle ausgibt, zieht aus einer Korrelation einen Kausalschluss und übergeht konkurrierende Erklärungen. Auch die Umkehrung (die vielen Heiligsprechungen hätten die Schwächung der Rolle bewirkt) ist unbelegt; die Zahl selbst zu bestreiten wäre falsch, denn sie ist gut dokumentiert. Redlich ist es, die Zahl anzuerkennen und den Schluss offen zu lassen, bis andere Erklärungen geprüft sind.","coreRule":"⚡ Zeitliches Zusammenfallen heißt nicht, dass das eine das andere bewirkte – auch bei gut belegten Zahlen.","beleg":"Werkstück A.11 (Kontext & Tiefe); Fn. ga-jp2 (Johannes Paul II., Divinus Perfectionis Magister, 25.1.1983, Nr. 10 und 13; Bigalke 2025, S. 106)","status":"entwurf","kurz":"Zahl und zeitlicher Zusammenfall sind gut belegt, eine Ursache folgt daraus aber nicht: Dieselbe Reform verlagerte einen Großteil der Ermittlungen auf die Bistümer, und der Papst warb selbst für Heiligsprechungen. Solange das offen ist, bleibt der Schluss eine Vermutung.","prueffrage":"Was davon ist belegt, und was behauptet nur der Beitrag im Netz?","rueckmeldung":[{"option":0,"text":"Dass die Zahl nach der Reform stieg, stimmt. Das Nacheinander allein belegt aber noch keine Ursache: Dieselbe Reform verlagerte einen Großteil der Ermittlungsarbeit, und der Papst trieb Heiligsprechungen selbst voran."},{"option":2,"text":"Die 482 Heiligsprechungen sind gut dokumentiert, die Zahl lässt sich nicht bestreiten. Angreifbar ist nicht sie, sondern der Schluss, der aus ihr auf die Wirkung der Rolle gezogen wird."},{"option":3,"text":"Eine umgekehrte Wirkrichtung in Betracht zu ziehen, ist oft klug. Hier ist sie aber ebenso wenig gesichert wie die ursprüngliche Behauptung, und die anderen Erklärungen bleiben genauso offen."}],"familie":"korrelation-und-ursache","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Pew Research Center (Lipka, M.; Townsend, T., 24.04.2014): Papal saints: Once a given, now extremely rare","oeffentlich":true,"url":"https://www.pewresearch.org/short-reads/2014/04/24/papal-saints-once-a-given-now-extremely-rare/","abruf":"2026-10-12"},{"typ":"url","kurz":"Johannes Paul II. (1983): Apostolische Konstitution Divinus Perfectionis Magister, 25.01.1983 (engl. Fassung, vatican.va)","oeffentlich":true,"url":"https://www.vatican.va/content/john-paul-ii/en/apost_constitutions/documents/hf_jp-ii_apc_25011983_divinus-perfectionis-magister.html","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Bigalke, B., in: Vitanova-Kerber, V.; Zander, H. (Hg.) (2025): Esoteric Catholicism. Berlin: De Gruyter","oeffentlich":false}],"thema":"Geschichte und Wissenschaft"}]`);export{t as n,n as t};